window.LERN_CONTENT={"generated":"2026-06-12T18:47:15.497Z","topics":[{"id":"buch","title":"Buch (Schularbeit)","icon":"📖","phase":1,"order":0,"subtabs":[{"id":"cond","title":"Conditionals (S. 31)"},{"id":"mod","title":"Modal Verbs (S. 57)"},{"id":"rep","title":"Reported Speech (S. 89)"},{"id":"mix","title":"Mixed Tenses (S. 126–127)"}],"birkenbihl":[{"id":"buch_t1","title":"Conditionals – Beispielsätze aus dem Buch","sub":"cond","sentences":[{"id":"buch_t1_s01","en":"If I have the money, I will buy an electric car.","decode":[["If","wenn"],["I","ich"],["have","habe"],["the","das"],["money,","Geld,"],["I","ich"],["will buy","werde-kaufen"],["an","ein"],["electric","elektrisches"],["car.","Auto."]],"de":"Wenn ich das Geld habe, werde ich ein Elektroauto kaufen."},{"id":"buch_t1_s02","en":"If the president were here, he would tell us what to do.","decode":[["If","wenn"],["the","der"],["president","Präsident"],["were","wäre"],["here,","hier,"],["he","er"],["would tell","würde-sagen"],["us","uns"],["what","was"],["to do.","zu tun."]],"de":"Wenn der Präsident hier wäre, würde er uns sagen, was zu tun ist."},{"id":"buch_t1_s03","en":"If the gunman had come through the garden, he would have left some footprints.","decode":[["If","wenn"],["the","der"],["gunman","bewaffnete-Mann"],["had come","gekommen-wäre"],["through","durch"],["the","den"],["garden,","Garten,"],["he","er"],["would have left","hätte-hinterlassen"],["some","einige"],["footprints.","Fußspuren."]],"de":"Wäre der Täter durch den Garten gekommen, hätte er Fußspuren hinterlassen."}]},{"id":"buch_t2","title":"Modal Verbs – Beispielsätze aus dem Buch","sub":"mod","sentences":[{"id":"buch_t2_s01","en":"In parks, dogs must be kept on a lead.","decode":[["In","in"],["parks,","Parks,"],["dogs","Hunde"],["must","müssen"],["be kept","gehalten-werden"],["on","an"],["a","einer"],["lead.","Leine."]],"de":"In Parks müssen Hunde an der Leine geführt werden."},{"id":"buch_t2_s02","en":"When Joe was younger, he could swim pretty fast.","decode":[["When","als"],["Joe","Joe"],["was","war"],["younger,","jünger,"],["he","er"],["could","konnte"],["swim","schwimmen"],["pretty","ziemlich"],["fast.","schnell."]],"de":"Als Joe jünger war, konnte er ziemlich schnell schwimmen."},{"id":"buch_t2_s03","en":"Pat has been able to play the piano for five years.","decode":[["Pat","Pat"],["has been able to","kann-schon (Ersatzform)"],["play","spielen"],["the","das"],["piano","Klavier"],["for","seit"],["five","fünf"],["years.","Jahren."]],"de":"Pat kann seit fünf Jahren Klavier spielen."}]},{"id":"buch_t3","title":"Reported Speech – Beispielsätze aus dem Buch","sub":"rep","sentences":[{"id":"buch_t3_s01","en":"Tom said to me that he would wait for me at the train station.","decode":[["Tom","Tom"],["said","sagte"],["to me","zu-mir"],["that","dass"],["he","er"],["would wait","warten-würde"],["for me","auf-mich"],["at","am"],["the","dem"],["train station.","Bahnhof."]],"de":"(Direkt: \"I will wait for you at the train station.\") Tom sagte mir, dass er am Bahnhof auf mich warten würde."},{"id":"buch_t3_s02","en":"Pat asked me what I was going to do the next day.","decode":[["Pat","Pat"],["asked","fragte"],["me","mich"],["what","was"],["I","ich"],["was going to do","tun-würde"],["the next day.","am-nächsten-Tag."]],"de":"(Direkt: \"What are you going to do tomorrow?\") Pat fragte mich, was ich am nächsten Tag vorhätte."},{"id":"buch_t3_s03","en":"Our teacher said that the earth moves around the sun.","decode":[["Our","unser"],["teacher","Lehrer"],["said","sagte"],["that","dass"],["the","die"],["earth","Erde"],["moves","sich-bewegt"],["around","um"],["the","die"],["sun.","Sonne."]],"de":"Allgemeingültige Aussagen behalten die Present Tense – kein Backshift."}]},{"id":"buch_t4","title":"Mixed Tenses – Beispielsätze aus dem Buch","sub":"mix","sentences":[{"id":"buch_t4_s01","en":"Look! A spider is climbing up the wall.","decode":[["Look!","schau!"],["A","eine"],["spider","Spinne"],["is climbing","klettert-gerade"],["up","hinauf"],["the","die"],["wall.","Wand."]],"de":"Schau! Eine Spinne klettert gerade die Wand hinauf. (Signalwort Look! → Present Progressive)"},{"id":"buch_t4_s02","en":"Since 1990 we have been living in the country.","decode":[["Since","seit"],["1990","1990"],["we","wir"],["have been living","leben-schon"],["in","auf"],["the","dem"],["country.","Land."]],"de":"Seit 1990 leben wir auf dem Land. (since → Present Perfect (Progressive))"},{"id":"buch_t4_s03","en":"When I came home yesterday, he was sitting asleep in his armchair.","decode":[["When","als"],["I","ich"],["came","kam"],["home","nach-Hause"],["yesterday,","gestern,"],["he","er"],["was sitting","saß-gerade"],["asleep","schlafend"],["in","in"],["his","seinem"],["armchair.","Lehnstuhl."]],"de":"Als ich gestern heimkam, saß er schlafend in seinem Lehnstuhl. (Hintergrundhandlung → Past Progressive)"}]}],"exercises":[{"id":"buch_ex01","title":"Challenge 1 – Mixed Types","source":"Buch S. 31, Ziele erreicht?","type":"gap","instruction":"Setze die richtige Verbform ein (Conditional Typ 0–III, auch gemischt).","sub":"cond","questions":[{"parts":["1. If I have the money, I ",{"opts":["will buy","would buy","would have bought"],"decode":["werde-kaufen","würde-kaufen","hätte-gekauft"],"correct":0}," (buy) an electric car."],"solutionEn":"If I have the money, I will buy an electric car.","solutionDe":"Wenn ich das Geld habe, kaufe ich ein Elektroauto.","explain":"Typ I (real): if + Present → will + Infinitiv."},{"parts":["2. If I were you, I ",{"opts":["would try","will try","tried"],"decode":["würde-versuchen","werde-versuchen","versuchte"],"correct":0}," (try) to stop eating so much junk food."],"solutionEn":"If I were you, I would try to stop eating so much junk food.","solutionDe":"An deiner Stelle würde ich versuchen, weniger Junkfood zu essen.","explain":"Typ II: if + Past (were) → would + Infinitiv."},{"parts":["3. You ",{"opts":["could talk","can talk","could have talked"],"decode":["könntest-sprechen","kannst-sprechen","hättest-sprechen-können"],"correct":0}," (can) talk to Jorge if you had learnt some Spanish."],"solutionEn":"You could talk to Jorge if you had learnt some Spanish.","solutionDe":"Du könntest (jetzt) mit Jorge reden, wenn du Spanisch gelernt hättest.","explain":"Mixed Conditional: Bedingung Vergangenheit (had learnt), Folge Gegenwart → could + Infinitiv."},{"parts":["4. Phosphorus ",{"opts":["burns","is burning","will burn"],"decode":["brennt","brennt-gerade","wird-brennen"],"correct":0}," (burn) if you expose it to air."],"solutionEn":"Phosphorus burns if you expose it to air.","solutionDe":"Phosphor brennt, wenn man ihn der Luft aussetzt.","explain":"Typ 0 (Naturgesetz): Present + Present."},{"parts":["5. If it ",{"opts":["stops","stopped","will stop"],"decode":["aufhört","aufhörte","wird-aufhören"],"correct":0}," (stop) snowing, we will go skiing in the afternoon."],"solutionEn":"If it stops snowing, we will go skiing in the afternoon.","solutionDe":"Wenn es aufhört zu schneien, gehen wir am Nachmittag Skifahren.","explain":"Typ I: kein will im if-Satz!"},{"parts":["6. If the gunman ",{"opts":["had come","came","would have come"],"decode":["gekommen-wäre","kam","wäre-gekommen"],"correct":0}," (come) through the garden, he would have left some footprints."],"solutionEn":"If the gunman had come through the garden, he would have left some footprints.","solutionDe":"Wäre der Täter durch den Garten gekommen, hätte er Fußspuren hinterlassen.","explain":"Typ III: if + Past Perfect → would have + Past Participle."},{"parts":["7. If the president were here, he ",{"opts":["would tell","will tell","told"],"decode":["würde-sagen","wird-sagen","sagte"],"correct":0}," (tell) us what to do."],"solutionEn":"If the president were here, he would tell us what to do.","solutionDe":"Wäre der Präsident hier, würde er uns sagen, was zu tun ist.","explain":"Typ II: were → would + Infinitiv."},{"parts":["8. She probably would not have developed an eating disorder if her parents ",{"opts":["had supported","supported","would support"],"decode":["unterstützt-hätten","unterstützten","unterstützen-würden"],"correct":0}," (support) her more when she was a teenager."],"solutionEn":"She probably would not have developed an eating disorder if her parents had supported her more when she was a teenager.","solutionDe":"Sie hätte vermutlich keine Essstörung entwickelt, wenn ihre Eltern sie als Teenager mehr unterstützt hätten.","explain":"Typ III: would have + Partizip ↔ if + Past Perfect."},{"parts":["9. If you had not bought this big old house, you ",{"opts":["would not have to pay","do not have to pay","will not have to pay"],"decode":["müsstest-nicht-zahlen","musst-nicht-zahlen","wirst-nicht-zahlen-müssen"],"correct":0}," (not must pay) such high costs every month."],"solutionEn":"If you had not bought this big old house, you would not have to pay such high costs every month.","solutionDe":"Hättest du dieses große alte Haus nicht gekauft, müsstest du jetzt nicht jeden Monat so hohe Kosten zahlen.","explain":"Mixed: Bedingung Vergangenheit, Folge Gegenwart (every month) → would not have to pay."},{"parts":["10. We ",{"opts":["will need","would need","need"],"decode":["werden-brauchen","würden-brauchen","brauchen"],"correct":0}," (need) another planet if we go on wasting resources like that."],"solutionEn":"We will need another planet if we go on wasting resources like that.","solutionDe":"Wir werden einen zweiten Planeten brauchen, wenn wir so weiter Ressourcen verschwenden.","explain":"Typ I: if + Present (go on) → will + Infinitiv."},{"parts":["11. If the government had not passed laws to cut down emissions, more than half of our woods ",{"opts":["would have died","would die","had died"],"decode":["wären-gestorben","würden-sterben","waren-gestorben"],"correct":0}," (die) due to acid rain in the 1970s."],"solutionEn":"If the government had not passed laws to cut down emissions, more than half of our woods would have died due to acid rain in the 1970s.","solutionDe":"Hätte die Regierung keine Emissions-Gesetze beschlossen, wäre in den 1970ern mehr als die Hälfte unserer Wälder durch sauren Regen gestorben.","explain":"Typ III (Vergangenheit, 1970s): would have + Past Participle."},{"parts":["12. If the film 'The Sound of Music' were not watched all over the world, a lot fewer tourists ",{"opts":["would come","will come","would have come"],"decode":["würden-kommen","werden-kommen","wären-gekommen"],"correct":0}," (come) to Austria every year."],"solutionEn":"If the film 'The Sound of Music' were not watched all over the world, a lot fewer tourists would come to Austria every year.","solutionDe":"Würde 'The Sound of Music' nicht weltweit gesehen, kämen jedes Jahr viel weniger Touristen nach Österreich.","explain":"Typ II (unreale Gegenwart, every year): would + Infinitiv."}]},{"id":"buch_ex02","title":"Challenge 2 – Mixed Types: Situations","source":"Buch S. 31, Ziele erreicht?","type":"build","instruction":"Vervollständige den Satz sinnvoll – achte auf den richtigen Conditional-Typ. (Beispielantworten; wichtig ist die Zeitform.)","sub":"cond","questions":[{"parts":["1. Do not do that. You will get into trouble if ",{"opts":["you do it again","you did it again","you had done it again"],"decode":["du-es-wieder-tust","du-es-wieder-tätest","du-es-wieder-getan-hättest"],"correct":0},"."],"solutionEn":"You will get into trouble if you do it again.","solutionDe":"Du bekommst Ärger, wenn du das noch einmal machst.","explain":"Typ I: will im Hauptsatz → Present im if-Satz."},{"parts":["2. We cannot leave Grandpa alone anymore. If he had not dropped in at his flat this morning, ",{"opts":["nobody would have noticed that Grandpa needed help","nobody will notice that Grandpa needs help","nobody noticed that Grandpa needed help"],"decode":["niemand-hätte-bemerkt","niemand-wird-bemerken","niemand-bemerkte"],"correct":0},"."],"solutionEn":"If he had not dropped in at his flat this morning, nobody would have noticed that Grandpa needed help.","solutionDe":"Wäre er heute Früh nicht vorbeigeschaut, hätte niemand bemerkt, dass Opa Hilfe brauchte.","explain":"Typ III: if + Past Perfect → would have + Partizip."},{"parts":["3. To be honest, your suit would look a lot better if ",{"opts":["you ironed it","you iron it","you will iron it"],"decode":["du-ihn-bügeltest","du-ihn-bügelst","du-ihn-bügeln-wirst"],"correct":0},"."],"solutionEn":"Your suit would look a lot better if you ironed it.","solutionDe":"Dein Anzug sähe viel besser aus, wenn du ihn bügeln würdest.","explain":"Typ II: would im Hauptsatz → Past im if-Satz."},{"parts":["4. I think he is only after her money. He would not have proposed to her if ",{"opts":["she had not been so rich","she is not so rich","she would not be so rich"],"decode":["sie-nicht-so-reich-gewesen-wäre","sie-nicht-so-reich-ist","sie-nicht-so-reich-wäre"],"correct":0},"."],"solutionEn":"He would not have proposed to her if she had not been so rich.","solutionDe":"Er hätte ihr keinen Antrag gemacht, wenn sie nicht so reich gewesen wäre.","explain":"Typ III: would have → if + Past Perfect."},{"parts":["5. He is not fit enough for the Olympics. If he trained harder, ",{"opts":["he would have a chance to qualify","he will have a chance to qualify","he would have had a chance to qualify"],"decode":["er-hätte-eine-Chance","er-wird-eine-Chance-haben","er-hätte-eine-Chance-gehabt"],"correct":0},"."],"solutionEn":"If he trained harder, he would have a chance to qualify.","solutionDe":"Wenn er härter trainierte, hätte er eine Chance, sich zu qualifizieren.","explain":"Typ II: if + Past (trained) → would + Infinitiv."},{"parts":["6. I had to do a lot of overtime this week. I would have learnt more if ",{"opts":["I had had more time to study","I have more time to study","I would have more time to study"],"decode":["ich-mehr-Zeit-gehabt-hätte","ich-mehr-Zeit-habe","ich-mehr-Zeit-hätte"],"correct":0},"."],"solutionEn":"I would have learnt more if I had had more time to study.","solutionDe":"Ich hätte mehr gelernt, wenn ich mehr Zeit zum Lernen gehabt hätte.","explain":"Typ III: would have learnt → if + Past Perfect (had had)."},{"parts":["7. You must look after your garden better. The flowers will die if ",{"opts":["you do not water them regularly","you did not water them regularly","you will not water them"],"decode":["du-sie-nicht-regelmäßig-gießt","du-sie-nicht-gießen-würdest","du-sie-nicht-gießen-wirst"],"correct":0},"."],"solutionEn":"The flowers will die if you do not water them regularly.","solutionDe":"Die Blumen gehen ein, wenn du sie nicht regelmäßig gießt.","explain":"Typ I: will im Hauptsatz → Present im if-Satz (kein will!)."},{"parts":["8. We had to stay at home all weekend. If it had not been raining, ",{"opts":["we would have gone hiking","we would go hiking","we went hiking"],"decode":["wir-wären-wandern-gegangen","wir-würden-wandern-gehen","wir-gingen-wandern"],"correct":0},"."],"solutionEn":"If it had not been raining, we would have gone hiking.","solutionDe":"Hätte es nicht geregnet, wären wir wandern gegangen.","explain":"Typ III: if + Past Perfect → would have + Partizip."},{"parts":["9. Tom refuses to share housework. If his wife had a full-time job, ",{"opts":["he would have to help in the household","he will have to help in the household","he had to help in the household"],"decode":["er-müsste-helfen","er-wird-helfen-müssen","er-musste-helfen"],"correct":0},"."],"solutionEn":"If his wife had a full-time job, he would have to help in the household.","solutionDe":"Hätte seine Frau einen Vollzeitjob, müsste er im Haushalt helfen.","explain":"Typ II: if + Past (had) → would + Infinitiv."},{"parts":["10. Global warming is a serious problem. If the polar ice caps melt, ",{"opts":["sea levels will rise","sea levels would have risen","sea levels rose"],"decode":["der-Meeresspiegel-wird-steigen","der-Meeresspiegel-wäre-gestiegen","der-Meeresspiegel-stieg"],"correct":0},"."],"solutionEn":"If the polar ice caps melt, sea levels will rise.","solutionDe":"Wenn die Polkappen schmelzen, steigt der Meeresspiegel.","explain":"Typ I (reale Gefahr): if + Present → will + Infinitiv."}]},{"id":"buch_ex03","title":"Challenge 1 – Modale Ersatzformen","source":"Buch S. 57, Ziele erreicht?","type":"gap","instruction":"Setze die passende Form des Modalverbs ein (deutsche Vorgabe in Klammern). Achtung: Vergangenheit und Zukunft brauchen Ersatzformen!","sub":"mod","questions":[{"parts":["1. Mr Brown broke his leg last week. So he ",{"opts":["could not","must not","did not need to"],"decode":["konnte-nicht","durfte-nicht","brauchte-nicht"],"correct":0}," (nicht können) go out for seven days."],"solutionEn":"So he could not go out for seven days.","solutionDe":"Er konnte sieben Tage lang nicht hinausgehen.","explain":"nicht können in der Vergangenheit → could not / was not able to."},{"parts":["2. In parks dogs ",{"opts":["must","can","should not"],"decode":["müssen","können","sollten-nicht"],"correct":0}," (müssen) be kept on a lead."],"solutionEn":"In parks dogs must be kept on a lead.","solutionDe":"In Parks müssen Hunde an der Leine geführt werden.","explain":"müssen (Vorschrift) → must / have to."},{"parts":["3. Even experts ",{"opts":["can","must","may not"],"decode":["können","müssen","dürfen-nicht"],"correct":0}," (können) make mistakes."],"solutionEn":"Even experts can make mistakes.","solutionDe":"Sogar Experten können Fehler machen.","explain":"können (Möglichkeit) → can."},{"parts":["4. When Joe was younger, he ",{"opts":["could","can","was allowed to"],"decode":["konnte","kann","durfte"],"correct":0}," (können) swim pretty fast."],"solutionEn":"When Joe was younger, he could swim pretty fast.","solutionDe":"Als Joe jünger war, konnte er ziemlich schnell schwimmen.","explain":"können in der Vergangenheit → could."},{"parts":["5a. Son: \"",{"opts":["May","Must","Should"],"decode":["darf","muss","sollte"],"correct":0}," (dürfen) I go to the disco tonight?\" – Father: \"No, you ",{"opts":["may not","need not","could not"],"decode":["darfst-nicht","brauchst-nicht","konntest-nicht"],"correct":0}," (nicht dürfen).\""],"solutionEn":"\"May I go to the disco tonight?\" – \"No, you may not.\"","solutionDe":"„Darf ich heute Abend in die Disco?“ – „Nein, du darfst nicht.“","explain":"dürfen → may (höfliche Erlaubnisfrage)."},{"parts":["5b. Son: \"But Sue ",{"opts":["was allowed to","may","could"],"decode":["durfte","darf","konnte"],"correct":0}," (dürfen) go last week!\" – Father: \"You ",{"opts":["will be allowed to","may","were allowed to"],"decode":["wirst-dürfen","darfst","durftest"],"correct":0}," (dürfen) go when you are as old as Sue.\""],"solutionEn":"\"But Sue was allowed to go last week!\" – \"You will be allowed to go when you are as old as Sue.\"","solutionDe":"„Aber Sue durfte letzte Woche!“ – „Du wirst gehen dürfen, wenn du so alt bist wie Sue.“","explain":"dürfen hat keine Vergangenheits-/Zukunftsform → Ersatzform be allowed to (last week → was; Zukunft → will be)."},{"parts":["6. Mr Brown ",{"opts":["will not be able to","cannot","could not"],"decode":["wird-nicht-können","kann-nicht","konnte-nicht"],"correct":0}," (nicht können) help us tomorrow. He is ill. That is why we ",{"opts":["will have to","must","had to"],"decode":["werden-müssen","müssen","mussten"],"correct":0}," (müssen) work alone."],"solutionEn":"Mr Brown will not be able to help us tomorrow. That is why we will have to work alone.","solutionDe":"Mr Brown wird uns morgen nicht helfen können, deshalb werden wir allein arbeiten müssen.","explain":"Zukunft (tomorrow): können → will be able to; müssen → will have to."},{"parts":["7. You ",{"opts":["need not","must not","cannot"],"decode":["brauchst-nicht","darfst-nicht","kannst-nicht"],"correct":0}," (nicht brauchen) phone her, because she is not at home at the moment."],"solutionEn":"You need not phone her, because she is not at home at the moment.","solutionDe":"Du brauchst sie nicht anzurufen, sie ist gerade nicht zu Hause.","explain":"nicht brauchen → need not / do not need to. must not wäre ein Verbot!"},{"parts":["8. You ",{"opts":["must","may","could"],"decode":["musst","darfst","konntest"],"correct":0}," (müssen) do as I say."],"solutionEn":"You must do as I say.","solutionDe":"Du musst tun, was ich sage.","explain":"müssen (Befehl des Sprechers) → must."},{"parts":["9. Pat ",{"opts":["does not have to","must not","could not"],"decode":["muss-nicht","darf-nicht","konnte-nicht"],"correct":0}," (nicht müssen) be at home before midnight."],"solutionEn":"Pat does not have to be at home before midnight.","solutionDe":"Pat muss nicht vor Mitternacht zu Hause sein.","explain":"nicht müssen → does not have to / need not (≠ must not = Verbot!)."},{"parts":["10. Children ",{"opts":["should not","must","may"],"decode":["sollten-nicht","müssen","dürfen"],"correct":0}," (eigentlich nicht sollen) eat many sweets. Instead, they ",{"opts":["should","must not","could"],"decode":["sollten","dürfen-nicht","konnten"],"correct":0}," (sollen) eat more fruit."],"solutionEn":"Children should not eat many sweets. Instead, they should eat more fruit.","solutionDe":"Kinder sollten eigentlich nicht viele Süßigkeiten essen, sondern mehr Obst.","explain":"(nicht) sollen als Rat → should (not) / ought (not) to."},{"parts":["11. Pat ",{"opts":["can","could","must"],"decode":["kann","konnte","muss"],"correct":0}," (können) play the piano. He ",{"opts":["has been able to","can","could"],"decode":["kann-schon (Perfekt)","kann","konnte"],"correct":0}," (können) play the piano for five years."],"solutionEn":"Pat can play the piano. He has been able to play the piano for five years.","solutionDe":"Pat kann Klavier spielen – schon seit fünf Jahren.","explain":"for five years → Present Perfect: Ersatzform has been able to (can hat kein Perfekt)."},{"parts":["12. There ",{"opts":["must","can","should"],"decode":["muss","kann","sollte"],"correct":0}," (müssen) be a mistake."],"solutionEn":"There must be a mistake.","solutionDe":"Da muss ein Fehler vorliegen.","explain":"must = logische Schlussfolgerung („das muss so sein“)."},{"parts":["13. The students ",{"opts":["will have to","must","had to"],"decode":["werden-müssen","müssen","mussten"],"correct":0}," (müssen) work very hard for their A-levels next year."],"solutionEn":"The students will have to work very hard for their A-levels next year.","solutionDe":"Die Schüler werden nächstes Jahr für die Matura hart arbeiten müssen.","explain":"next year → Zukunft: müssen → will have to."},{"parts":["14. We ",{"opts":["must","may","should not"],"decode":["müssen","dürfen","sollten-nicht"],"correct":0}," (müssen) be quiet. Otherwise, we ",{"opts":["could","must","need to"],"decode":["könnten","müssen","brauchen"],"correct":0}," (können) wake up the baby, and then mother will be angry."],"solutionEn":"We must be quiet. Otherwise, we could wake up the baby.","solutionDe":"Wir müssen leise sein, sonst könnten wir das Baby aufwecken.","explain":"könnten (Möglichkeit) → could/might."},{"parts":["15. Mr Smith missed the train. He ",{"opts":["could not","cannot","must not"],"decode":["konnte-nicht","kann-nicht","darf-nicht"],"correct":0}," (nicht können) go to Vienna at seven and ",{"opts":["had to","must","will have to"],"decode":["musste","muss","wird-müssen"],"correct":0}," (müssen) wait for the nine o'clock train instead."],"solutionEn":"He could not go to Vienna at seven and had to wait for the nine o'clock train instead.","solutionDe":"Er konnte nicht um sieben nach Wien fahren und musste stattdessen auf den Neun-Uhr-Zug warten.","explain":"Vergangenheit: können → could, müssen → had to."},{"parts":["16. Alice got top marks in her A-levels. So she ",{"opts":["must","can","had to"],"decode":["muss","kann","musste"],"correct":0}," (müssen) be very clever."],"solutionEn":"So she must be very clever.","solutionDe":"Sie muss also sehr klug sein.","explain":"must = logische Schlussfolgerung aus den Topnoten."},{"parts":["17./18. She ",{"opts":["will be able to","can","could"],"decode":["wird-können","kann","konnte"],"correct":0}," (können) swim the English Channel soon. They ",{"opts":["did not need to","must not","could not"],"decode":["brauchten-nicht","dürfen-nicht","konnten-nicht"],"correct":0}," (nicht brauchen) clean everything before they started to paint."],"solutionEn":"She will be able to swim the English Channel soon. They did not need to clean everything before they started to paint.","solutionDe":"Sie wird bald den Ärmelkanal durchschwimmen können. / Sie brauchten nicht alles zu putzen, bevor sie zu malen begannen.","explain":"soon → will be able to; nicht brauchen (Vergangenheit) → did not need to / did not have to."}]},{"id":"buch_ex04","title":"Zeit- und Ortsangaben verschieben","source":"Buch S. 89, Tabelle","type":"gap","instruction":"Wie verschieben sich die Angaben in der indirekten Rede?","sub":"rep","questions":[{"parts":["now → ",{"opts":["then","that","before"],"decode":["dann/damals","jenes","davor"],"correct":0}," · today → ",{"opts":["that day","this day","the next day"],"decode":["an-jenem-Tag","an-diesem-Tag","am-nächsten-Tag"],"correct":0}," · here → ",{"opts":["there","that","then"],"decode":["dort","jenes","dann"],"correct":0}," · this → ",{"opts":["that","these","there"],"decode":["jenes","diese","dort"],"correct":0}],"solutionEn":"now → then, today → that day, here → there, this → that","solutionDe":"jetzt → damals, heute → an jenem Tag, hier → dort, dieses → jenes","explain":"In der indirekten Rede rücken Zeit- und Ortsangaben eine Stufe „weiter weg“."},{"parts":["these → ",{"opts":["those","that","them"],"decode":["jene","jenes","sie"],"correct":0}," · ago → ",{"opts":["before","later","then"],"decode":["davor","später","dann"],"correct":0}," · yesterday → ",{"opts":["the day before","two days before","that day"],"decode":["am-Tag-davor","zwei-Tage-davor","an-jenem-Tag"],"correct":0}," · last week → ",{"opts":["the week before","next week","the following week"],"decode":["die-Woche-davor","nächste-Woche","die-folgende-Woche"],"correct":0}],"solutionEn":"these → those, ago → before, yesterday → the day before, last week → the week before","solutionDe":"diese → jene, vor → davor, gestern → am Tag davor, letzte Woche → die Woche davor","explain":"ago wird zu before; yesterday/last week wandern eine Stufe zurück."},{"parts":["tomorrow → ",{"opts":["the next day","in two days' time","that day"],"decode":["am-nächsten-Tag","in-zwei-Tagen","an-jenem-Tag"],"correct":0}," · the day after tomorrow → ",{"opts":["in two days' time","the next day","two days before"],"decode":["in-zwei-Tagen","am-nächsten-Tag","zwei-Tage-davor"],"correct":0}," · the day before yesterday → ",{"opts":["two days before","the day before","before"],"decode":["zwei-Tage-davor","am-Tag-davor","davor"],"correct":0}," · next week → ",{"opts":["the following week","the week before","that week"],"decode":["die-folgende-Woche","die-Woche-davor","jene-Woche"],"correct":0}],"solutionEn":"tomorrow → the next day / the following day, the day after tomorrow → in two days' time, the day before yesterday → two days before, next week → the following week","solutionDe":"morgen → am nächsten Tag, übermorgen → in zwei Tagen, vorgestern → zwei Tage davor, nächste Woche → die folgende Woche","explain":"Zukunftsangaben → following/next-Formen."}]},{"id":"buch_ex05","title":"Your Turn 1 – Reported Speech","source":"Buch S. 89","type":"build","instruction":"Setze die direkte Rede in die indirekte Rede (Backshift, Pronomen, Zeitangaben!).","sub":"rep","questions":[{"parts":["1. Tom said to me, \"I will wait for you at the train station.\" → Tom said to me that ",{"opts":["he would wait","he will wait","I would wait"],"decode":["er-würde-warten","er-wird-warten","ich-würde-warten"],"correct":0}," for ",{"opts":["me","you","him"],"decode":["mich","dich","ihn"],"correct":0}," at the train station."],"solutionEn":"Tom said to me that he would wait for me at the train station.","solutionDe":"Tom sagte mir, dass er am Bahnhof auf mich warten würde.","explain":"will → would; I/you → he/me."},{"parts":["2. Pat asked me, \"What are you going to do tomorrow?\" → Pat asked me what ",{"opts":["I was going to do","I am going to do","you were going to do"],"decode":["ich-vorhatte","ich-vorhabe","du-vorhattest"],"correct":0}," ",{"opts":["the next day","tomorrow","that day"],"decode":["am-nächsten-Tag","morgen","an-jenem-Tag"],"correct":0},"."],"solutionEn":"Pat asked me what I was going to do the next day.","solutionDe":"Pat fragte mich, was ich am nächsten Tag vorhätte.","explain":"Frage: kein do-Umstellung, are → was, tomorrow → the next day."},{"parts":["3. Jason says, \"I want to be a famous actor when I have grown up.\" → Jason says that he ",{"opts":["wants","wanted","would want"],"decode":["will","wollte","würde-wollen"],"correct":0}," to be a famous actor when he ",{"opts":["has grown up","had grown up","grew up"],"decode":["erwachsen-ist","erwachsen-war","aufwuchs"],"correct":0},"."],"solutionEn":"Jason says that he wants to be a famous actor when he has grown up.","solutionDe":"Jason sagt, dass er ein berühmter Schauspieler werden will, wenn er groß ist.","explain":"says = Present → KEIN Backshift, nur Pronomen ändern."},{"parts":["4. Mr Smith told his secretary, \"You can phone from this office.\" → Mr Smith told his secretary that she ",{"opts":["could","can","may"],"decode":["könne/konnte","kann","darf"],"correct":0}," phone from ",{"opts":["that","this","the next"],"decode":["jenem","diesem","dem-nächsten"],"correct":0}," office."],"solutionEn":"Mr Smith told his secretary that she could phone from that office.","solutionDe":"Mr Smith sagte seiner Sekretärin, dass sie von jenem Büro aus telefonieren könne.","explain":"can → could; this → that."},{"parts":["5. Pat said, \"I am living with my parents at present, but I hope that I will have my own flat soon.\" → Pat said that he ",{"opts":["was living","is living","lived"],"decode":["wohnte-gerade","wohnt-gerade","wohnte"],"correct":0}," with his parents at that time, but he hoped that he ",{"opts":["would have","will have","had"],"decode":["haben-würde","haben-wird","hatte"],"correct":0}," his own flat soon."],"solutionEn":"Pat said that he was living with his parents at that time, but he hoped that he would have his own flat soon.","solutionDe":"Pat sagte, er wohne derzeit bei den Eltern, hoffe aber, bald eine eigene Wohnung zu haben.","explain":"am living → was living; will → would; at present → at that time."},{"parts":["6. Jill said, \"I usually take my dog for a walk after work.\" → Jill said that she usually ",{"opts":["took","takes","had taken"],"decode":["ausführte","ausführt","ausgeführt-hatte"],"correct":0}," her dog for a walk after work."],"solutionEn":"Jill said that she usually took her dog for a walk after work.","solutionDe":"Jill sagte, dass sie ihren Hund nach der Arbeit normalerweise spazieren führe.","explain":"Backshift Present → Past. Bei Gewohnheiten wäre auch „takes“ erlaubt (Regel b im Buch)."},{"parts":["7. He asked me, \"Have you ever met her before?\" → He asked me ",{"opts":["if I had ever met","if I have ever met","that I had ever met"],"decode":["ob-ich-je-getroffen-hatte","ob-ich-je-getroffen-habe","dass-ich-je-getroffen-hatte"],"correct":0}," her before."],"solutionEn":"He asked me if I had ever met her before.","solutionDe":"Er fragte mich, ob ich sie je zuvor getroffen hätte.","explain":"Ja/Nein-Frage → if/whether; Present Perfect → Past Perfect."},{"parts":["8. Mary said, \"The party last Saturday was great. We were dancing all night long.\" → Mary said that the party ",{"opts":["the Saturday before","last Saturday","next Saturday"],"decode":["am-Samstag-davor","letzten-Samstag","nächsten-Samstag"],"correct":0}," ",{"opts":["had been","was","is"],"decode":["gewesen-war","war","ist"],"correct":0}," great and that they ",{"opts":["had been dancing","were dancing","danced"],"decode":["getanzt-hatten","tanzten-gerade","tanzten"],"correct":0}," all night long."],"solutionEn":"Mary said that the party the Saturday before had been great and that they had been dancing all night long.","solutionDe":"Mary sagte, die Party am Samstag davor sei großartig gewesen und sie hätten die ganze Nacht getanzt.","explain":"last Saturday → the Saturday before; was → had been; were dancing → had been dancing."},{"parts":["9. Lucy said, \"In this village nothing ever happens.\" → Lucy said that in ",{"opts":["that","this","the"],"decode":["jenem","diesem","dem"],"correct":0}," village nothing ever ",{"opts":["happened","happens","had happened"],"decode":["passierte","passiert","passiert-war"],"correct":0},"."],"solutionEn":"Lucy said that in that village nothing ever happened.","solutionDe":"Lucy sagte, dass in jenem Dorf nie etwas passiere.","explain":"this → that; happens → happened (bei Allgemeingültigem auch „happens“ möglich)."},{"parts":["10. Tim said, \"I have missed my train. So I will be late for work today.\" → Tim said that he ",{"opts":["had missed","has missed","missed"],"decode":["verpasst-hatte","verpasst-hat","verpasste"],"correct":0}," his train, so he ",{"opts":["would be","will be","was"],"decode":["sein-würde","sein-wird","war"],"correct":0}," late for work ",{"opts":["that day","today","the day before"],"decode":["an-jenem-Tag","heute","am-Tag-davor"],"correct":0},"."],"solutionEn":"Tim said that he had missed his train, so he would be late for work that day.","solutionDe":"Tim sagte, er habe seinen Zug verpasst und werde an jenem Tag zu spät zur Arbeit kommen.","explain":"Present Perfect → Past Perfect; will → would; today → that day."},{"parts":["11. The shop assistant said, \"The sales already started last weekend.\" → The shop assistant said that the sales ",{"opts":["had already started","already started","have already started"],"decode":["schon-begonnen-hatten","schon-begannen","schon-begonnen-haben"],"correct":0}," ",{"opts":["the weekend before","last weekend","next weekend"],"decode":["am-Wochenende-davor","letztes-Wochenende","nächstes-Wochenende"],"correct":0},"."],"solutionEn":"The shop assistant said that the sales had already started the weekend before.","solutionDe":"Die Verkäuferin sagte, der Schlussverkauf habe schon am Wochenende davor begonnen.","explain":"Past → Past Perfect; last weekend → the weekend before."},{"parts":["12. Father says to John, \"Tomorrow we are going to meet Granny.\" → Father says to John that ",{"opts":["tomorrow they are going to meet","the next day they were going to meet","tomorrow we were going to meet"],"decode":["morgen-sie-treffen-werden","am-nächsten-Tag-sie-treffen-würden","morgen-wir-treffen-würden"],"correct":0}," Granny."],"solutionEn":"Father says to John that tomorrow they are going to meet Granny.","solutionDe":"Vater sagt zu John, dass sie morgen Oma treffen werden.","explain":"says = Present → kein Backshift, tomorrow bleibt tomorrow!"},{"parts":["13. Sue asked Ann, \"Did you like your last holiday?\" → Sue asked Ann ",{"opts":["if she had liked","if she liked","did she like"],"decode":["ob-sie-gemocht-hatte","ob-sie-mochte","mochte-sie"],"correct":0}," her last holiday."],"solutionEn":"Sue asked Ann if she had liked her last holiday.","solutionDe":"Sue fragte Ann, ob ihr der letzte Urlaub gefallen habe.","explain":"Frage mit did → if + Past Perfect; keine Frage-Wortstellung."},{"parts":["14. Mr Johnson asked, \"May I use your phone, sir?\" → Mr Johnson asked ",{"opts":["if he might use","if he may use","that he might use"],"decode":["ob-er-benutzen-dürfe","ob-er-benutzen-darf","dass-er-benutzen-dürfe"],"correct":0}," his phone."],"solutionEn":"Mr Johnson asked if he might use his phone.","solutionDe":"Mr Johnson fragte, ob er sein Telefon benutzen dürfe.","explain":"may → might; Anrede „sir“ fällt weg."},{"parts":["15. Father told mum, \"You do not have to water the flowers. I have already done it for you.\" → Father told mum that she ",{"opts":["did not have to","does not have to","must not"],"decode":["nicht-musste","nicht-muss","nicht-durfte"],"correct":0}," water the flowers because he ",{"opts":["had already done","has already done","already did"],"decode":["schon-erledigt-hatte","schon-erledigt-hat","schon-erledigte"],"correct":0}," it for her."],"solutionEn":"Father told mum that she did not have to water the flowers because he had already done it for her.","solutionDe":"Vater sagte Mama, sie müsse die Blumen nicht gießen, er habe es schon erledigt.","explain":"do not have to → did not have to; Present Perfect → Past Perfect."},{"parts":["16. Paul said, \"I have just bought a new car.\" → Paul said that he ",{"opts":["had just bought","has just bought","just bought"],"decode":["gerade-gekauft-hatte","gerade-gekauft-hat","gerade-kaufte"],"correct":0}," a new car."],"solutionEn":"Paul said that he had just bought a new car.","solutionDe":"Paul sagte, er habe sich gerade ein neues Auto gekauft.","explain":"Present Perfect → Past Perfect; just bleibt."}]},{"id":"buch_ex06","title":"Super Challenge 1 – Mixed Tenses (Teil 1: 1–13)","source":"Buch S. 126, Ziele erreicht?","type":"gap","instruction":"Setze die richtige Zeitform ein. Achte auf Signalwörter!","sub":"mix","questions":[{"parts":["1. Look! A spider ",{"opts":["is climbing","climbs","climbed"],"decode":["klettert-gerade","klettert","kletterte"],"correct":0}," (climb) up the wall."],"solutionEn":"Look! A spider is climbing up the wall.","solutionDe":"Schau! Eine Spinne klettert gerade die Wand hinauf.","explain":"Look! → Present Progressive (passiert gerade)."},{"parts":["2. Yesterday, while father ",{"opts":["was doing","did","has done"],"decode":["machte-gerade","machte","gemacht-hat"],"correct":0}," (do) the washing up, mother ",{"opts":["was working","worked","is working"],"decode":["arbeitete-gerade","arbeitete","arbeitet-gerade"],"correct":0}," (work) in the garden."],"solutionEn":"Yesterday, while father was doing the washing up, mother was working in the garden.","solutionDe":"Gestern, während Vater abwusch, arbeitete Mutter im Garten.","explain":"while + zwei parallele Handlungen → Past Progressive."},{"parts":["3. \"",{"opts":["Have you ever been","Were you ever","Did you ever be"],"decode":["warst-du-jemals (Perfekt)","warst-du-jemals","-"],"correct":0}," (ever, be) to New York?\" – \"Yes, I ",{"opts":["was","have been","had been"],"decode":["war","bin-gewesen","war-gewesen"],"correct":0}," (be) there last August. We ",{"opts":["stayed","have stayed","were staying"],"decode":["wohnten","haben-gewohnt","wohnten-gerade"],"correct":0}," (stay) in a luxury hotel in Manhattan for ten days.\""],"solutionEn":"\"Have you ever been to New York?\" – \"Yes, I was there last August. We stayed in a luxury hotel in Manhattan for ten days.\"","solutionDe":"„Warst du je in New York?“ – „Ja, letzten August. Wir wohnten zehn Tage in einem Luxushotel.“","explain":"ever → Present Perfect; last August (abgeschlossene Zeit) → Past Simple."},{"parts":["4. John usually ",{"opts":["gets","is getting","got"],"decode":["steht-auf","steht-gerade-auf","stand-auf"],"correct":0}," (get) up at six in the morning, but today he ",{"opts":["is not getting","does not get","did not get"],"decode":["steht-nicht-auf (heute)","steht-nicht-auf","stand-nicht-auf"],"correct":0}," (not get up) that early because it ",{"opts":["is","was","will be"],"decode":["ist","war","wird-sein"],"correct":0}," (be) Sunday."],"solutionEn":"John usually gets up at six in the morning, but today he is not getting up that early because it is Sunday.","solutionDe":"John steht normalerweise um sechs auf, aber heute nicht so früh, weil Sonntag ist.","explain":"usually → Present Simple; today (Ausnahme) → Present Progressive."},{"parts":["5. I hope the weather ",{"opts":["will be","is","would be"],"decode":["wird-sein","ist","würde-sein"],"correct":0}," (be) fine tomorrow."],"solutionEn":"I hope the weather will be fine tomorrow.","solutionDe":"Ich hoffe, das Wetter wird morgen schön.","explain":"tomorrow + Vorhersage → will-Future."},{"parts":["6. Sue ",{"opts":["was doing","did","has done"],"decode":["bügelte-gerade","bügelte","hat-gebügelt"],"correct":0}," (do) the ironing, when someone ",{"opts":["rang","was ringing","has rung"],"decode":["läutete","läutete-gerade","hat-geläutet"],"correct":0}," (ring) at the door."],"solutionEn":"Sue was doing the ironing, when someone rang at the door.","solutionDe":"Sue bügelte gerade, als jemand an der Tür läutete.","explain":"Hintergrundhandlung → Past Progressive; Unterbrechung → Past Simple."},{"parts":["7. She ",{"opts":["stood","was standing","stands"],"decode":["stand-auf","stand-gerade","steht"],"correct":0}," (stand) up, ",{"opts":["went","was going","goes"],"decode":["ging","ging-gerade","geht"],"correct":0}," (go) downstairs and ",{"opts":["opened","was opening","opens"],"decode":["öffnete","öffnete-gerade","öffnet"],"correct":0}," (open) the door."],"solutionEn":"She stood up, went downstairs and opened the door.","solutionDe":"Sie stand auf, ging hinunter und öffnete die Tür.","explain":"Handlungskette in der Vergangenheit → Past Simple."},{"parts":["8. The students ",{"opts":["have","will have","had"],"decode":["haben","werden-haben","hatten"],"correct":0}," (have) an English exam tomorrow. So they ",{"opts":["have been studying","study","studied"],"decode":["lernen-schon (Perfekt)","lernen","lernten"],"correct":0}," (study) a lot since last week."],"solutionEn":"The students have an English exam tomorrow. So they have been studying a lot since last week.","solutionDe":"Die Schüler haben morgen eine Englisch-Prüfung, darum lernen sie seit letzter Woche viel.","explain":"since → Present Perfect (Progressive); fixer Termin → Present Simple."},{"parts":["9. After Tom ",{"opts":["had finished","finished","has finished"],"decode":["beendet-hatte","beendete","beendet-hat"],"correct":0}," (finish) work, he ",{"opts":["went","had gone","goes"],"decode":["ging","gegangen-war","geht"],"correct":0}," (go) to the cinema with his friends."],"solutionEn":"After Tom had finished work, he went to the cinema with his friends.","solutionDe":"Nachdem Tom die Arbeit beendet hatte, ging er mit Freunden ins Kino.","explain":"after + Vorvergangenheit → Past Perfect, danach Past Simple."},{"parts":["10. At the moment the members of the team ",{"opts":["are listening","listen","listened"],"decode":["hören-gerade-zu","hören-zu","hörten-zu"],"correct":0}," (listen) to their boss."],"solutionEn":"At the moment the members of the team are listening to their boss.","solutionDe":"Im Moment hören die Teammitglieder ihrem Chef zu.","explain":"at the moment → Present Progressive."},{"parts":["11. Ben and Jenny ",{"opts":["moved","have moved","were moving"],"decode":["zogen","sind-gezogen","zogen-gerade"],"correct":0}," (move) to Australia in 2005. Since then they ",{"opts":["have been living","live","lived"],"decode":["leben-seitdem (Perfekt)","leben","lebten"],"correct":0}," (live) in Sydney."],"solutionEn":"Ben and Jenny moved to Australia in 2005. Since then they have been living in Sydney.","solutionDe":"Ben und Jenny zogen 2005 nach Australien. Seitdem leben sie in Sydney.","explain":"in 2005 → Past Simple; since then → Present Perfect (Progressive)."},{"parts":["12. When they ",{"opts":["were watching","watched","watch"],"decode":["schauten-gerade","schauten","schauen"],"correct":0}," (watch) TV, the telephone ",{"opts":["rang","was ringing","rings"],"decode":["läutete","läutete-gerade","läutet"],"correct":0}," (ring)."],"solutionEn":"When they were watching TV, the telephone rang.","solutionDe":"Als sie fernsahen, läutete das Telefon.","explain":"Hintergrund → Past Progressive; kurzes Ereignis → Past Simple."},{"parts":["13. Granny ",{"opts":["will be","is","was"],"decode":["wird-sein","ist","war"],"correct":0}," (be) 80 next week. \"What ",{"opts":["are you doing","do you do","did you do"],"decode":["macht-ihr (geplant)","macht-ihr","machtet-ihr"],"correct":0}," (do) in your holidays?\" – \"Well, we ",{"opts":["do not know","are not knowing","did not know"],"decode":["wissen-nicht","-","wussten-nicht"],"correct":0}," (not know)."],"solutionEn":"Granny will be 80 next week. \"What are you doing in your holidays?\" – \"Well, we do not know.\"","solutionDe":"Oma wird nächste Woche 80. „Was macht ihr in den Ferien?“ – „Wir wissen es nicht.“","explain":"next week → will; geplante Zukunft → Present Progressive; know = Zustandsverb → nie Progressive."}]},{"id":"buch_ex07","title":"Super Challenge 1 – Mixed Tenses (Teil 2: 13–22)","source":"Buch S. 126–127, Ziele erreicht?","type":"gap","instruction":"Setze die richtige Zeitform ein. Achte auf Signalwörter!","sub":"mix","questions":[{"parts":["13b. I ",{"opts":["do not want","did not want","am not wanting"],"decode":["will-nicht","wollte-nicht","-"],"correct":0}," (not want) to go to Italy again as we ",{"opts":["were","have been","had been"],"decode":["waren","sind-gewesen","waren-gewesen"],"correct":0}," (be) there last year."],"solutionEn":"I do not want to go to Italy again as we were there last year.","solutionDe":"Ich will nicht wieder nach Italien, wir waren letztes Jahr dort.","explain":"Gegenwart → Present Simple; last year → Past Simple."},{"parts":["13c. I ",{"opts":["want","wanted","will want"],"decode":["will","wollte","werde-wollen"],"correct":0}," (want) to go to Sweden or Norway, but the children ",{"opts":["loved","love","have loved"],"decode":["liebten","lieben","haben-geliebt"],"correct":0}," (love) swimming in the sea and playing on the beach. They really ",{"opts":["enjoyed","enjoy","have enjoyed"],"decode":["genossen","genießen","haben-genossen"],"correct":0}," (enjoy) it last year."],"solutionEn":"I want to go to Sweden or Norway, but the children loved swimming in the sea and playing on the beach. They really enjoyed it last year.","solutionDe":"Ich will nach Schweden oder Norwegen, aber die Kinder liebten das Schwimmen im Meer – sie haben es letztes Jahr richtig genossen.","explain":"last year → Past Simple (loved, enjoyed)."},{"parts":["13d. Therefore we ",{"opts":["have not made","did not make","do not make"],"decode":["haben-nicht-getroffen","trafen-nicht","treffen-nicht"],"correct":0}," (not make) up our minds, but I hope that we ",{"opts":["will agree","agree","agreed"],"decode":["werden-einigen","einigen","einigten"],"correct":0}," (agree) on a destination next weekend."],"solutionEn":"Therefore we have not made up our minds, but I hope that we will agree on a destination next weekend.","solutionDe":"Darum haben wir uns noch nicht entschieden, aber ich hoffe, wir einigen uns nächstes Wochenende.","explain":"Ergebnis bis jetzt → Present Perfect; next weekend → will-Future."},{"parts":["14. I promise that I ",{"opts":["will not tell","do not tell","did not tell"],"decode":["werde-nicht-erzählen","erzähle-nicht","erzählte-nicht"],"correct":0}," (not tell) anybody about the accident."],"solutionEn":"I promise that I will not tell anybody about the accident.","solutionDe":"Ich verspreche, ich erzähle niemandem von dem Unfall.","explain":"Versprechen → will-Future."},{"parts":["15. \"What time ",{"opts":["does the train leave","is the train leaving","did the train leave"],"decode":["fährt-der-Zug (Fahrplan)","fährt-der-Zug-gerade","fuhr-der-Zug"],"correct":0}," (the train, leave)?\" – \"It usually ",{"opts":["leaves","is leaving","left"],"decode":["fährt","fährt-gerade","fuhr"],"correct":0}," (leave) at 6.30, but today it ",{"opts":["is leaving","leaves","left"],"decode":["fährt (Ausnahme-heute)","fährt","fuhr"],"correct":0}," (leave) ten minutes later.\""],"solutionEn":"\"What time does the train leave?\" – \"It usually leaves at 6.30, but today it is leaving ten minutes later.\"","solutionDe":"„Wann fährt der Zug?“ – „Normalerweise um 6.30, aber heute zehn Minuten später.“","explain":"Fahrplan → Present Simple; heutige Ausnahme → Present Progressive."},{"parts":["16. When we ",{"opts":["were playing","played","play"],"decode":["spielten-gerade","spielten","spielen"],"correct":0}," (play) tennis last Sunday it suddenly ",{"opts":["started","was starting","starts"],"decode":["begann","begann-gerade","beginnt"],"correct":0}," (start) to rain."],"solutionEn":"When we were playing tennis last Sunday it suddenly started to rain.","solutionDe":"Als wir letzten Sonntag Tennis spielten, begann es plötzlich zu regnen.","explain":"Hintergrund → Past Progressive; suddenly → Past Simple."},{"parts":["17. The dancing club ",{"opts":["has","is having","had"],"decode":["hat","hat-gerade","hatte"],"correct":0}," (have) its summer party in July."],"solutionEn":"The dancing club has its summer party in July.","solutionDe":"Der Tanzklub hat sein Sommerfest im Juli.","explain":"Regelmäßiges Ereignis → Present Simple."},{"parts":["18. Our friends ",{"opts":["had organised","organised","have organised"],"decode":["organisiert-hatten","organisierten","haben-organisiert"],"correct":0}," (organise) everything before they ",{"opts":["left","had left","leave"],"decode":["abreisten","abgereist-waren","abreisen"],"correct":0}," (leave)."],"solutionEn":"Our friends had organised everything before they left.","solutionDe":"Unsere Freunde hatten alles organisiert, bevor sie abreisten.","explain":"before: Vorvergangenheit → Past Perfect, dann Past Simple."},{"parts":["19. The travel agent ",{"opts":["recommended","has recommended","recommends"],"decode":["empfahl","hat-empfohlen","empfiehlt"],"correct":0}," (recommend) the hotel which ",{"opts":["was","has been","is"],"decode":["wurde","ist-worden","wird"],"correct":0}," (be) renovated last March to the couple."],"solutionEn":"The travel agent recommended the hotel which was renovated last March to the couple.","solutionDe":"Der Reiseberater empfahl dem Paar das Hotel, das letzten März renoviert wurde.","explain":"last March → Past Simple (Passiv: was renovated)."},{"parts":["20. Sue ",{"opts":["had already finished","already finished","has already finished"],"decode":["schon-beendet-hatte","schon-beendete","hat-schon-beendet"],"correct":0}," (already, finish) her work when Jim ",{"opts":["called","had called","calls"],"decode":["anrief","angerufen-hatte","anruft"],"correct":0}," (call)."],"solutionEn":"Sue had already finished her work when Jim called.","solutionDe":"Sue hatte ihre Arbeit schon beendet, als Jim anrief.","explain":"already + Vorvergangenheit → Past Perfect."},{"parts":["21. \"Where ",{"opts":["are you spending","do you spend","did you spend"],"decode":["verbringt-ihr (geplant)","verbringt-ihr","verbrachtet-ihr"],"correct":0}," (you, spend) your next summer holidays?\" – \"My family and I ",{"opts":["are flying","fly","flew"],"decode":["fliegen (geplant)","fliegen","flogen"],"correct":0}," (fly) to Spain.\""],"solutionEn":"\"Where are you spending your next summer holidays?\" – \"My family and I are flying to Spain.\"","solutionDe":"„Wo verbringt ihr die nächsten Sommerferien?“ – „Wir fliegen nach Spanien.“","explain":"Geplante Zukunft → Present Progressive."},{"parts":["22. Granny ",{"opts":["did not tell","has not told","does not tell"],"decode":["erzählte-nicht","hat-nicht-erzählt","erzählt-nicht"],"correct":0}," (not tell) us that she ",{"opts":["had been","was","has been"],"decode":["gewesen-war","war","gewesen-ist"],"correct":0}," (be) ill last week."],"solutionEn":"Granny did not tell us that she had been ill last week.","solutionDe":"Oma erzählte uns nicht, dass sie letzte Woche krank gewesen war.","explain":"Erzählzeit Past → davor Past Perfect."}]},{"id":"buch_ex08","title":"Super Challenge 1 – Mixed Tenses (Teil 3: 23–33)","source":"Buch S. 127, Ziele erreicht?","type":"gap","instruction":"Setze die richtige Zeitform ein. Achte auf Signalwörter!","sub":"mix","questions":[{"parts":["23. Mother expects that her children ",{"opts":["will be","are","were"],"decode":["werden-sein","sind","waren"],"correct":0}," (be) at home for lunch."],"solutionEn":"Mother expects that her children will be at home for lunch.","solutionDe":"Mutter erwartet, dass die Kinder zum Mittagessen zu Hause sein werden.","explain":"Erwartung an die Zukunft → will-Future."},{"parts":["24. Many people believe that humankind ",{"opts":["will never fly","never flies","has never flown"],"decode":["wird-nie-fliegen","fliegt-nie","ist-nie-geflogen"],"correct":0}," (never, fly) to Mars."],"solutionEn":"Many people believe that humankind will never fly to Mars.","solutionDe":"Viele glauben, dass die Menschheit nie zum Mars fliegen wird.","explain":"Zukunftsglaube → will-Future."},{"parts":["25. \"",{"opts":["Did you go","Have you gone","Were you going"],"decode":["gingst-du","bist-du-gegangen","gingst-du-gerade"],"correct":0}," (you, go) to the cinema last week?\" – \"No, I ",{"opts":["did not go","have not gone","was not going"],"decode":["ging-nicht","bin-nicht-gegangen","ging-gerade-nicht"],"correct":0}," (not go) because I ",{"opts":["was","had been","have been"],"decode":["war","war-gewesen","bin-gewesen"],"correct":0}," (be) there three weeks ago.\""],"solutionEn":"\"Did you go to the cinema last week?\" – \"No, I did not go because I was there three weeks ago.\"","solutionDe":"„Warst du letzte Woche im Kino?“ – „Nein, ich war schon vor drei Wochen dort.“","explain":"last week / ago → Past Simple."},{"parts":["26. Since 1990 we ",{"opts":["have been living","live","lived"],"decode":["leben-schon (Perfekt)","leben","lebten"],"correct":0}," (live) in the country, but next year we ",{"opts":["will move","moved","have moved"],"decode":["werden-ziehen","zogen","sind-gezogen"],"correct":0}," (move) to a big city."],"solutionEn":"Since 1990 we have been living in the country, but next year we will move to a big city.","solutionDe":"Seit 1990 leben wir auf dem Land, aber nächstes Jahr ziehen wir in eine Großstadt.","explain":"since → Present Perfect (Progressive); next year → will-Future."},{"parts":["27. Many years ago John ",{"opts":["studied","has studied","was studying"],"decode":["studierte","hat-studiert","studierte-gerade"],"correct":0}," (study) Spanish and French abroad."],"solutionEn":"Many years ago John studied Spanish and French abroad.","solutionDe":"Vor vielen Jahren studierte John im Ausland Spanisch und Französisch.","explain":"ago → Past Simple."},{"parts":["28. The secretary ",{"opts":["has just finished","just finished","had just finished"],"decode":["hat-gerade-beendet","beendete-gerade","hatte-gerade-beendet"],"correct":0}," (just, finish) writing the letters."],"solutionEn":"The secretary has just finished writing the letters.","solutionDe":"Die Sekretärin hat die Briefe gerade fertig geschrieben.","explain":"just (gerade eben) → Present Perfect."},{"parts":["29. When I ",{"opts":["came","come","was coming"],"decode":["kam","komme","kam-gerade"],"correct":0}," (come) home yesterday, he ",{"opts":["was sitting","sat","is sitting"],"decode":["saß-gerade","saß","sitzt-gerade"],"correct":0}," (sit) asleep in his armchair."],"solutionEn":"When I came home yesterday, he was sitting asleep in his armchair.","solutionDe":"Als ich gestern heimkam, saß er schlafend im Lehnstuhl.","explain":"Ereignis → Past Simple; Hintergrundzustand → Past Progressive."},{"parts":["30. After the children ",{"opts":["had gone","went","have gone"],"decode":["gegangen-waren","gingen","gegangen-sind"],"correct":0}," (go) home for lunch, they ",{"opts":["had","have had","have"],"decode":["hatten","haben-gehabt","haben"],"correct":0}," (have) an appointment with the dentist."],"solutionEn":"After the children had gone home for lunch, they had an appointment with the dentist.","solutionDe":"Nachdem die Kinder zum Mittagessen heimgegangen waren, hatten sie einen Zahnarzttermin.","explain":"after → Past Perfect, Hauptsatz Past Simple."},{"parts":["31. \"Since when ",{"opts":["have you had","do you have","did you have"],"decode":["hast-du-schon","hast-du","hattest-du"],"correct":0}," (you, have) your new bike?\" – \"I ",{"opts":["bought","have bought","had bought"],"decode":["kaufte","habe-gekauft","hatte-gekauft"],"correct":0}," (buy) it last Saturday.\""],"solutionEn":"\"Since when have you had your new bike?\" – \"I bought it last Saturday.\"","solutionDe":"„Seit wann hast du dein neues Rad?“ – „Ich habe es letzten Samstag gekauft.“","explain":"since when → Present Perfect; last Saturday → Past Simple."},{"parts":["32. Jason ",{"opts":["told","tells","has told"],"decode":["erzählte","erzählt","hat-erzählt"],"correct":0}," (tell) the police that there ",{"opts":["had been","was","has been"],"decode":["gewesen-war","war","gewesen-ist"],"correct":0}," (be) an accident in Park Avenue."],"solutionEn":"Jason told the police that there had been an accident in Park Avenue.","solutionDe":"Jason erzählte der Polizei, dass es in der Park Avenue einen Unfall gegeben hatte.","explain":"Indirekte Rede nach told → Past Perfect."},{"parts":["33. Since his wife left home, Patrick ",{"opts":["has been preparing","prepares","prepared"],"decode":["bereitet-seitdem-zu (Perfekt)","bereitet-zu","bereitete-zu"],"correct":0}," (prepare) breakfast on his own."],"solutionEn":"Since his wife left home, Patrick has been preparing breakfast on his own.","solutionDe":"Seit seine Frau ausgezogen ist, macht Patrick das Frühstück allein.","explain":"since → Present Perfect Progressive (andauernd bis jetzt)."}]}]},{"id":"media","title":"(Social) Media & Fake News","icon":"📱","phase":1,"birkenbihl":[{"id":"media_t1","title":"Traditional Media and New Media","sentences":[{"id":"media_t1_s01","en":"Today, people can choose from many different ways to get information.","decode":[["Today,","heute"],["people","Menschen"],["can","können"],["choose","wählen"],["from","aus"],["many","vielen"],["different","verschiedenen"],["ways","Wegen"],["to get","zu bekommen"],["information.","Information."]],"de":"Heute können Menschen aus vielen verschiedenen Wegen wählen, um an Informationen zu kommen."},{"id":"media_t1_s02","en":"In the past, traditional media such as newspapers, radio, and television were the main sources of news.","decode":[["In the past,","früher"],["traditional","traditionelle"],["media","Medien"],["such as","wie zum Beispiel"],["newspapers,","Zeitungen,"],["radio,","Radio,"],["and","und"],["television","Fernsehen"],["were","waren"],["the","die"],["main","Haupt-"],["sources","Quellen"],["of","der"],["news.","Nachrichten."]],"de":"Früher waren traditionelle Medien wie Zeitungen, Radio und Fernsehen die Hauptquellen der Nachrichten."},{"id":"media_t1_s03","en":"However, new media, like social media and online platforms, have become more and more popular.","decode":[["However,","jedoch"],["new","neue"],["media,","Medien,"],["like","wie"],["social media","soziale Medien"],["and","und"],["online platforms,","Online-Plattformen,"],["have become","sind geworden"],["more and more","immer mehr"],["popular.","beliebt."]],"de":"Jedoch sind neue Medien wie soziale Medien und Online-Plattformen immer beliebter geworden."},{"id":"media_t1_s04","en":"One important difference between traditional and new media is the lead time.","decode":[["One","ein"],["important","wichtiger"],["difference","Unterschied"],["between","zwischen"],["traditional","traditionellen"],["and","und"],["new","neuen"],["media","Medien"],["is","ist"],["the","die"],["lead time.","Vorlaufzeit."]],"de":"Ein wichtiger Unterschied zwischen traditionellen und neuen Medien ist die Vorlaufzeit ('lead time')."},{"id":"media_t1_s05","en":"Traditional media usually needs more time to prepare news.","decode":[["Traditional","traditionelle"],["media","Medien"],["usually","normalerweise"],["needs","brauchen"],["more","mehr"],["time","Zeit"],["to prepare","um vorzubereiten"],["news.","Nachrichten."]],"de":"Traditionelle Medien brauchen normalerweise mehr Zeit, um Nachrichten vorzubereiten."},{"id":"media_t1_s06","en":"Journalists research their topics, write articles, and check the facts before publishing them.","decode":[["Journalists","Journalisten"],["research","recherchieren"],["their","ihre"],["topics,","Themen,"],["write","schreiben"],["articles,","Artikel,"],["and","und"],["check","prüfen"],["the","die"],["facts","Fakten"],["before publishing them.","bevor sie sie veröffentlichen."]],"de":"Journalisten recherchieren ihre Themen, schreiben Artikel und prüfen die Fakten, bevor sie sie veröffentlichen."},{"id":"media_t1_s07","en":"Because of this, it can take hours or even a whole day before the news can reach the audience.","decode":[["Because of this,","deswegen"],["it","es"],["can","kann"],["take","dauern"],["hours","Stunden"],["or","oder"],["even","sogar"],["a","einen"],["whole","ganzen"],["day","Tag"],["before","bevor"],["the","die"],["news","Nachrichten"],["can","können"],["reach","erreichen"],["the","das"],["audience.","Publikum."]],"de":"Deswegen kann es Stunden oder sogar einen ganzen Tag dauern, bevor die Nachrichten das Publikum erreichen können."},{"id":"media_t1_s08","en":"In contrast, new media is much faster.","decode":[["In contrast,","im Gegensatz dazu"],["new","neue"],["media","Medien"],["is","sind"],["much","viel"],["faster.","schneller."]],"de":"Im Gegensatz dazu sind neue Medien viel schneller."},{"id":"media_t1_s09","en":"People can post information online immediately, and others can read it within seconds.","decode":[["People","Menschen"],["can","können"],["post","posten"],["information","Informationen"],["online","online"],["immediately,","sofort,"],["and","und"],["others","andere"],["can","können"],["read","lesen"],["it","sie"],["within","innerhalb-von"],["seconds.","Sekunden."]],"de":"Menschen können Informationen sofort online posten, und andere können sie innerhalb von Sekunden lesen."},{"id":"media_t1_s10","en":"Another difference is the commitment to quality.","decode":[["Another","ein-weiterer"],["difference","Unterschied"],["is","ist"],["the","die"],["commitment","Verpflichtung"],["to","zur"],["quality.","Qualität."]],"de":"Ein weiterer Unterschied ist die Verpflichtung zur Qualität ('commitment to quality')."},{"id":"media_t1_s11","en":"Traditional media companies often feel responsible for giving correct and reliable information.","decode":[["Traditional","traditionelle"],["media","Medien-"],["companies","Unternehmen"],["often","oft"],["feel","fühlen-sich"],["responsible","verantwortlich"],["for giving","für das Liefern von"],["correct","korrekten"],["and","und"],["reliable","zuverlässigen"],["information.","Informationen."]],"de":"Traditionelle Medienunternehmen fühlen sich oft dafür verantwortlich, korrekte und zuverlässige Informationen zu liefern."},{"id":"media_t1_s12","en":"This is why their reports usually have a longer longevity, as people trust them over time.","decode":[["This is why","deshalb"],["their","ihre"],["reports","Berichte"],["usually","normalerweise"],["have","haben"],["a","eine"],["longer","längere"],["longevity,","Lebensdauer,"],["as","da"],["people","Menschen"],["trust","vertrauen"],["them","ihnen"],["over time.","mit der Zeit."]],"de":"Deshalb haben ihre Berichte normalerweise eine längere Lebensdauer ('longevity'), da die Menschen ihnen mit der Zeit vertrauen."},{"id":"media_t1_s13","en":"On the other hand, new media is often less controlled.","decode":[["On the other hand,","andererseits"],["new","neue"],["media","Medien"],["is","sind"],["often","oft"],["less","weniger"],["controlled.","kontrolliert."]],"de":"Andererseits sind neue Medien oft weniger kontrolliert."},{"id":"media_t1_s14","en":"Anyone can publish content, which means that some information might not be true or complete.","decode":[["Anyone","jeder"],["can","kann"],["publish","veröffentlichen"],["content,","Inhalte,"],["which means","was bedeutet"],["that","dass"],["some","manche"],["information","Informationen"],["might","könnten"],["not","nicht"],["be","sein"],["true","wahr"],["or","oder"],["complete.","vollständig."]],"de":"Jeder kann Inhalte veröffentlichen, was bedeutet, dass manche Informationen vielleicht nicht wahr oder vollständig sind."},{"id":"media_t1_s15","en":"New media also has a strong cumulative effect.","decode":[["New","neue"],["media","Medien"],["also","auch"],["has","haben"],["a","einen"],["strong","starken"],["cumulative","kumulativen"],["effect.","Effekt."]],"de":"Neue Medien haben auch einen starken kumulativen Effekt ('cumulative effect' = Anhäufungs-Effekt)."},{"id":"media_t1_s16","en":"Users can collect information from many different sources and share it with others.","decode":[["Users","Nutzer"],["can","können"],["collect","sammeln"],["information","Informationen"],["from","aus"],["many","vielen"],["different","verschiedenen"],["sources","Quellen"],["and","und"],["share","teilen"],["it","sie"],["with","mit"],["others.","anderen."]],"de":"Nutzer können Informationen aus vielen verschiedenen Quellen sammeln und sie mit anderen teilen."},{"id":"media_t1_s17","en":"This makes it easier to follow and track a story as it develops.","decode":[["This","das"],["makes","macht"],["it","es"],["easier","einfacher"],["to follow","zu verfolgen"],["and","und"],["track","nachverfolgen"],["a","eine"],["story","Geschichte"],["as","während"],["it","sie"],["develops.","sich-entwickelt."]],"de":"Das macht es einfacher, eine Geschichte zu verfolgen und nachzuverfolgen, während sie sich entwickelt."},{"id":"media_t1_s18","en":"For example, people can read updates about an event, watch videos, and discuss it online at the same time.","decode":[["For example,","zum Beispiel"],["people","Menschen"],["can","können"],["read","lesen"],["updates","Updates"],["about","über"],["an","ein"],["event,","Ereignis,"],["watch","schauen"],["videos,","Videos,"],["and","und"],["discuss","diskutieren"],["it","es"],["online","online"],["at the same time.","zur gleichen Zeit."]],"de":"Zum Beispiel können Menschen Updates über ein Ereignis lesen, Videos schauen und gleichzeitig online darüber diskutieren."},{"id":"media_t1_s19","en":"A big advantage of new media is that it is instant and interactive.","decode":[["A","ein"],["big","großer"],["advantage","Vorteil"],["of","der"],["new","neuen"],["media","Medien"],["is","ist"],["that","dass"],["it","sie"],["is","sind"],["instant","sofortig"],["and","und"],["interactive.","interaktiv."]],"de":"Ein großer Vorteil der neuen Medien ist, dass sie sofortig ('instant') und interaktiv sind."},{"id":"media_t1_s20","en":"Users can comment, like, and share content with others.","decode":[["Users","Nutzer"],["can","können"],["comment,","kommentieren,"],["like,","liken,"],["and","und"],["share","teilen"],["content","Inhalte"],["with","mit"],["others.","anderen."]],"de":"Nutzer können Inhalte kommentieren, liken und mit anderen teilen."},{"id":"media_t1_s21","en":"This creates a fast exchange of ideas.","decode":[["This","das"],["creates","erzeugt"],["a","einen"],["fast","schnellen"],["exchange","Austausch"],["of","von"],["ideas.","Ideen."]],"de":"Das erzeugt einen schnellen Austausch von Ideen."},{"id":"media_t1_s22","en":"However, this speed can also be a problem.","decode":[["However,","jedoch"],["this","diese"],["speed","Geschwindigkeit"],["can","kann"],["also","auch"],["be","sein"],["a","ein"],["problem.","Problem."]],"de":"Jedoch kann diese Geschwindigkeit auch ein Problem sein."},{"id":"media_t1_s23","en":"Because information is shared so quickly, it is sometimes not checked properly, which can lead to misunderstandings.","decode":[["Because","weil"],["information","Information"],["is shared","geteilt wird"],["so","so"],["quickly,","schnell,"],["it","sie"],["is","wird"],["sometimes","manchmal"],["not","nicht"],["checked","geprüft"],["properly,","richtig,"],["which","was"],["can","kann"],["lead to","führen zu"],["misunderstandings.","Missverständnissen."]],"de":"Weil Informationen so schnell geteilt werden, werden sie manchmal nicht richtig geprüft, was zu Missverständnissen führen kann."},{"id":"media_t1_s24","en":"Both traditional and new media have their strengths and weaknesses.","decode":[["Both","sowohl"],["traditional","traditionelle"],["and","als-auch"],["new","neue"],["media","Medien"],["have","haben"],["their","ihre"],["strengths","Stärken"],["and","und"],["weaknesses.","Schwächen."]],"de":"Sowohl traditionelle als auch neue Medien haben ihre Stärken und Schwächen."},{"id":"media_t1_s25","en":"Traditional media is often slower but more reliable, while new media is faster and more interactive.","decode":[["Traditional","traditionelle"],["media","Medien"],["is","sind"],["often","oft"],["slower","langsamer"],["but","aber"],["more reliable,","zuverlässiger,"],["while","während"],["new","neue"],["media","Medien"],["is","sind"],["faster","schneller"],["and","und"],["more interactive.","interaktiver."]],"de":"Traditionelle Medien sind oft langsamer, aber zuverlässiger, während neue Medien schneller und interaktiver sind."},{"id":"media_t1_s26","en":"For this reason, it is important to use both carefully and think critically about the information we receive.","decode":[["For this reason,","aus diesem Grund"],["it","es"],["is","ist"],["important","wichtig"],["to use","zu nutzen"],["both","beide"],["carefully","sorgfältig"],["and","und"],["think","nachzudenken"],["critically","kritisch"],["about","über"],["the","die"],["information","Informationen"],["we","wir"],["receive.","erhalten."]],"de":"Aus diesem Grund ist es wichtig, beide sorgfältig zu nutzen und kritisch über die Informationen nachzudenken, die wir erhalten."}]},{"id":"media_t2","title":"Fake News: Key Vocabulary","sentences":[{"id":"media_t2_s01","en":"Fake news is false information that looks like real news.","decode":[["Fake news","Falschnachrichten"],["is","sind"],["false","falsche"],["information","Informationen"],["that","die"],["looks like","aussehen wie"],["real","echte"],["news.","Nachrichten."]],"de":"Fake News sind falsche Informationen, die wie echte Nachrichten aussehen."},{"id":"media_t2_s02","en":"Confirmation bias means that people prefer information that confirms their existing beliefs.","decode":[["Confirmation bias","Bestätigungsfehler"],["means","bedeutet"],["that","dass"],["people","Menschen"],["prefer","bevorzugen"],["information","Informationen"],["that","die"],["confirms","bestätigen"],["their","ihre"],["existing","bestehenden"],["beliefs.","Überzeugungen."]],"de":"Confirmation Bias (Bestätigungsfehler) bedeutet, dass Menschen Informationen bevorzugen, die ihre bestehenden Überzeugungen bestätigen."},{"id":"media_t2_s03","en":"Misinformation is information that is simply wrong or misleading.","decode":[["Misinformation","Fehlinformation"],["is","ist"],["information","Information"],["that","die"],["is","ist"],["simply","einfach"],["wrong","falsch"],["or","oder"],["misleading.","irreführend."]],"de":"Misinformation ist Information, die einfach falsch oder irreführend ist."},{"id":"media_t2_s04","en":"Disinformation is false information that is spread deliberately to manipulate people.","decode":[["Disinformation","Desinformation"],["is","ist"],["false","falsche"],["information","Information"],["that","die"],["is spread","verbreitet wird"],["deliberately","absichtlich"],["to manipulate","um zu manipulieren"],["people.","Menschen."]],"de":"Desinformation ist falsche Information, die absichtlich verbreitet wird, um Menschen zu manipulieren."},{"id":"media_t2_s05","en":"In post-truth politics, emotions are more important than facts and evidence.","decode":[["In","in"],["post-truth politics,","postfaktischer Politik,"],["emotions","Emotionen"],["are","sind"],["more important","wichtiger"],["than","als"],["facts","Fakten"],["and","und"],["evidence.","Beweise."]],"de":"In der postfaktischen Politik ('post-truth politics') sind Emotionen wichtiger als Fakten und Beweise."},{"id":"media_t2_s06","en":"Propaganda is information that supports a political cause and is often biased or false.","decode":[["Propaganda","Propaganda"],["is","ist"],["information","Information"],["that","die"],["supports","unterstützt"],["a","eine"],["political","politische"],["cause","Sache"],["and","und"],["is","ist"],["often","oft"],["biased","voreingenommen"],["or","oder"],["false.","falsch."]],"de":"Propaganda ist Information, die eine politische Sache unterstützt, und sie ist oft voreingenommen oder falsch."},{"id":"media_t2_s07","en":"Satire imitates something to make fun of it, often as a political statement.","decode":[["Satire","Satire"],["imitates","imitiert"],["something","etwas"],["to make fun of","um sich lustig zu machen über"],["it,","es,"],["often","oft"],["as","als"],["a","ein"],["political","politisches"],["statement.","Statement."]],"de":"Satire imitiert etwas, um sich darüber lustig zu machen – oft als politisches Statement."},{"id":"media_t2_s08","en":"A fact-checker is a person or a system that checks facts and information on the internet.","decode":[["A","ein"],["fact-checker","Faktenprüfer"],["is","ist"],["a","eine"],["person","Person"],["or","oder"],["a","ein"],["system","System"],["that","das"],["checks","überprüft"],["facts","Fakten"],["and","und"],["information","Informationen"],["on the","im"],["internet.","Internet."]],"de":"Ein Fact-Checker (Faktenprüfer) ist eine Person oder ein System, das Fakten und Informationen im Internet überprüft."}]}],"exercises":[{"id":"media_ex01","title":"Fake News Vocabulary","source":"fake news.pdf – Aufgabe 2","type":"gap","instruction":"Wähle das passende Fake-News-Wort aus dem Dropdown. Achte auf die richtige Form (z. B. Plural).","questions":[{"parts":["Facebook and Twitter introduced ",{"opts":["fact-checkers","confirmation biases","satires"],"decode":["Fakten-Prüfer","Bestätigungs-Fehler","Satiren"],"correct":0}," to flag up any posts deemed to contain incorrect or misleading information."],"solutionEn":"Facebook and Twitter introduced fact-checkers to flag up any posts deemed to contain incorrect or misleading information.","solutionDe":"Facebook und Twitter führten Faktenprüfer ein, um Beiträge zu markieren, die falsche oder irreführende Informationen enthalten.","explain":"to factcheck / fact-checker = Fakten online überprüfen / jemand oder ein System, das das tut. Hier ist der Plural nötig (fact-checkers)."},{"parts":["In the era of ",{"opts":["propaganda","post-truth politics","fact-checkers"],"decode":["Propaganda","postfaktische Politik","Faktenprüfer"],"correct":1},", supporters of Brexit continued to refer to a potential £350 million extra per week for the health service even after this figure was widely proven to be false."],"solutionEn":"In the era of post-truth politics, supporters of Brexit continued to refer to a potential £350 million extra per week for the health service even after this figure was widely proven to be false.","solutionDe":"Im Zeitalter der postfaktischen Politik beriefen sich Brexit-Befürworter weiterhin auf mögliche 350 Millionen Pfund extra pro Woche für das Gesundheitssystem, obwohl diese Zahl längst als falsch bewiesen war.","explain":"post-truth politics = Fakten und Beweise zählen weniger als Emotionen. Genau das passiert hier: Die Zahl ist widerlegt, wird aber trotzdem weiterverwendet."},{"parts":["Ofcom threw out hundreds of complaints against Channel 4's alternative Christmas speech, which depicted a 'deepfake' Queen Elizabeth II joking about her family and dancing, saying it was clearly ",{"opts":["satirical","disinformation","propaganda"],"decode":["satirisch","Desinformation","Propaganda"],"correct":0}," and no one would have believed it was real."],"solutionEn":"Ofcom threw out hundreds of complaints against Channel 4's alternative Christmas speech, saying it was clearly satirical and no one would have believed it was real.","solutionDe":"Ofcom wies Hunderte Beschwerden gegen die alternative Weihnachtsansprache von Channel 4 (mit einer 'Deepfake'-Queen) ab, weil sie eindeutig satirisch war und niemand sie für echt gehalten hätte.","explain":"satire (Nomen) / satirical (Adjektiv) = etwas imitieren, um sich darüber lustig zu machen. Niemand sollte die Deepfake-Queen für echt halten – also Satire, keine Täuschungsabsicht. Auch das Nomen 'satire' wäre hier sprachlich möglich."},{"parts":["Due to ",{"opts":["confirmation bias","post-truth politics","satire"],"decode":["Bestätigungsfehler","postfaktische Politik","Satire"],"correct":0},", even when it is proved that information is false, people will continue to believe that it is true."],"solutionEn":"Due to confirmation bias, even when it is proved that information is false, people will continue to believe that it is true.","solutionDe":"Wegen des Bestätigungsfehlers glauben Menschen weiterhin, dass eine Information wahr ist, selbst wenn bewiesen wurde, dass sie falsch ist.","explain":"confirmation bias = die Tendenz, Informationen zu bevorzugen, die die eigene Überzeugung bestätigen – egal, ob sie wahr sind."},{"parts":["Ricky Vaughn, a social media troll, was charged with conspiring to disseminate ",{"opts":["misinformation","disinformation","satire"],"decode":["Fehlinformation (unabsichtlich falsch)","Desinformation (absichtlich täuschend)","Satire"],"correct":1}," with the intention of depriving people of their legal right to vote. His posts encouraged people to vote in the 2016 election by text or by social media posts, neither of which are legally valid ways of voting."],"solutionEn":"Ricky Vaughn was charged with conspiring to disseminate disinformation with the intention of depriving people of their legal right to vote.","solutionDe":"Ricky Vaughn wurde angeklagt, Desinformation verbreitet zu haben – mit der Absicht, Menschen ihr legales Wahlrecht zu nehmen.","explain":"'with the intention' = Absicht! Absichtlich irreführende Information = DISinformation. Misinformation ist auch falsch, aber OHNE Täuschungsabsicht."},{"parts":["Government ",{"opts":["satire","propaganda","confirmation bias"],"decode":["Satire","Propaganda","Bestätigungsfehler"],"correct":1}," was seen as a vital part of the war effort during World War 2 to increase public support for the allies of the United States and to foster hatred of the enemy."],"solutionEn":"Government propaganda was seen as a vital part of the war effort during World War 2 to increase public support for the allies of the United States and to foster hatred of the enemy.","solutionDe":"Regierungspropaganda galt im Zweiten Weltkrieg als wichtiger Teil der Kriegsanstrengungen, um die öffentliche Unterstützung für die Verbündeten der USA zu erhöhen und Hass auf den Feind zu schüren.","explain":"propaganda = Information zur Unterstützung einer politischen Sache, oft einseitig, irreführend oder falsch – klassisches Beispiel: Kriegszeiten."}]},{"id":"media_ex02","title":"Media Vocabulary: Welcher Begriff passt?","source":"media_vocabulary_worksheet.pdf – Task 1 (Match the words with their meanings)","type":"mc","instruction":"Lies die Situation und wähle den passenden Medien-Begriff aus dem Dropdown.","questions":[{"parts":["Maria heard about a new series because several of her friends kept recommending it to her in conversations. → ",{"opts":["press","word of mouth","broadcast media"],"decode":["Presse","Mundpropaganda","Rundfunkmedien (TV/Radio)"],"correct":1}],"solutionEn":"word of mouth = information spreads through personal conversations and recommendations. (Scenario T)","solutionDe":"word of mouth = Mundpropaganda: Informationen verbreiten sich durch persönliche Gespräche und Empfehlungen.","explain":"Maria erfährt von der Serie durch Empfehlungen von Freunden im Gespräch – wörtlich 'von Mund zu Mund'."},{"parts":["An elderly man prefers reading the newspaper every morning instead of using his phone for news. → ",{"opts":["print media","broadcast media","media outlets"],"decode":["Printmedien","Rundfunkmedien (TV/Radio)","Medienhäuser"],"correct":0}],"solutionEn":"print media = printed news like newspapers and magazines. (Scenario Q)","solutionDe":"print media = Printmedien: gedruckte Medien wie Zeitungen und Zeitschriften.","explain":"Zeitung auf Papier = print media. Fernsehen und Radio wären broadcast media."},{"parts":["A family watches the evening news on TV to stay updated about current events. → ",{"opts":["print media","word of mouth","broadcast media"],"decode":["Printmedien","Mundpropaganda","Rundfunkmedien (TV/Radio)"],"correct":2}],"solutionEn":"broadcast media = TV and radio. (Scenario P)","solutionDe":"broadcast media = Rundfunkmedien: Fernsehen und Radio.","explain":"to broadcast = senden/ausstrahlen. Abendnachrichten im Fernsehen = broadcast media."},{"parts":["Different news companies report the same political event, but each presents it in a slightly different way. → ",{"opts":["media outlets","echo chamber","press"],"decode":["Medienhäuser / Nachrichtenanbieter","Echokammer","Presse"],"correct":0}],"solutionEn":"media outlets = the different companies that publish news (newspapers, TV stations, news websites). (Scenario O)","solutionDe":"media outlets = Medienhäuser/Nachrichtenanbieter: die verschiedenen Unternehmen, die Nachrichten veröffentlichen.","explain":"Mehrere Nachrichten-FIRMEN berichten unterschiedlich über dasselbe Ereignis – jedes dieser Unternehmen ist ein 'media outlet'."},{"parts":["While scrolling through Instagram, Tom accidentally finds an interesting article he wasn't looking for. → ",{"opts":["to skim","to stumble upon","to cover"],"decode":["überfliegen","zufällig stoßen auf","berichten über"],"correct":1}],"solutionEn":"to stumble upon = to find something by chance, without looking for it. (Scenario E)","solutionDe":"to stumble upon = zufällig auf etwas stoßen, ohne danach zu suchen.","explain":"'accidentally finds' = zufällig finden → to stumble upon (wörtlich: darüber stolpern)."},{"parts":["Sarah quickly reads through an online article to understand the main idea without focusing on details. → ",{"opts":["to skim","to stumble upon","to cover"],"decode":["überfliegen","zufällig stoßen auf","berichten über"],"correct":0}],"solutionEn":"to skim = to read something quickly to get the main idea. (Scenario G)","solutionDe":"to skim = einen Text überfliegen, um die Hauptidee zu erfassen.","explain":"Schnell lesen, Details überspringen = skimmen. Wichtige Lesetechnik – auch für deine Schularbeit!"},{"parts":["A website spreads a completely false story about a celebrity to influence people's opinions. → ",{"opts":["soft news","clickbait","fake news"],"decode":["leichte Unterhaltungs-Nachrichten","Klickköder","Falschnachrichten"],"correct":2}],"solutionEn":"fake news = completely false stories that are presented as real news, often to influence people. (Scenario L)","solutionDe":"fake news = komplett falsche Geschichten, die wie echte Nachrichten präsentiert werden – oft, um Meinungen zu beeinflussen.","explain":"Die Geschichte ist 'completely false' und soll Meinungen beeinflussen → fake news. Clickbait will nur Klicks, soft news ist harmlose Unterhaltung."},{"parts":["A headline says: 'You won't believe what happened next!' to make people curious enough to click. → ",{"opts":["clickbait","fake news","soft news"],"decode":["Klickköder","Falschnachrichten","leichte Unterhaltungs-Nachrichten"],"correct":0}],"solutionEn":"clickbait = a sensational headline whose only goal is to make you click. (Scenario K)","solutionDe":"clickbait = Klickköder: eine reißerische Überschrift, deren einziges Ziel es ist, Klicks zu erzeugen.","explain":"'You won't believe...!' ist DIE typische Clickbait-Formel: neugierig machen → klicken."},{"parts":["Lisa notices that her social media feed only shows posts that match her opinions and interests. → ",{"opts":["algorithms","filter bubble","echo chamber"],"decode":["Algorithmen","Filterblase","Echokammer"],"correct":1}],"solutionEn":"filter bubble = you only see content that matches your own interests and opinions. (Scenario J)","solutionDe":"filter bubble = Filterblase: Du siehst nur noch Inhalte, die zu deinen eigenen Interessen und Meinungen passen.","explain":"Merkhilfe: algorithms = die Technik dahinter, filter bubble = das Ergebnis für DEINEN Feed, echo chamber = die Gruppe, in der alle gleich denken."},{"parts":["A platform decides which posts appear in your feed based on what you liked and searched before. → ",{"opts":["algorithms","filter bubble","echo chamber"],"decode":["Algorithmen","Filterblase","Echokammer"],"correct":0}],"solutionEn":"algorithms = computer programs that decide which content you see. (Scenario I)","solutionDe":"algorithms = Algorithmen: Programme, die entscheiden, welche Inhalte du siehst.","explain":"Hier ENTSCHEIDET die Plattform aktiv (basierend auf Likes und Suchverlauf) – das machen die Algorithmen. Die Filterblase ist nur die Folge davon."},{"parts":["On the bus, Anna watches 30-second videos and reads mini-posts – content that is short and easy to consume in between. → ",{"opts":["snackable content","soft news","print media"],"decode":["leicht konsumierbare Kurz-Inhalte","leichte Unterhaltungs-Nachrichten","Printmedien"],"correct":0}],"solutionEn":"snackable content = short, easy-to-consume content (like a snack). (No scenario on the worksheet – own example)","solutionDe":"snackable content = kurze, leicht konsumierbare Inhalte – wie ein Snack für zwischendurch.","explain":"Für dieses Wort gibt es im Arbeitsblatt kein Szenario (21 Wörter, nur 20 Szenarien A–T) – dieses Beispiel ist selbst erstellt. Merke: snack = kleiner Happen → Häppchen-Inhalte."},{"parts":["A news report exaggerates a story to make it more shocking and attract attention. → ",{"opts":["credible","misleading","sensational"],"decode":["glaubwürdig","irreführend","reißerisch"],"correct":2}],"solutionEn":"sensational = exaggerated and shocking in order to attract attention. (Scenario B)","solutionDe":"sensational = reißerisch: übertrieben und schockierend, um Aufmerksamkeit zu erregen.","explain":"'exaggerates' (übertreibt) + 'shocking' + 'attract attention' = sensational. misleading wäre: Es entsteht ein falscher Eindruck."},{"parts":["Before believing an article, John checks whether the source is reliable and trustworthy. → ",{"opts":["credible","sensational","misleading"],"decode":["glaubwürdig","reißerisch","irreführend"],"correct":0}],"solutionEn":"credible = believable, reliable and trustworthy. (Scenario S)","solutionDe":"credible = glaubwürdig: zuverlässig und vertrauenswürdig.","explain":"'reliable and trustworthy' ist genau die Definition von credible. John prüft die Glaubwürdigkeit der Quelle."},{"parts":["The title of an article gives a completely wrong impression of what the article is actually about. → ",{"opts":["sensational","credible","misleading"],"decode":["reißerisch","glaubwürdig","irreführend"],"correct":2}],"solutionEn":"misleading = giving a wrong impression. (Scenario A)","solutionDe":"misleading = irreführend: Es entsteht ein falscher Eindruck.","explain":"'wrong impression' = falscher Eindruck → misleading (to mislead = in die Irre führen)."},{"parts":["A student questions the information in an article instead of accepting it immediately. → ",{"opts":["critical thinking","convenience","word of mouth"],"decode":["kritisches Denken","Bequemlichkeit","Mundpropaganda"],"correct":0}],"solutionEn":"critical thinking = questioning information instead of believing it immediately. (Scenario H)","solutionDe":"critical thinking = kritisches Denken: Informationen hinterfragen, statt sie sofort zu glauben.","explain":"'questions the information' = hinterfragt die Information → kritisches Denken. Genau das fordert auch der Reading-Text am Ende."},{"parts":["In an online group, people only share and hear opinions that are similar to their own. → ",{"opts":["filter bubble","echo chamber","algorithms"],"decode":["Filterblase","Echokammer","Algorithmen"],"correct":1}],"solutionEn":"echo chamber = a group or space where people only hear opinions similar to their own. (Scenario M)","solutionDe":"echo chamber = Echokammer: eine Gruppe, in der alle nur ähnliche Meinungen teilen und hören.","explain":"Hier geht es um eine GRUPPE von Menschen (nicht um deinen persönlichen Feed) → echo chamber. Die eigene Meinung kommt wie ein Echo zurück."},{"parts":["A news story focuses on celebrity gossip rather than important political issues. → ",{"opts":["soft news","fake news","clickbait"],"decode":["leichte Unterhaltungs-Nachrichten","Falschnachrichten","Klickköder"],"correct":0}],"solutionEn":"soft news = entertaining news (gossip, lifestyle) instead of hard, important facts. (Scenario F)","solutionDe":"soft news = leichte Nachrichten: Unterhaltung (Promi-Klatsch, Lifestyle) statt wichtiger politischer Themen.","explain":"Promi-Klatsch ist nicht falsch (also keine fake news), nur leichte Unterhaltung → soft news."},{"parts":["Journalists report on a major event from different locations and perspectives. → ",{"opts":["to stumble upon","to skim","to cover"],"decode":["zufällig stoßen auf","überfliegen","berichten über"],"correct":2}],"solutionEn":"to cover (news) = to report on an event. (Scenario N)","solutionDe":"to cover (news) = über ein Ereignis berichten.","explain":"'report on a major event' = über ein Großereignis berichten → to cover. (coverage = die Berichterstattung)"},{"parts":["Reporters ask politicians difficult questions during a press conference. → ",{"opts":["press","media outlets","broadcast media"],"decode":["Presse","Medienhäuser","Rundfunkmedien (TV/Radio)"],"correct":0}],"solutionEn":"press = journalists and news organisations as an institution. (Scenario D)","solutionDe":"press = die Presse: Journalisten und Nachrichtenorganisationen als Institution.","explain":"Reporter auf einer PRESSEkonferenz = the press. Das Wort steckt schon in 'press conference'."},{"parts":["A journalist supports their article with facts, data, and reliable sources. → ",{"opts":["convenience","evidence","critical thinking"],"decode":["Bequemlichkeit","Beweise / Belege","kritisches Denken"],"correct":1}],"solutionEn":"evidence = facts, data and sources that prove something. (Scenario C)","solutionDe":"evidence = Beweise/Belege: Fakten, Daten und Quellen, die etwas belegen.","explain":"'facts, data, and reliable sources' stützen den Artikel = evidence (Belege)."},{"parts":["A student uses a news app on their phone because it allows them to check updates anytime and anywhere. → ",{"opts":["evidence","critical thinking","convenience"],"decode":["Beweise / Belege","kritisches Denken","Bequemlichkeit"],"correct":2}],"solutionEn":"convenience = something is easy and comfortable to use. (Scenario R)","solutionDe":"convenience = Bequemlichkeit/Komfort: etwas ist einfach und praktisch nutzbar.","explain":"'anytime and anywhere' = jederzeit und überall → der Vorteil ist die Bequemlichkeit (convenient = praktisch/bequem)."}]},{"id":"media_ex03","title":"Reading Comprehension: Traditional Media and New Media","source":"Reading 'Traditional Media and New Media' – Aufgaben 1–4 des Blatts + 5 Zusatzfragen","type":"mc","instruction":"Lies den Text im Bereich 'Lesen & Hören' und wähle die richtige Antwort.","questions":[{"parts":["Give two differences between traditional and new media. Which two differences are mentioned in the text? → ",{"opts":["the price and the design","the lead time and the commitment to quality","the language and the number of pictures"],"decode":["der Preis und das Design","die Vorlaufzeit und die Verpflichtung zur Qualität","die Sprache und die Anzahl der Bilder"],"correct":1}],"solutionEn":"Two differences mentioned in the text are the lead time and the commitment to quality. (The text also mentions the cumulative effect and that new media is instant and interactive.)","solutionDe":"Zwei Unterschiede aus dem Text: die Vorlaufzeit (lead time) und die Verpflichtung zur Qualität (commitment to quality). Weitere: der kumulative Effekt und 'instant and interactive'.","explain":"Der Text nennt vier Unterschiede: lead time, commitment to quality, cumulative effect, instant & interactive. In der Schularbeit reichen zwei – mit je einem Erklärungssatz."},{"parts":["What does 'lead time' mean in the text? → ",{"opts":["the time media need to prepare news before publishing","the time readers spend on an article","the time a story stays popular"],"decode":["die Zeit, die Medien brauchen, um Nachrichten vor der Veröffentlichung vorzubereiten","die Zeit, die Leser mit einem Artikel verbringen","die Zeit, die eine Geschichte beliebt bleibt"],"correct":0}],"solutionEn":"'Lead time' is the time media need to prepare news before publishing it: journalists research, write articles and check the facts.","solutionDe":"'Lead time' = Vorlaufzeit: die Zeit, die Medien brauchen, um Nachrichten vor der Veröffentlichung vorzubereiten (recherchieren, schreiben, Fakten prüfen).","explain":"Im Text: Traditionelle Medien brauchen Stunden bis einen ganzen Tag – neue Medien posten sofort ('within seconds')."},{"parts":["Why does traditional media often have greater longevity? → ",{"opts":["because newspapers are printed on strong paper","because traditional media publishes news faster than new media","because people trust their correct and reliable reports over time"],"decode":["weil Zeitungen auf festem Papier gedruckt werden","weil traditionelle Medien schneller veröffentlichen als neue Medien","weil Menschen ihren korrekten und zuverlässigen Berichten mit der Zeit vertrauen"],"correct":2}],"solutionEn":"Traditional media often has greater longevity because its reports are correct and reliable, so people trust them over time.","solutionDe":"Traditionelle Medien haben oft eine größere Langlebigkeit, weil ihre Berichte korrekt und zuverlässig sind und die Menschen ihnen deshalb mit der Zeit vertrauen.","explain":"longevity = Langlebigkeit. Das Vertrauen entsteht durch die Verpflichtung zur Qualität (commitment to quality) – nicht durch das Papier!"},{"parts":["Do you think new media is always reliable? What does the text say? → ",{"opts":["No – anyone can publish content, so information might not be true or complete","Yes – everything online is checked by fact-checkers first","Yes – new media is reliable because it is so fast"],"decode":["Nein – jeder kann Inhalte veröffentlichen, daher sind Informationen vielleicht nicht wahr oder vollständig","Ja – alles online wird zuerst von Faktenprüfern geprüft","Ja – neue Medien sind zuverlässig, weil sie so schnell sind"],"correct":0}],"solutionEn":"No. New media is often less controlled: anyone can publish content, so some information might not be true or complete. Because news is shared so quickly, it is sometimes not checked properly.","solutionDe":"Nein. Neue Medien sind oft weniger kontrolliert: Jeder kann Inhalte veröffentlichen, daher ist nicht alles wahr oder vollständig. Durch die Geschwindigkeit wird manches nicht richtig geprüft.","explain":"Aufgabe 4 ist eine Meinungsfrage – begründe mit dem Text: weniger Kontrolle, jeder kann veröffentlichen, Geschwindigkeit vor Sorgfalt → kritisch denken!"},{"parts":["Why does traditional media need a longer lead time? → ",{"opts":["because printing machines are very slow","because journalists research their topics, write articles and check the facts before publishing","because readers only want news in the morning"],"decode":["weil Druckmaschinen sehr langsam sind","weil Journalisten recherchieren, Artikel schreiben und Fakten prüfen, bevor sie veröffentlichen","weil Leser Nachrichten nur am Morgen wollen"],"correct":1}],"solutionEn":"Traditional media needs a longer lead time because journalists research their topics, write articles and check the facts before publishing them.","solutionDe":"Traditionelle Medien brauchen eine längere Vorlaufzeit, weil Journalisten ihre Themen recherchieren, Artikel schreiben und die Fakten prüfen, bevor sie veröffentlichen.","explain":"Der Qualitäts-Prozess (recherchieren → schreiben → Fakten prüfen) kostet Zeit – das ist die 'lead time'."},{"parts":["What does 'commitment to quality' mean for traditional media companies? → ",{"opts":["They feel responsible for giving correct and reliable information","They promise to be faster than new media","They only report about high-quality products"],"decode":["Sie fühlen sich verantwortlich, korrekte und zuverlässige Informationen zu liefern","Sie versprechen, schneller als neue Medien zu sein","Sie berichten nur über hochwertige Produkte"],"correct":0}],"solutionEn":"'Commitment to quality' means that traditional media companies feel responsible for giving correct and reliable information.","solutionDe":"'Commitment to quality' (Verpflichtung zur Qualität) bedeutet: Traditionelle Medienunternehmen fühlen sich verantwortlich, korrekte und zuverlässige Informationen zu liefern.","explain":"Vorsicht Falle: 'quality' meint hier die Qualität der Berichterstattung, nicht die Qualität von Produkten."},{"parts":["What does 'longevity' refer to in the text? → ",{"opts":["how long it takes to print a newspaper","how long reports stay trusted and relevant over time","how long a journalist works for a company"],"decode":["wie lange es dauert, eine Zeitung zu drucken","wie lange Berichte über die Zeit vertrauenswürdig und relevant bleiben","wie lange ein Journalist für eine Firma arbeitet"],"correct":1}],"solutionEn":"'Longevity' refers to how long reports stay trusted and relevant over time.","solutionDe":"'Longevity' (Langlebigkeit) = wie lange Berichte über die Zeit vertrauenswürdig und relevant bleiben.","explain":"Im Text: Berichte traditioneller Medien haben eine längere 'longevity', weil die Menschen ihnen mit der Zeit vertrauen."},{"parts":["What is the 'cumulative effect' of new media? → ",{"opts":["Users collect information from many different sources and share it, so a story is easier to follow as it develops","Users get more and more tired of reading the news","News articles automatically become longer every day"],"decode":["Nutzer sammeln Informationen aus vielen Quellen und teilen sie – so lässt sich eine Geschichte leichter verfolgen, während sie sich entwickelt","Nutzer werden vom Nachrichtenlesen immer müder","Nachrichtenartikel werden automatisch jeden Tag länger"],"correct":0}],"solutionEn":"The cumulative effect: users collect information from many different sources and share it with others, which makes it easier to follow and track a story as it develops.","solutionDe":"Der kumulative Effekt: Nutzer sammeln Informationen aus vielen verschiedenen Quellen und teilen sie – dadurch kann man eine Geschichte leichter verfolgen, während sie sich entwickelt.","explain":"cumulative = sich ansammelnd: Updates lesen + Videos schauen + online diskutieren – alles gleichzeitig, aus vielen Quellen."},{"parts":["Why is new media called 'instant and interactive'? → ",{"opts":["because users can comment, like and share content immediately, which creates a fast exchange of ideas","because new media deletes false information instantly","because users can play interactive games in news apps"],"decode":["weil Nutzer sofort kommentieren, liken und teilen können – das erzeugt einen schnellen Ideenaustausch","weil neue Medien falsche Informationen sofort löschen","weil Nutzer in Nachrichten-Apps interaktive Spiele spielen können"],"correct":0}],"solutionEn":"New media is instant and interactive because users can comment, like and share content immediately, which creates a fast exchange of ideas.","solutionDe":"Neue Medien sind 'instant and interactive', weil Nutzer sofort kommentieren, liken und teilen können – das erzeugt einen schnellen Austausch von Ideen.","explain":"Achtung: Diese Geschwindigkeit ist zugleich eine Schwäche – Informationen werden manchmal nicht richtig geprüft, was zu Missverständnissen führen kann."}]},{"id":"media_ex04","title":"Fake News: Verständnisfragen","source":"fake news.pdf – Aufgabe 1 (Discussion Questions, Auswahl)","type":"mc","instruction":"Wähle die beste Antwort. Diese Fragen helfen dir, in der Schularbeit über Fake News zu schreiben und zu sprechen.","questions":[{"parts":["What is fake news? → ",{"opts":["news that is boring and far too long","false or misleading information that is presented as if it were real news","any news about famous people"],"decode":["Nachrichten, die langweilig und viel zu lang sind","falsche oder irreführende Informationen, die wie echte Nachrichten präsentiert werden","alle Nachrichten über berühmte Leute"],"correct":1}],"solutionEn":"Fake news is false or misleading information that is presented as if it were real news, often spread on social media.","solutionDe":"Fake News sind falsche oder irreführende Informationen, die wie echte Nachrichten präsentiert werden – oft über soziale Medien verbreitet.","explain":"Wichtig: Fake News SEHEN AUS wie echte Nachrichten – das unterscheidet sie von Satire (will unterhalten) und von Meinungen (sind als Meinung erkennbar)."},{"parts":["Why do people believe fake news? → ",{"opts":["because of confirmation bias – fake news often confirms what people already believe","because fake news is always carefully fact-checked","because fake news only appears in serious quality newspapers"],"decode":["wegen des Bestätigungsfehlers – Fake News bestätigen oft, was Menschen ohnehin glauben","weil Fake News immer sorgfältig auf Fakten geprüft werden","weil Fake News nur in seriösen Qualitätszeitungen erscheinen"],"correct":0}],"solutionEn":"People often believe fake news because of confirmation bias: it confirms what they already believe. Emotional, sensational stories are also shared without checking.","solutionDe":"Menschen glauben Fake News oft wegen des Bestätigungsfehlers (confirmation bias): Sie bestätigen, was man ohnehin schon glaubt. Emotionale, reißerische Geschichten werden zudem ungeprüft geteilt.","explain":"Verwende in der Schularbeit das Vokabel 'confirmation bias' in deiner Antwort – das zeigt, dass du die Fachbegriffe beherrschst."},{"parts":["Why does fake news spread faster than real news? → ",{"opts":["because journalists always check it before it is shared","because it is often sensational and emotional, so people share it quickly without checking","because it is only spread by official news agencies"],"decode":["weil Journalisten sie immer prüfen, bevor sie geteilt wird","weil sie oft reißerisch und emotional ist und Menschen sie ungeprüft schnell teilen","weil sie nur von offiziellen Nachrichtenagenturen verbreitet wird"],"correct":1}],"solutionEn":"Fake news spreads faster because it is often sensational and emotional, so people share it quickly without checking it first. Algorithms then show popular posts to even more people.","solutionDe":"Fake News verbreiten sich schneller, weil sie oft reißerisch und emotional sind – Menschen teilen sie schnell, ohne sie zu prüfen. Algorithmen zeigen beliebte Beiträge dann noch mehr Menschen.","explain":"Merk-Stichwörter: sensational, emotional, clickbait, sharing without fact-checking, algorithms."},{"parts":["What effect does fake news have on society? → ",{"opts":["It makes society better informed about politics","It has no effect because nobody reads it","It can create distrust in the media and influence opinions and even elections"],"decode":["Sie informieren die Gesellschaft besser über Politik","Sie haben keine Wirkung, weil sie niemand liest","Sie können Misstrauen gegenüber Medien erzeugen und Meinungen und sogar Wahlen beeinflussen"],"correct":2}],"solutionEn":"Fake news can create distrust in the media, divide society and influence opinions and even elections.","solutionDe":"Fake News können Misstrauen gegenüber den Medien erzeugen, die Gesellschaft spalten und Meinungen und sogar Wahlen beeinflussen.","explain":"Gute Beispiele für die Schularbeit: die Brexit-Kampagne (350-Millionen-Pfund-Behauptung) oder die US-Wahl 2016."}]}]},{"id":"blog","title":"Blog Entry schreiben","icon":"✍️","phase":1,"birkenbihl":[{"id":"blog_t1","title":"Model Blog Entry: Life Without Social Media? No Way!","sentences":[{"id":"blog_t1_s01","en":"Life Without Social Media? No Way!","decode":[["Life","Leben"],["Without","ohne"],["Social Media?","soziale Medien?"],["No Way!","auf keinen Fall!"]],"de":"Leben ohne soziale Medien? Auf keinen Fall! (Das ist der 'catchy' Titel.)"},{"id":"blog_t1_s02","en":"by Alex – 12 June 2026, at 6 pm","decode":[["by","von"],["Alex","Alex"],["– 12 June 2026,","– 12. Juni 2026,"],["at 6 pm","um 18 Uhr"]],"de":"von Alex – 12. Juni 2026, 18 Uhr (Name, Datum und Uhrzeit gehören an den Anfang.)"},{"id":"blog_t1_s03","en":"Hi guys,","decode":[["Hi","hallo"],["guys,","Leute,"]],"de":"Hallo Leute! (Die informelle Anrede eröffnet die Einleitung.)"},{"id":"blog_t1_s04","en":"Have you seen Jamie's comment?","decode":[["Have","habt"],["you","ihr"],["seen","gesehen"],["Jamie's","Jamies"],["comment?","Kommentar?"]],"de":"Habt ihr Jamies Kommentar gesehen? (Persönliche Frage als Einstieg – Present Perfect.)"},{"id":"blog_t1_s05","en":"He says he can't imagine life without social media – and honestly, I totally agree with him.","decode":[["He","er"],["says","sagt"],["he","er"],["can't","kann-nicht"],["imagine","sich-vorstellen"],["life","das-Leben"],["without","ohne"],["social media –","soziale Medien –"],["and","und"],["honestly,","ehrlich-gesagt,"],["I","ich"],["totally","völlig"],["agree","stimme-zu"],["with him.","mit ihm."]],"de":"Er sagt, er kann sich ein Leben ohne soziale Medien nicht vorstellen – und ehrlich gesagt stimme ich ihm völlig zu. (Hier reagierst du direkt auf Jamies Kommentar.)"},{"id":"blog_t1_s06","en":"Social media affects young people in many ways.","decode":[["Social media","soziale Medien"],["affects","beeinflussen"],["young","junge"],["people","Menschen"],["in","auf"],["many","viele"],["ways.","Arten."]],"de":"Soziale Medien beeinflussen junge Menschen auf viele Arten. (Topic Sentence – der Hauptteil beginnt.)"},{"id":"blog_t1_s07","en":"On the one hand, it helps us stay in touch with friends, share ideas and learn new things.","decode":[["On the one hand,","einerseits"],["it","sie"],["helps","helfen"],["us","uns"],["stay in touch","in Kontakt bleiben"],["with","mit"],["friends,","Freunden,"],["share","teilen"],["ideas","Ideen"],["and","und"],["learn","lernen"],["new","neue"],["things.","Dinge."]],"de":"Einerseits helfen sie uns, mit Freunden in Kontakt zu bleiben, Ideen zu teilen und neue Dinge zu lernen. (Positive Aspekte.)"},{"id":"blog_t1_s08","en":"We can find news in seconds and even discover new hobbies.","decode":[["We","wir"],["can","können"],["find","finden"],["news","Nachrichten"],["in","in"],["seconds","Sekunden"],["and","und"],["even","sogar"],["discover","entdecken"],["new","neue"],["hobbies.","Hobbys."]],"de":"Wir können in Sekunden Nachrichten finden und sogar neue Hobbys entdecken."},{"id":"blog_t1_s09","en":"On the other hand, there are negative aspects too.","decode":[["On the other hand,","andererseits"],["there are","es gibt"],["negative","negative"],["aspects","Aspekte"],["too.","auch."]],"de":"Andererseits gibt es auch negative Aspekte. (Übergang zu den negativen Seiten.)"},{"id":"blog_t1_s10","en":"Many teenagers spend hours scrolling, compare themselves with influencers and feel stressed.","decode":[["Many","viele"],["teenagers","Teenager"],["spend","verbringen"],["hours","Stunden"],["scrolling,","mit-Scrollen,"],["compare","vergleichen"],["themselves","sich"],["with","mit"],["influencers","Influencern"],["and","und"],["feel","fühlen-sich"],["stressed.","gestresst."]],"de":"Viele Teenager verbringen Stunden mit Scrollen, vergleichen sich mit Influencern und fühlen sich gestresst."},{"id":"blog_t1_s11","en":"Fake news spreads quickly, and cyberbullying is a real problem.","decode":[["Fake news","Falschnachrichten"],["spreads","verbreiten-sich"],["quickly,","schnell,"],["and","und"],["cyberbullying","Cybermobbing"],["is","ist"],["a","ein"],["real","echtes"],["problem.","Problem."]],"de":"Fake News verbreiten sich schnell, und Cybermobbing ist ein echtes Problem."},{"id":"blog_t1_s12","en":"In my life, social media is quite important.","decode":[["In","in"],["my","meinem"],["life,","Leben,"],["social media","soziale Medien"],["is","sind"],["quite","ziemlich"],["important.","wichtig."]],"de":"In meinem Leben sind soziale Medien ziemlich wichtig. (Punkt 4 der Aufgabe: Bedeutung in deinem Leben.)"},{"id":"blog_t1_s13","en":"I use it every day to chat with my friends and to follow my favourite creators.","decode":[["I","ich"],["use","benutze"],["it","sie"],["every","jeden"],["day","Tag"],["to chat","um zu chatten"],["with","mit"],["my","meinen"],["friends","Freunden"],["and","und"],["to follow","um zu folgen"],["my","meinen"],["favourite","Lieblings-"],["creators.","Creators."]],"de":"Ich benutze sie jeden Tag, um mit meinen Freunden zu chatten und meinen Lieblings-Creators zu folgen."},{"id":"blog_t1_s14","en":"However, I try to take breaks and put my phone away when I study.","decode":[["However,","jedoch"],["I","ich"],["try","versuche"],["to take","zu machen"],["breaks","Pausen"],["and","und"],["put","legen"],["my","mein"],["phone","Handy"],["away","weg"],["when","wenn"],["I","ich"],["study.","lerne."]],"de":"Jedoch versuche ich, Pausen zu machen und mein Handy wegzulegen, wenn ich lerne."},{"id":"blog_t1_s15","en":"Summing up, social media is neither good nor bad – it depends on how we use it.","decode":[["Summing up,","zusammenfassend"],["social media","soziale Medien"],["is","sind"],["neither","weder"],["good","gut"],["nor","noch"],["bad –","schlecht –"],["it","es"],["depends on","hängt ab von"],["how","wie"],["we","wir"],["use","benutzen"],["it.","sie."]],"de":"Zusammenfassend: Soziale Medien sind weder gut noch schlecht – es hängt davon ab, wie wir sie benutzen. (Die Conclusion fasst zusammen.)"},{"id":"blog_t1_s16","en":"What do you think? Leave your comment below!","decode":[["What","was"],["do you think?","denkt ihr?"],["Leave","hinterlasst"],["your","euren"],["comment","Kommentar"],["below!","unten!"]],"de":"Was denkt ihr? Hinterlasst unten euren Kommentar! (Leser ansprechen und um Kommentare bitten – typisches Blog-Ende.)"}]}],"exercises":[{"id":"blog_ex01","title":"Blog-Struktur: die richtige Reihenfolge","source":"blog-post.pdf – Struktur und Layout","type":"order","instruction":"Baue den Aufbau eines Blog Entry zusammen: Wähle für jede Position den passenden Baustein.","questions":[{"parts":["1. Ganz oben: ",{"opts":["Title: catchy, with your name, date and time","Introduction: greeting + present the topic in an interesting way","Main body: your arguments and examples in clear paragraphs","Conclusion: sum up + ask your readers for comments"],"decode":["Titel: auffällig ('catchy'), mit Name, Datum und Uhrzeit","Einleitung: Anrede ('Hi guys') + Thema interessant vorstellen","Hauptteil: Argumente und Beispiele in klaren Absätzen","Schluss: zusammenfassen + Leser um Kommentare bitten"],"correct":0}," 2. Danach: ",{"opts":["Title: catchy, with your name, date and time","Introduction: greeting + present the topic in an interesting way","Main body: your arguments and examples in clear paragraphs","Conclusion: sum up + ask your readers for comments"],"decode":["Titel: auffällig ('catchy'), mit Name, Datum und Uhrzeit","Einleitung: Anrede ('Hi guys') + Thema interessant vorstellen","Hauptteil: Argumente und Beispiele in klaren Absätzen","Schluss: zusammenfassen + Leser um Kommentare bitten"],"correct":1}," 3. Dann: ",{"opts":["Title: catchy, with your name, date and time","Introduction: greeting + present the topic in an interesting way","Main body: your arguments and examples in clear paragraphs","Conclusion: sum up + ask your readers for comments"],"decode":["Titel: auffällig ('catchy'), mit Name, Datum und Uhrzeit","Einleitung: Anrede ('Hi guys') + Thema interessant vorstellen","Hauptteil: Argumente und Beispiele in klaren Absätzen","Schluss: zusammenfassen + Leser um Kommentare bitten"],"correct":2}," 4. Zum Schluss: ",{"opts":["Title: catchy, with your name, date and time","Introduction: greeting + present the topic in an interesting way","Main body: your arguments and examples in clear paragraphs","Conclusion: sum up + ask your readers for comments"],"decode":["Titel: auffällig ('catchy'), mit Name, Datum und Uhrzeit","Einleitung: Anrede ('Hi guys') + Thema interessant vorstellen","Hauptteil: Argumente und Beispiele in klaren Absätzen","Schluss: zusammenfassen + Leser um Kommentare bitten"],"correct":3}],"solutionEn":"Title (catchy, with name, date and time) → Introduction (greeting + interesting opening) → Main body (arguments and examples in paragraphs) → Conclusion (sum up + ask for comments).","solutionDe":"Titel (catchy, mit Name, Datum, Uhrzeit) → Einleitung (Anrede + interessanter Einstieg) → Hauptteil (Argumente und Beispiele in Absätzen) → Schluss (Zusammenfassung + um Kommentare bitten).","explain":"Ein Blog Entry hat immer diesen festen Aufbau. In der Einleitung stellst du Thema und Standpunkt vor, im Hauptteil bringst du Argumente mit Beispielen, im Schluss fasst du zusammen und sprichst die Leser an."}]},{"id":"blog_ex02","title":"Informelle Blog-Phrasen einsetzen","source":"blog-post.pdf – Einleitung, nützliche Ausdrücke, Schlussteil","type":"gap","instruction":"Wähle die passende informelle Blog-Phrase aus dem Dropdown.","questions":[{"parts":["",{"opts":["Have you ever","Did you ever","Do you ever"],"decode":["hast du jemals (Present Perfect – richtig)","tatest du jemals (passt nicht zu 'thought')","tust du jemals (passt nicht zu 'thought')"],"correct":0}," thought about how much time you spend on your phone?"],"solutionEn":"Have you ever thought about how much time you spend on your phone?","solutionDe":"Hast du jemals darüber nachgedacht, wie viel Zeit du an deinem Handy verbringst?","explain":"Persönliche Einstiegsfrage im Present Perfect: 'Have you ever + 3. Verbform (thought)'. Nach 'Did you ever' müsste die Grundform 'think' stehen – ein typischer Fehler."},{"parts":["",{"opts":["Hi guys","Dear Sir or Madam","Yours sincerely"],"decode":["hallo Leute (informell – richtig für Blogs)","sehr geehrte Damen und Herren (formeller Brief)","mit freundlichen Grüßen (Briefschluss)"],"correct":0},", today I want to share some thoughts about social media."],"solutionEn":"Hi guys, today I want to share some thoughts about social media.","solutionDe":"Hallo Leute, heute möchte ich ein paar Gedanken über soziale Medien mit euch teilen.","explain":"Ein Blog beginnt mit einer informellen Anrede wie 'Hi guys' oder 'Hi everyone' – nie mit formellen Briefformeln."},{"parts":["",{"opts":["In my opinion","After my opinion","By my opinion"],"decode":["meiner Meinung nach (richtig)","wörtlich 'nach meiner Meinung' – falsches Englisch","wörtlich 'bei meiner Meinung' – falsches Englisch"],"correct":0},", social media has more advantages than disadvantages."],"solutionEn":"In my opinion, social media has more advantages than disadvantages.","solutionDe":"Meiner Meinung nach haben soziale Medien mehr Vorteile als Nachteile.","explain":"'In my opinion' ist die richtige Meinungs-Phrase. 'After my opinion' ist ein klassischer Übersetzungsfehler aus dem Deutschen."},{"parts":["",{"opts":["On the one hand","On the one side","At the one hand"],"decode":["einerseits (richtig)","unüblich im Englischen","falsche Präposition (at)"],"correct":0},", social media connects people all over the world. ",{"opts":["On the other hand","On the other side","At the other hand"],"decode":["andererseits (richtig)","unüblich als Verbindungswort","falsche Präposition (at)"],"correct":0},", it can be addictive and stressful."],"solutionEn":"On the one hand, social media connects people all over the world. On the other hand, it can be addictive and stressful.","solutionDe":"Einerseits verbinden soziale Medien Menschen auf der ganzen Welt. Andererseits können sie süchtig machen und stressen.","explain":"Das Phrasen-Paar heißt 'On the one hand ... on the other hand' – perfekt, um positive und negative Aspekte zu verbinden (genau das verlangt die Aufgabe!)."},{"parts":["",{"opts":["Summing up","Summing down","Adding up"],"decode":["zusammenfassend (richtig)","gibt es nicht","zusammenzählend (Mathematik)"],"correct":0},", it can be said that social media is both a blessing and a curse."],"solutionEn":"Summing up, it can be said that social media is both a blessing and a curse.","solutionDe":"Zusammenfassend lässt sich sagen, dass soziale Medien Segen und Fluch zugleich sind.","explain":"'Summing up, it can be said that ...' ist eine Schluss-Phrase aus der Blog-Anleitung – ideal für die Conclusion."},{"parts":["I can't wait to read your opinion! ",{"opts":["Leave your comment below!","Yours faithfully, Alex.","See attachment for details."],"decode":["hinterlasst unten einen Kommentar! (richtig)","hochachtungsvoll, Alex (formeller Brief)","Details im Anhang (Büro-E-Mail)"],"correct":0}],"solutionEn":"I can't wait to read your opinion! Leave your comment below!","solutionDe":"Ich kann es kaum erwarten, eure Meinung zu lesen! Hinterlasst unten einen Kommentar!","explain":"Ein Blog endet mit Leser-Interaktion: um Kommentare bitten ('Leave your comment below', 'Share your thoughts in the comments below')."},{"parts":["",{"opts":["Frankly speaking","Frankly spoken","Free speaking"],"decode":["ehrlich gesagt (richtig)","falsche Verbform","wörtlich 'frei sprechend' – falsch"],"correct":0},", I check my phone far too often."],"solutionEn":"Frankly speaking, I check my phone far too often.","solutionDe":"Ehrlich gesagt schaue ich viel zu oft auf mein Handy.","explain":"'Frankly speaking' (ehrlich gesagt) ist eine informelle Phrase aus der Blog-Anleitung – gut, um persönlich und ehrlich zu klingen."}]},{"id":"blog_ex03","title":"Stil und Regeln des Blog Entry","source":"blog-post.pdf + BlogEntry_Social Media.pdf (Aufgabenstellung)","type":"mc","instruction":"Wähle die richtige Antwort zu Stil und Aufbau eines Blog Entry.","questions":[{"parts":["How many words should your blog entry have in the exam task? → ",{"opts":["140–180 words","at least 250 words","exactly 100 words"],"decode":["140–180 Wörter","mindestens 250 Wörter","genau 100 Wörter"],"correct":0}],"solutionEn":"The task says: Write a blog entry (140–180 words).","solutionDe":"Die Aufgabe verlangt 140–180 Wörter.","explain":"Wortzahl unbedingt einhalten! Übe vorher, deine Wörter zu zählen – der Mustertext hat 153 Wörter."},{"parts":["Which style is right for a blog entry? → ",{"opts":["informal and personal, with contractions like 'I don't'","formal, like a business letter","scientific, with many technical terms"],"decode":["informell und persönlich, mit Kurzformen wie 'I don't'","formell, wie ein Geschäftsbrief","wissenschaftlich, mit vielen Fachbegriffen"],"correct":0}],"solutionEn":"A blog entry is informal and personal: use the first person, contractions (I don't, I can't) and a friendly tone.","solutionDe":"Ein Blog Entry ist informell und persönlich: Ich-Form, Kurzformen (I don't, I can't) und ein freundlicher Ton.","explain":"Ein Blog ist persönlich und deshalb meistens informell – das steht genau so in der Blog-Anleitung."},{"parts":["How can you interact with your readers? → ",{"opts":["ask questions and use exclamations, e.g. 'What do you think?'","avoid speaking to them directly","use only passive sentences"],"decode":["Fragen stellen und Ausrufe verwenden, z. B. 'What do you think?'","sie nie direkt ansprechen","nur Passivsätze verwenden"],"correct":0}],"solutionEn":"Interact with your readers: ask questions and use exclamations, e.g. 'What do you think?', 'It's awesome!', 'Easier said than done. Right?'","solutionDe":"Sprich die Leser direkt an: Stelle Fragen und verwende Ausrufesätze, z. B. 'What do you think?', 'It's awesome!'","explain":"Leser-Interaktion ist ein Kernmerkmal des Blogs: Fragen, Ausrufe, direkte Anrede – das macht den Text lebendig."},{"parts":["What do you put at the very top of your blog entry? → ",{"opts":["a catchy title, your name, date and time","your home address and the school's address","a long summary of the whole text"],"decode":["einen auffälligen Titel, deinen Namen, Datum und Uhrzeit","deine Wohnadresse und die Adresse der Schule","eine lange Zusammenfassung des ganzen Texts"],"correct":0}],"solutionEn":"At the top: a catchy title, your name, date and time – e.g. 'CHIPS, BURGERS AND COLA MAKE ME HAPPY, by PeterPan, 2 June 2023, at 5 pm'.","solutionDe":"Ganz oben: ein 'catchy' Titel, dein Name, Datum und Uhrzeit – wie im Beispiel der Anleitung ('by PeterPan, 2 June 2023, at 5 pm').","explain":"Der Titel soll Leser anlocken UND über das Thema informieren. Die Jamie-Aufgabe sagt ausdrücklich: 'Give your blog entry a suitable title!'"},{"parts":["Which tense is used in the opening line 'I have just tried vegan food'? → ",{"opts":["Present Perfect","Past Perfect","Will-Future"],"decode":["Present Perfect (have + 3. Verbform)","Past Perfect (had + 3. Verbform)","Will-Future (will + Grundform)"],"correct":0}],"solutionEn":"'I have just tried vegan food' is Present Perfect (have/has + past participle).","solutionDe":"'I have just tried vegan food' steht im Present Perfect (have/has + 3. Verbform).","explain":"Mit dem Present Perfect erzählst du im Blog von (gerade gemachten) Erfahrungen oder fragst danach: 'Have you ever tried ...?'"},{"parts":["What does the Jamie task ask you to do? → ",{"opts":["respond to Jamie, describe how social media affects young people, give positive AND negative aspects, and explain its importance in your life","only describe the negative sides of social media","write a formal letter to Jamie about your school"],"decode":["auf Jamie antworten, die Wirkung auf junge Menschen beschreiben, positive UND negative Aspekte nennen und die Bedeutung in deinem Leben erklären","nur die negativen Seiten von Social Media beschreiben","einen formellen Brief an Jamie über deine Schule schreiben"],"correct":0}],"solutionEn":"The task: respond to Jamie's comment, describe how social media affects young people, mention both positive and negative aspects, and explain whether social media is important in your life – plus a suitable title.","solutionDe":"Die Aufgabe: auf Jamies Kommentar reagieren, die Wirkung auf junge Menschen beschreiben, positive UND negative Aspekte nennen, die Bedeutung in deinem Leben erklären – und ein passender Titel.","explain":"Arbeite in der Schularbeit ALLE vier Punkte ab und hake sie am Ende ab – fehlende Punkte kosten Inhaltspunkte."},{"parts":["Why are paragraphs and linking words important? → ",{"opts":["they make your text structured, logical and easy to read","they make the text longer so you reach the word count","they are only needed in formal letters"],"decode":["sie machen den Text strukturiert, logisch und gut lesbar","sie machen den Text länger, damit man die Wortzahl erreicht","man braucht sie nur in formellen Briefen"],"correct":0}],"solutionEn":"Paragraphs and linking words (however, on the one hand, summing up) make your text structured, logical and easy to read.","solutionDe":"Absätze und Verbindungswörter (however, on the one hand, summing up) machen deinen Text strukturiert, logisch und gut lesbar.","explain":"Die Anleitung warnt: Ein riesiger Textblock schreckt ab – niemand liest ihn. Absätze + linking words sind Pflicht."}]}]},{"id":"conditionals","title":"Conditionals I–III","icon":"🔀","phase":1,"birkenbihl":[{"id":"cond_t1","title":"Type 0 – Allgemeine Wahrheiten","sentences":[{"id":"cond_t1_s01","en":"If you heat water to 212 degrees, it boils and evaporates.","decode":[["If","wenn"],["you","du"],["heat","erhitzt"],["water","Wasser"],["to","auf"],["212 degrees,","212 Grad,"],["it","es"],["boils","kocht"],["and","und"],["evaporates.","verdampft."]],"de":"Wenn man Wasser auf 212 Grad erhitzt, kocht und verdampft es."},{"id":"cond_t1_s02","en":"If you strike a match, it starts burning.","decode":[["If","wenn"],["you","du"],["strike","anreißt"],["a","ein"],["match,","Streichholz,"],["it","es"],["starts","beginnt"],["burning.","zu-brennen."]],"de":"Wenn man ein Streichholz anreißt, beginnt es zu brennen."},{"id":"cond_t1_s03","en":"If I am late, my boss gets angry.","decode":[["If","wenn"],["I","ich"],["am","bin"],["late,","zu-spät,"],["my","mein"],["boss","Chef"],["gets","wird"],["angry.","wütend."]],"de":"Wenn ich zu spät komme, wird mein Chef wütend."},{"id":"cond_t1_s04","en":"If it snows in England, there is chaos on the roads.","decode":[["If","wenn"],["it","es"],["snows","schneit"],["in","in"],["England,","England,"],["there is","es-gibt"],["chaos","Chaos"],["on","auf"],["the","den"],["roads.","Straßen."]],"de":"Wenn es in England schneit, gibt es Chaos auf den Straßen."}]},{"id":"cond_t2","title":"Type I – Reale Bedingungen (Zukunft)","sentences":[{"id":"cond_t2_s01","en":"If it rains, I'll stay at home.","decode":[["If","wenn"],["it","es"],["rains,","regnet,"],["I'll stay","ich-werde-bleiben"],["at home.","zu-Hause."]],"de":"Wenn es regnet, bleibe ich zu Hause."},{"id":"cond_t2_s02","en":"If I pass my exams, my parents will buy me an iPhone X.","decode":[["If","wenn"],["I","ich"],["pass","bestehe"],["my","meine"],["exams,","Prüfungen,"],["my","meine"],["parents","Eltern"],["will buy","werden-kaufen"],["me","mir"],["an","ein"],["iPhone X.","iPhone X."]],"de":"Wenn ich meine Prüfungen bestehe, werden mir meine Eltern ein iPhone X kaufen."},{"id":"cond_t2_s03","en":"If we save enough money, we can go on holiday.","decode":[["If","wenn"],["we","wir"],["save","sparen"],["enough","genug"],["money,","Geld,"],["we","wir"],["can go","können-fahren"],["on holiday.","auf-Urlaub."]],"de":"Wenn wir genug Geld sparen, können wir auf Urlaub fahren."},{"id":"cond_t2_s04","en":"He will pass his driving test if he practises more.","decode":[["He","er"],["will pass","wird-bestehen"],["his","seine"],["driving test","Fahrprüfung"],["if","wenn"],["he","er"],["practises","übt"],["more.","mehr."]],"de":"Er wird seine Fahrprüfung bestehen, wenn er mehr übt."}]},{"id":"cond_t3","title":"Type II – Annahmen (unwahrscheinlich)","sentences":[{"id":"cond_t3_s01","en":"If I had enough money, I would buy a new car.","decode":[["If","wenn"],["I","ich"],["had","hätte"],["enough","genug"],["money,","Geld,"],["I","ich"],["would buy","würde-kaufen"],["a","ein"],["new","neues"],["car.","Auto."]],"de":"Wenn ich genug Geld hätte, würde ich ein neues Auto kaufen."},{"id":"cond_t3_s02","en":"If I were you, I would study more.","decode":[["If","wenn"],["I","ich"],["were","wäre"],["you,","du,"],["I","ich"],["would study","würde-lernen"],["more.","mehr."]],"de":"Wenn ich du wäre, würde ich mehr lernen."},{"id":"cond_t3_s03","en":"If we had our own boat, we could go on a sailing cruise in summer.","decode":[["If","wenn"],["we","wir"],["had","hätten"],["our","unser"],["own","eigenes"],["boat,","Boot,"],["we","wir"],["could go","könnten-fahren"],["on","auf"],["a","eine"],["sailing cruise","Segeltour"],["in summer.","im-Sommer."]],"de":"Wenn wir ein eigenes Boot hätten, könnten wir im Sommer auf eine Segeltour fahren."},{"id":"cond_t3_s04","en":"If you worked overtime more often, your boss might give you a pay rise.","decode":[["If","wenn"],["you","du"],["worked","machtest"],["overtime","Überstunden"],["more often,","öfter,"],["your","dein"],["boss","Chef"],["might give","würde-vielleicht-geben"],["you","dir"],["a","eine"],["pay rise.","Gehaltserhöhung."]],"de":"Wenn du öfter Überstunden machtest, würde dir dein Chef vielleicht eine Gehaltserhöhung geben."}]},{"id":"cond_t4","title":"Type III – Vergangenheit (nicht passiert)","sentences":[{"id":"cond_t4_s01","en":"If I had studied more, I would have passed the exam.","decode":[["If","wenn"],["I","ich"],["had studied","gelernt-hätte"],["more,","mehr,"],["I","ich"],["would have passed","hätte-bestanden"],["the","die"],["exam.","Prüfung."]],"de":"Wenn ich mehr gelernt hätte, hätte ich die Prüfung bestanden."},{"id":"cond_t4_s02","en":"If it had rained last night, I would have stayed at home.","decode":[["If","wenn"],["it","es"],["had rained","geregnet-hätte"],["last night,","letzte-Nacht,"],["I","ich"],["would have stayed","wäre-geblieben"],["at home.","zu-Hause."]],"de":"Wenn es letzte Nacht geregnet hätte, wäre ich zu Hause geblieben."},{"id":"cond_t4_s03","en":"If he hadn't been so tired, he could have finished the race.","decode":[["If","wenn"],["he","er"],["hadn't been","nicht-gewesen-wäre"],["so","so"],["tired,","müde,"],["he","er"],["could have finished","hätte-beenden-können"],["the","das"],["race.","Rennen."]],"de":"Wenn er nicht so müde gewesen wäre, hätte er das Rennen beenden können."},{"id":"cond_t4_s04","en":"They would have arrived on time if they had not missed the bus.","decode":[["They","sie"],["would have arrived","wären-angekommen"],["on time","pünktlich"],["if","wenn"],["they","sie"],["had not missed","nicht-verpasst-hätten"],["the","den"],["bus.","Bus."]],"de":"Sie wären pünktlich angekommen, wenn sie den Bus nicht verpasst hätten."}]}],"exercises":[{"id":"cond_ex01","title":"Type 0: Sätze bilden","source":"Conditionals 0,1,2_FormsAndStructures.pdf – Type 0: Form meaningful sentences (1–8)","type":"build","instruction":"Typ 0 – allgemeine Wahrheiten: Baue jeden Satz nach dem Muster „If you travel in the sun for hours, you get sunburnt quite easily.“ Wähle für jede Lücke die richtige Form.","questions":[{"parts":["If you ",{"opts":["stop","will stop","stopped"],"decode":["aufhörst","wirst-aufhören","aufhörtest"],"correct":0}," eating, you ",{"opts":["starve","will starve","would starve"],"decode":["verhungerst","wirst-verhungern","würdest-verhungern"],"correct":0},"."],"solutionEn":"If you stop eating, you starve.","solutionDe":"Wenn du aufhörst zu essen, verhungerst du.","explain":"Typ 0 (immer wahr): if + Present Simple, Hauptsatz Present Simple – kein will!"},{"parts":["If there ",{"opts":["is","will be","was"],"decode":["ist","wird-sein","war"],"correct":0}," a lot of snow, driving conditions ",{"opts":["are","will be","would be"],"decode":["sind","werden-sein","wären"],"correct":0}," dangerous."],"solutionEn":"If there is a lot of snow, driving conditions are dangerous.","solutionDe":"Wenn es viel Schnee gibt, sind die Fahrverhältnisse gefährlich.","explain":"Typ 0 (allgemeine Wahrheit): beide Teile stehen im Present Simple."},{"parts":["If people ",{"opts":["eat","will eat","ate"],"decode":["essen","werden-essen","aßen"],"correct":0}," too much junk food, they ",{"opts":["gain","will gain","gained"],"decode":["nehmen-zu","werden-zunehmen","nahmen-zu"],"correct":0}," weight."],"solutionEn":"If people eat too much junk food, they gain weight.","solutionDe":"Wenn Leute zu viel Junkfood essen, nehmen sie zu.","explain":"Typ 0: gilt immer und für alle → Present Simple + Present Simple."},{"parts":["If a serious hurricane ",{"opts":["hits","will hit","hit"],"decode":["trifft","wird-treffen","traf"],"correct":0}," Florida, the inhabitants ",{"opts":["leave","will leave","left"],"decode":["verlassen","werden-verlassen","verließen"],"correct":0}," the area."],"solutionEn":"If a serious hurricane hits Florida, the inhabitants leave the area.","solutionDe":"Wenn ein schwerer Hurrikan Florida trifft, verlassen die Bewohner das Gebiet.","explain":"Typ 0: typischer Ablauf, der immer so passiert → Present Simple in beiden Teilen. Achtung: hits mit -s (3. Person)."},{"parts":["If I regularly ",{"opts":["watch","will watch","watched"],"decode":["schaue","werde-schauen","schaute"],"correct":0}," the news in English, my English ",{"opts":["improves","will improve","improved"],"decode":["verbessert-sich","wird-sich-verbessern","verbesserte-sich"],"correct":0}," a lot."],"solutionEn":"If I regularly watch the news in English, my English improves a lot.","solutionDe":"Wenn ich regelmäßig die Nachrichten auf Englisch schaue, verbessert sich mein Englisch sehr.","explain":"Typ 0: regelmäßige, immer gültige Folge → Present Simple + Present Simple."},{"parts":["If elderly people ",{"opts":["have","will have","had"],"decode":["haben","werden-haben","hatten"],"correct":0}," a pet, they ",{"opts":["are","will be","were"],"decode":["sind","werden-sein","waren"],"correct":0}," happier."],"solutionEn":"If elderly people have a pet, they are happier.","solutionDe":"Wenn ältere Menschen ein Haustier haben, sind sie glücklicher.","explain":"Typ 0: allgemein gültige Aussage → Present Simple in beiden Satzteilen."},{"parts":["If we ",{"opts":["do","will do","did"],"decode":["machen","werden-machen","machten"],"correct":0}," a lot of sports, we ",{"opts":["are","will be","would be"],"decode":["sind","werden-sein","wären"],"correct":0}," in good shape."],"solutionEn":"If we do a lot of sports, we are in good shape.","solutionDe":"Wenn wir viel Sport machen, sind wir in guter Form.","explain":"Typ 0: immer wahre Folge → Present Simple + Present Simple."},{"parts":["If you ",{"opts":["grow up","will grow up","grew up"],"decode":["aufwächst","wirst-aufwachsen","aufwuchsest"],"correct":0}," in China, you ",{"opts":["learn","will learn","learnt"],"decode":["lernst","wirst-lernen","lerntest"],"correct":0}," to speak Chinese."],"solutionEn":"If you grow up in China, you learn to speak Chinese.","solutionDe":"Wenn du in China aufwächst, lernst du Chinesisch zu sprechen.","explain":"Typ 0: gilt grundsätzlich für jeden → Present Simple in beiden Teilen."}]},{"id":"cond_ex02","title":"Type I: Your Turn","source":"Conditionals 0,1,2_FormsAndStructures.pdf – Type 1: Your Turn 1 (1–10)","type":"build","instruction":"Typ I – reale Bedingungen: Setze die Verben in der richtigen Form ein (if + Present Simple, Hauptsatz mit will oder Modalverb).","questions":[{"parts":["If I ",{"opts":["wake up","will wake up","woke up"],"decode":["aufwache","werde-aufwachen","aufwachte"],"correct":0}," late on Monday, I ",{"opts":["will miss","missed","would miss"],"decode":["werde-verpassen","verpasste","würde-verpassen"],"correct":0}," the bus."],"solutionEn":"If I wake up late on Monday, I will miss the bus.","solutionDe":"Wenn ich am Montag spät aufwache, werde ich den Bus verpassen.","explain":"Typ I (real, Zukunft): if + Present Simple, Hauptsatz mit will + Infinitiv. Kein will im if-Satz!"},{"parts":["If you ",{"opts":["move","will move","moved"],"decode":["ziehst","wirst-ziehen","zogst"],"correct":0}," to Cuba, you ",{"opts":["must speak","will must speak","had to speak"],"decode":["musst-sprechen","wirst-müssen-sprechen","musstest-sprechen"],"correct":0}," Spanish."],"solutionEn":"If you move to Cuba, you must speak Spanish.","solutionDe":"Wenn du nach Kuba ziehst, musst du Spanisch sprechen.","explain":"Typ I: if + Present Simple; im Hauptsatz ist statt will auch ein Modalverb (must) möglich. will + must geht nicht zusammen."},{"parts":["If you ",{"opts":["learn","will learn","learnt"],"decode":["lernst","wirst-lernen","lerntest"],"correct":0}," hard, you ",{"opts":["will pass","passed","would pass"],"decode":["wirst-bestehen","bestandest","würdest-bestehen"],"correct":0}," your maths exam."],"solutionEn":"If you learn hard, you will pass your maths exam.","solutionDe":"Wenn du fleißig lernst, wirst du deine Mathe-Prüfung bestehen.","explain":"Typ I: reale Möglichkeit in der Zukunft → if + Present Simple, Hauptsatz will + Infinitiv."},{"parts":["If you ",{"opts":["eat","will eat","ate"],"decode":["isst","wirst-essen","aßest"],"correct":0}," healthy food, you ",{"opts":["will become","became","would become"],"decode":["wirst-werden","wurdest","würdest-werden"],"correct":0}," quite old."],"solutionEn":"If you eat healthy food, you will become quite old.","solutionDe":"Wenn du gesundes Essen isst, wirst du ziemlich alt werden.","explain":"Typ I: erfüllbare Bedingung → if + Present Simple, Hauptsatz will + Infinitiv."},{"parts":["If you ",{"opts":["do not hurry up","will not hurry up","did not hurry up"],"decode":["dich-nicht-beeilst","dich-nicht-beeilen-wirst","dich-nicht-beeiltest"],"correct":0},", you ",{"opts":["will miss","missed","would miss"],"decode":["wirst-verpassen","verpasstest","würdest-verpassen"],"correct":0}," your plane."],"solutionEn":"If you do not hurry up, you will miss your plane.","solutionDe":"Wenn du dich nicht beeilst, wirst du dein Flugzeug verpassen.","explain":"Typ I: Verneinung im if-Satz mit do not + Infinitiv (Present Simple), Hauptsatz mit will."},{"parts":["If you ",{"opts":["study","will study","studied"],"decode":["lernst","wirst-lernen","lerntest"],"correct":0}," English three times a week, you ",{"opts":["will improve","improved","would improve"],"decode":["wirst-dich-verbessern","verbessertest-dich","würdest-dich-verbessern"],"correct":0}," quickly."],"solutionEn":"If you study English three times a week, you will improve quickly.","solutionDe":"Wenn du dreimal pro Woche Englisch lernst, wirst du dich schnell verbessern.","explain":"Typ I: realistische Zukunftsbedingung → if + Present Simple, Hauptsatz will + Infinitiv."},{"parts":["If it ",{"opts":["rains","will rain","rained"],"decode":["regnet","wird-regnen","regnete"],"correct":0}," this weekend, we ",{"opts":["will not go","did not go","would not go"],"decode":["werden-nicht-fahren","fuhren-nicht","würden-nicht-fahren"],"correct":0}," on holiday to Hungary."],"solutionEn":"If it rains this weekend, we will not go on holiday to Hungary.","solutionDe":"Wenn es dieses Wochenende regnet, fahren wir nicht auf Urlaub nach Ungarn.","explain":"Typ I: if + Present Simple (rains), Hauptsatz verneint mit will not + Infinitiv."},{"parts":["If you ",{"opts":["are","will be","were"],"decode":["bist","sein-wirst","wärst"],"correct":0}," too busy, I ",{"opts":["will not come","would not come","had not come"],"decode":["werde-nicht-kommen","würde-nicht-kommen","war-nicht-gekommen"],"correct":0}," round for a cup of coffee."],"solutionEn":"If you are too busy, I will not come round for a cup of coffee.","solutionDe":"Wenn du zu beschäftigt bist, komme ich nicht auf eine Tasse Kaffee vorbei.","explain":"Typ I: if + Present Simple (are), Hauptsatz will not + Infinitiv."},{"parts":["If you ",{"opts":["do not leave","will not leave","did not leave"],"decode":["nicht-verlässt","nicht-verlassen-wirst","nicht-verließest"],"correct":0}," my flat at once, I ",{"opts":["will call","called","would call"],"decode":["werde-rufen","rief","würde-rufen"],"correct":0}," the police."],"solutionEn":"If you do not leave my flat at once, I will call the police.","solutionDe":"Wenn du meine Wohnung nicht sofort verlässt, rufe ich die Polizei.","explain":"Typ I: Drohung für die Zukunft → if + Present Simple (verneint), Hauptsatz will + Infinitiv."},{"parts":["If she ",{"opts":["offers","will offer","offered"],"decode":["anbietet","wird-anbieten","anbot"],"correct":0}," me the job of personal assistant, I ",{"opts":["will accept","accepted","would accept"],"decode":["werde-annehmen","nahm-an","würde-annehmen"],"correct":0}," this new opportunity."],"solutionEn":"If she offers me the job of personal assistant, I will accept this new opportunity.","solutionDe":"Wenn sie mir den Job als persönliche Assistentin anbietet, werde ich diese neue Chance annehmen.","explain":"Typ I: if + Present Simple (offers, 3. Person -s!), Hauptsatz will + Infinitiv."}]},{"id":"cond_ex03","title":"Type II: Your Turn","source":"Conditionals 0,1,2_FormsAndStructures.pdf – Type 2: Your Turn 1 (1–10)","type":"build","instruction":"Typ II – Annahmen: Setze die Verben in der richtigen Form ein (if + Past Simple, Hauptsatz mit would/could + Infinitiv). Achtung: be wird im if-Satz immer zu were.","questions":[{"parts":["If I ",{"opts":["were","am","would be"],"decode":["wäre","bin","würde-sein"],"correct":0}," ten years younger, I ",{"opts":["would emigrate","will emigrate","emigrated"],"decode":["würde-auswandern","werde-auswandern","wanderte-aus"],"correct":0}," to Australia."],"solutionEn":"If I were ten years younger, I would emigrate to Australia.","solutionDe":"Wenn ich zehn Jahre jünger wäre, würde ich nach Australien auswandern.","explain":"Typ II (bloße Annahme): if + Past Simple, Hauptsatz would + Infinitiv. be hat im if-Satz immer die Form were."},{"parts":["We are always late! If we ",{"opts":["left","leave","had left"],"decode":["losführen","losfahren","losgefahren-wären"],"correct":0}," punctually at six o'clock, we ",{"opts":["would not have","will not have","do not have"],"decode":["hätten-nicht","werden-nicht-haben","haben-nicht"],"correct":0}," any stress catching the early morning train."],"solutionEn":"If we left punctually at six o'clock, we would not have any stress catching the early morning train.","solutionDe":"Wenn wir pünktlich um sechs Uhr losführen, hätten wir keinen Stress, den frühen Morgenzug zu erwischen.","explain":"Typ II: Die Realität ist anders (wir sind immer spät dran) → if + Past Simple, Hauptsatz would + Infinitiv."},{"parts":["If I ",{"opts":["were","was","will be"],"decode":["wäre","war","werde-sein"],"correct":0}," a politician, I ",{"opts":["would fight","will fight","fought"],"decode":["würde-kämpfen","werde-kämpfen","kämpfte"],"correct":0}," for free health care and education."],"solutionEn":"If I were a politician, I would fight for free health care and education.","solutionDe":"Wenn ich Politiker wäre, würde ich für kostenlose Gesundheitsversorgung und Bildung kämpfen.","explain":"Typ II: unwahrscheinliche Annahme → if + were (nicht was – Regel vom Arbeitsblatt!), Hauptsatz would + Infinitiv."},{"parts":["If you ",{"opts":["drank","drink","would drink"],"decode":["tränkest","trinkst","würdest-trinken"],"correct":0}," too much alcohol, you ",{"opts":["would feel","will feel","felt"],"decode":["würdest-dich-fühlen","wirst-dich-fühlen","fühltest-dich"],"correct":0}," sleepy quite easily."],"solutionEn":"If you drank too much alcohol, you would feel sleepy quite easily.","solutionDe":"Wenn du zu viel Alkohol tränkest, würdest du dich ziemlich schnell schläfrig fühlen.","explain":"Typ II: if + Past Simple (drank), Hauptsatz would + Infinitiv (feel)."},{"parts":["If you ",{"opts":["had","have","would have"],"decode":["hättest","hast","würdest-haben"],"correct":0}," a spanner, you ",{"opts":["could fix","can fix","could have fixed"],"decode":["könntest-reparieren","kannst-reparieren","hättest-reparieren-können"],"correct":0}," your bike."],"solutionEn":"If you had a spanner, you could fix your bike.","solutionDe":"Wenn du einen Schraubenschlüssel hättest, könntest du dein Fahrrad reparieren.","explain":"Typ II: if + Past Simple (had); im Hauptsatz statt would auch could (= könntest)."},{"parts":["If we ",{"opts":["had","have","will have"],"decode":["hätten","haben","werden-haben"],"correct":0}," more money, we ",{"opts":["would invest","will invest","invested"],"decode":["würden-investieren","werden-investieren","investierten"],"correct":0}," most of it in schools."],"solutionEn":"If we had more money, we would invest most of it in schools.","solutionDe":"Wenn wir mehr Geld hätten, würden wir das meiste davon in Schulen investieren.","explain":"Typ II: bloße Annahme (wir haben das Geld nicht) → if + Past Simple, Hauptsatz would + Infinitiv."},{"parts":["If I ",{"opts":["spoke","speak","would speak"],"decode":["spräche","spreche","würde-sprechen"],"correct":0}," Japanese fluently, I ",{"opts":["would travel","will travel","travelled"],"decode":["würde-reisen","werde-reisen","reiste"],"correct":0}," to Japan."],"solutionEn":"If I spoke Japanese fluently, I would travel to Japan.","solutionDe":"Wenn ich fließend Japanisch spräche, würde ich nach Japan reisen.","explain":"Typ II: if + Past Simple (spoke), Hauptsatz would + Infinitiv. Kein would im if-Satz!"},{"parts":["If I ",{"opts":["were","am","will be"],"decode":["wäre","bin","werde-sein"],"correct":0}," slimmer, I ",{"opts":["would buy","will buy","bought"],"decode":["würde-kaufen","werde-kaufen","kaufte"],"correct":0}," designer clothes."],"solutionEn":"If I were slimmer, I would buy designer clothes.","solutionDe":"Wenn ich schlanker wäre, würde ich Designerkleidung kaufen.","explain":"Typ II: Annahme über die Gegenwart → if + were, Hauptsatz would + Infinitiv."},{"parts":["If I ",{"opts":["had","have","had had"],"decode":["hätte","habe","gehabt-hätte"],"correct":0}," more time and money, I ",{"opts":["could stop","can stop","could have stopped"],"decode":["könnte-aufhören","kann-aufhören","hätte-aufhören-können"],"correct":0}," working and go abroad."],"solutionEn":"If I had more time and money, I could stop working and go abroad.","solutionDe":"Wenn ich mehr Zeit und Geld hätte, könnte ich aufhören zu arbeiten und ins Ausland gehen.","explain":"Typ II: if + Past Simple (had), Hauptsatz mit Modalverb could + Infinitiv."},{"parts":["If I ",{"opts":["were","was","am"],"decode":["wäre","war","bin"],"correct":0}," you, I ",{"opts":["would buy","will buy","would have bought"],"decode":["würde-kaufen","werde-kaufen","hätte-gekauft"],"correct":0}," that new car."],"solutionEn":"If I were you, I would buy that new car.","solutionDe":"Wenn ich du wäre, würde ich das neue Auto kaufen.","explain":"Typ II: feste Wendung If I were you (Ratschlag) → Hauptsatz would + Infinitiv."}]},{"id":"cond_ex04","title":"First & Second Conditional: Lücken","source":"first-second-third-conditional.pdf – Presentation-Beispiele; Conditionals-Explained.pdf (unless)","type":"gap","instruction":"First oder Second Conditional? Wähle die richtige Form für die Lücke.","questions":[{"parts":["According to the weather forecast, it might rain tonight. If it ",{"opts":["rains","will rain","rained"],"decode":["regnet","wird-regnen","regnete"],"correct":0},", I'll stay at home."],"solutionEn":"If it rains, I'll stay at home.","solutionDe":"Wenn es regnet, bleibe ich zu Hause.","explain":"Typ I (reale Möglichkeit): kein will im if-Satz! if + Present Simple, Hauptsatz mit will ('ll stay)."},{"parts":["If I ",{"opts":["don't call","won't call","didn't call"],"decode":["nicht-anrufe","nicht-anrufen-werde","nicht-anrief"],"correct":0}," you tonight, you can call me."],"solutionEn":"If I don't call you tonight, you can call me.","solutionDe":"Wenn ich dich heute Abend nicht anrufe, kannst du mich anrufen.","explain":"Typ I: if + Present Simple (verneint mit don't); im Hauptsatz statt will auch can."},{"parts":["Will you wait for me if I ",{"opts":["am","will be","was"],"decode":["bin","sein-werde","war"],"correct":0}," late?"],"solutionEn":"Will you wait for me if I am late?","solutionDe":"Wirst du auf mich warten, wenn ich zu spät komme?","explain":"Typ I als Frage: will steht nur im Hauptsatz, im if-Satz Present Simple (am)."},{"parts":["At the moment, it's raining. If it was sunny, I ",{"opts":["would go","will go","went"],"decode":["würde-gehen","werde-gehen","ging"],"correct":0}," out."],"solutionEn":"If it was sunny, I would go out.","solutionDe":"Im Moment regnet es. Wenn es sonnig wäre, würde ich rausgehen.","explain":"Typ II (Gegenteil der Realität): if + Past Simple, Hauptsatz would + Infinitiv. (Das Blatt schreibt was; bei be ist im if-Satz auch were üblich.)"},{"parts":["What would you do if you ",{"opts":["found","find","will find"],"decode":["fändest","findest","finden-wirst"],"correct":0}," a lot of money in the street?"],"solutionEn":"What would you do if you found a lot of money in the street?","solutionDe":"Was würdest du tun, wenn du auf der Straße viel Geld fändest?","explain":"Typ II: if + Past Simple (found). Die Vergangenheitsform meint hier nichts Vergangenes, sondern eine vorgestellte Situation."},{"parts":["If it wasn't dark outside, we ",{"opts":["could go","can go","will go"],"decode":["könnten-gehen","können-gehen","werden-gehen"],"correct":0}," out."],"solutionEn":"If it wasn't dark outside, we could go out.","solutionDe":"Wenn es draußen nicht dunkel wäre, könnten wir rausgehen.","explain":"Typ II: im Hauptsatz statt would auch could oder might."},{"parts":["We are sure she will come. ",{"opts":["When","If","Unless"],"decode":["wenn/sobald","falls","außer-wenn"],"correct":0}," she comes, I'll call you."],"solutionEn":"When she comes, I'll call you.","solutionDe":"Wenn (sobald) sie kommt, rufe ich dich an.","explain":"Bei Dingen, die sicher passieren werden, steht when statt if (Struktur wie Typ I)."},{"parts":["You don't get fit ",{"opts":["unless","if","when"],"decode":["außer-wenn","wenn","sobald"],"correct":0}," you exercise regularly. (= if you don't exercise regularly)"],"solutionEn":"You don't get fit unless you exercise regularly.","solutionDe":"Du wirst nicht fit, außer wenn du regelmäßig trainierst.","explain":"unless = if not (wenn nicht / außer wenn). Der Satz selbst ist hier ein Typ 0 (allgemeine Wahrheit)."}]},{"id":"cond_ex05","title":"Third Conditional: Lücken","source":"third-conditional-british-english-teacher-B1-B2.pdf – Ex. 2 Part B (1–8, Teacher-Key)","type":"build","instruction":"Third Conditional: Wähle für jede Lücke die richtige Form (if + Past Perfect, Hauptsatz mit would have + Past Participle).","questions":[{"parts":["If I ",{"opts":["had studied","studied","would have studied"],"decode":["gelernt-hätte","lernte","würde-gelernt-haben"],"correct":0}," harder, I ",{"opts":["would have passed","would pass","had passed"],"decode":["hätte-bestanden","würde-bestehen","hatte-bestanden"],"correct":0}," the exam."],"solutionEn":"If I had studied harder, I would have passed the exam.","solutionDe":"Wenn ich härter gelernt hätte, hätte ich die Prüfung bestanden.","explain":"Typ III (Vergangenheit, nicht passiert): if + Past Perfect, Hauptsatz would have + Past Participle."},{"parts":["They ",{"opts":["wouldn't have gotten","wouldn't get","hadn't gotten"],"decode":["hätten-sich-nicht-verirrt","würden-sich-nicht-verirren","hatten-sich-nicht-verirrt"],"correct":0}," lost if they ",{"opts":["had followed","followed","would have followed"],"decode":["gefolgt-wären","folgten","würden-gefolgt-sein"],"correct":0}," the map."],"solutionEn":"They wouldn't have gotten lost if they had followed the map.","solutionDe":"Sie hätten sich nicht verirrt, wenn sie der Karte gefolgt wären.","explain":"Typ III: Hauptsatz wouldn't have + Past Participle, if-Satz Past Perfect. would steht nie im if-Satz!"},{"parts":["If she ",{"opts":["had asked","asked","would have asked"],"decode":["gebeten-hätte","bat","würde-gebeten-haben"],"correct":0}," for help, someone ",{"opts":["would have assisted","would assist","had assisted"],"decode":["hätte-geholfen","würde-helfen","hatte-geholfen"],"correct":0}," her."],"solutionEn":"If she had asked for help, someone would have assisted her.","solutionDe":"Wenn sie um Hilfe gebeten hätte, hätte ihr jemand geholfen.","explain":"Typ III: unreale Vergangenheit (sie hat nicht gefragt) → if + Past Perfect, Hauptsatz would have + Past Participle."},{"parts":["We ",{"opts":["would have attended","would attend","had attended"],"decode":["hätten-besucht","würden-besuchen","hatten-besucht"],"correct":0}," the concert if we ",{"opts":["had bought","bought","would have bought"],"decode":["gekauft-hätten","kauften","würden-gekauft-haben"],"correct":0}," tickets earlier."],"solutionEn":"We would have attended the concert if we had bought tickets earlier.","solutionDe":"Wir hätten das Konzert besucht, wenn wir früher Karten gekauft hätten.","explain":"Typ III: Hauptsatz would have + Past Participle, if-Satz Past Perfect – der if-Satz kann auch hinten stehen (dann kein Komma)."},{"parts":["If it ",{"opts":["hadn't rained","didn't rain","wouldn't have rained"],"decode":["nicht-geregnet-hätte","nicht-regnete","würde-nicht-geregnet-haben"],"correct":0}," yesterday, we ",{"opts":["would have gone","would go","had gone"],"decode":["wären-gegangen","würden-gehen","waren-gegangen"],"correct":0}," for a picnic."],"solutionEn":"If it hadn't rained yesterday, we would have gone for a picnic.","solutionDe":"Wenn es gestern nicht geregnet hätte, hätten wir ein Picknick gemacht.","explain":"Typ III: Signalwort yesterday → Vergangenheit. if + Past Perfect (verneint: hadn't), Hauptsatz would have + Past Participle."},{"parts":["He ",{"opts":["would have been","would be","had been"],"decode":["wäre-gewesen","wäre","war-gewesen"],"correct":0}," on time if his alarm clock ",{"opts":["hadn't broken","didn't break","wouldn't have broken"],"decode":["nicht-kaputtgegangen-wäre","nicht-kaputtging","würde-nicht-kaputtgegangen-sein"],"correct":0}," down."],"solutionEn":"He would have been on time if his alarm clock hadn't broken down.","solutionDe":"Er wäre pünktlich gewesen, wenn sein Wecker nicht kaputtgegangen wäre.","explain":"Typ III: Hauptsatz would have been, if-Satz Past Perfect (hadn't broken down)."},{"parts":["If they ",{"opts":["hadn't missed","didn't miss","wouldn't have missed"],"decode":["nicht-verpasst-hätten","nicht-verpassten","würden-nicht-verpasst-haben"],"correct":0}," the bus, they ",{"opts":["would have arrived","would arrive","had arrived"],"decode":["wären-angekommen","würden-ankommen","waren-angekommen"],"correct":0}," on time."],"solutionEn":"If they hadn't missed the bus, they would have arrived on time.","solutionDe":"Wenn sie den Bus nicht verpasst hätten, wären sie pünktlich angekommen.","explain":"Typ III: In Wirklichkeit haben sie den Bus verpasst → if + Past Perfect, Hauptsatz would have + Past Participle."},{"parts":["She ",{"opts":["would have felt","would feel","had felt"],"decode":["hätte-sich-gefühlt","würde-sich-fühlen","hatte-sich-gefühlt"],"correct":0}," better if she ",{"opts":["had taken","took","would have taken"],"decode":["genommen-hätte","nahm","würde-genommen-haben"],"correct":0}," the medicine earlier."],"solutionEn":"She would have felt better if she had taken the medicine earlier.","solutionDe":"Sie hätte sich besser gefühlt, wenn sie das Medikament früher genommen hätte.","explain":"Typ III: unreale Vergangenheit → Hauptsatz would have felt, if-Satz had taken (Past Perfect)."}]},{"id":"cond_ex06","title":"Third Conditional: Nicks Pannentag","source":"third-conditional-british-english-teacher-B1-B2.pdf – Ex. 2 Part C (1–6, Teacher-Key)","type":"build","instruction":"Gestern hatte Nick viele Probleme. Baue zu jedem Problem den passenden Third-Conditional-Satz.","questions":[{"parts":["Problem: He was not able to use the internet. → If he ",{"opts":["had paid","paid","would have paid"],"decode":["bezahlt-hätte","bezahlte","würde-bezahlt-haben"],"correct":0}," his internet bill, he ",{"opts":["would have been","would be","had been"],"decode":["wäre-gewesen","wäre","war-gewesen"],"correct":0}," able to use the internet."],"solutionEn":"If he had paid his internet bill, he would have been able to use the internet.","solutionDe":"Wenn er seine Internetrechnung bezahlt hätte, hätte er das Internet nutzen können.","explain":"Typ III: Die Vergangenheit lässt sich nicht mehr ändern → if + Past Perfect, Hauptsatz would have + Past Participle."},{"parts":["Problem: He forgot his best friend's birthday. → If he ",{"opts":["had kept","kept","would have kept"],"decode":["geführt-hätte","führte","würde-geführt-haben"],"correct":0}," a diary, he ",{"opts":["would have remembered","would remember","had remembered"],"decode":["hätte-sich-erinnert","würde-sich-erinnern","hatte-sich-erinnert"],"correct":0}," his best friend's birthday."],"solutionEn":"If he had kept a diary, he would have remembered his best friend's birthday.","solutionDe":"Wenn er einen Kalender geführt hätte, hätte er sich an den Geburtstag seines besten Freundes erinnert.","explain":"Typ III: nicht passierte Vergangenheit → if + Past Perfect (had kept), Hauptsatz would have remembered."},{"parts":["Problem: His car broke down. → His car ",{"opts":["wouldn't have broken down","didn't break down","hadn't broken down"],"decode":["wäre-nicht-kaputtgegangen","ging-nicht-kaputt","war-nicht-kaputtgegangen"],"correct":0}," if he ",{"opts":["had changed","changed","would have changed"],"decode":["gewechselt-hätte","wechselte","würde-gewechselt-haben"],"correct":0}," the oil."],"solutionEn":"His car wouldn't have broken down if he had changed the oil.","solutionDe":"Sein Auto wäre nicht kaputtgegangen, wenn er das Öl gewechselt hätte.","explain":"Typ III: Hauptsatz zuerst (wouldn't have + Past Participle), if-Satz mit Past Perfect dahinter."},{"parts":["Problem: He ran out of coffee. → If he ",{"opts":["had done","did","would have done"],"decode":["gemacht-hätte","machte","würde-gemacht-haben"],"correct":0}," some shopping, he ",{"opts":["wouldn't have run out","wouldn't run out","hadn't run out"],"decode":["wäre-nicht-ausgegangen","würde-nicht-ausgehen","war-nicht-ausgegangen"],"correct":0}," of coffee."],"solutionEn":"If he had done some shopping, he wouldn't have run out of coffee.","solutionDe":"Wenn er eingekauft hätte, wäre ihm der Kaffee nicht ausgegangen.","explain":"Typ III: if + Past Perfect (had done), Hauptsatz verneint: wouldn't have + Past Participle (run)."},{"parts":["Problem: He was soaking wet. → If he ",{"opts":["had had","had","would have had"],"decode":["gehabt-hätte","hatte","würde-gehabt-haben"],"correct":0}," an umbrella, he ",{"opts":["wouldn't have been","wouldn't be","hadn't been"],"decode":["wäre-nicht-gewesen","wäre-nicht","war-nicht-gewesen"],"correct":0}," soaking wet."],"solutionEn":"If he had had an umbrella, he wouldn't have been soaking wet.","solutionDe":"Wenn er einen Regenschirm gehabt hätte, wäre er nicht klatschnass gewesen.","explain":"Typ III: had had = Past Perfect von have (oft abgekürzt: if he'd had). Hauptsatz wouldn't have been."},{"parts":["Problem: He got food poisoning in the evening. → If he ",{"opts":["had cooked","cooked","would have cooked"],"decode":["gekocht-hätte","kochte","würde-gekocht-haben"],"correct":0}," his lunch properly, he ",{"opts":["wouldn't have got","wouldn't get","hadn't got"],"decode":["hätte-nicht-bekommen","würde-nicht-bekommen","hatte-nicht-bekommen"],"correct":0}," food poisoning in the evening."],"solutionEn":"If he had cooked his lunch properly, he wouldn't have got food poisoning in the evening.","solutionDe":"Wenn er sein Mittagessen richtig gekocht hätte, hätte er am Abend keine Lebensmittelvergiftung bekommen.","explain":"Typ III: if + Past Perfect (had cooked), Hauptsatz wouldn't have got (Past Participle von get)."}]},{"id":"cond_ex07","title":"Third Conditional: Emmas verpasstes Konzert","source":"third-conditional-british-english-teacher-B1-B2.pdf – Ex. 3 Part B (1–4, Teacher-Key)","type":"build","instruction":"Emma hat ihren Wecker nicht kontrolliert, hat verschlafen, den Bus verpasst und das Konzert versäumt. Vervollständige die Sätze über ihren Tag im Third Conditional.","questions":[{"parts":["If Emma ",{"opts":["had checked","checked","would have checked"],"decode":["kontrolliert-hätte","kontrollierte","würde-kontrolliert-haben"],"correct":0}," her alarm the night before, she ",{"opts":["would have woken up","would wake up","had woken up"],"decode":["wäre-aufgewacht","würde-aufwachen","war-aufgewacht"],"correct":0}," on time."],"solutionEn":"If Emma had checked her alarm the night before, she would have woken up on time.","solutionDe":"Wenn Emma am Abend davor ihren Wecker kontrolliert hätte, wäre sie rechtzeitig aufgewacht.","explain":"Typ III: Sie hat den Wecker nicht kontrolliert (Vergangenheit, nicht passiert) → if + Past Perfect, Hauptsatz would have + Past Participle."},{"parts":["If Emma ",{"opts":["had woken up","woke up","would have woken up"],"decode":["aufgewacht-wäre","aufwachte","würde-aufgewacht-sein"],"correct":0}," on time, she ",{"opts":["would have caught","would catch","had caught"],"decode":["hätte-erwischt","würde-erwischen","hatte-erwischt"],"correct":0}," the bus."],"solutionEn":"If Emma had woken up on time, she would have caught the bus.","solutionDe":"Wenn Emma rechtzeitig aufgewacht wäre, hätte sie den Bus erwischt.","explain":"Typ III: if + Past Perfect (had woken up), Hauptsatz would have caught."},{"parts":["If Emma ",{"opts":["had caught","caught","would have caught"],"decode":["erwischt-hätte","erwischte","würde-erwischt-haben"],"correct":0}," the bus, she ",{"opts":["would have arrived","would arrive","had arrived"],"decode":["wäre-angekommen","würde-ankommen","war-angekommen"],"correct":0}," at the concert on time with her friends."],"solutionEn":"If Emma had caught the bus, she would have arrived at the concert on time with her friends.","solutionDe":"Wenn Emma den Bus erwischt hätte, wäre sie mit ihren Freunden rechtzeitig beim Konzert angekommen.","explain":"Typ III: Kette von unrealen Vergangenheits-Bedingungen → if + Past Perfect, Hauptsatz would have + Past Participle."},{"parts":["If Emma ",{"opts":["had set","set","would have set"],"decode":["gestellt-hätte","stellte","würde-gestellt-haben"],"correct":0}," her alarm correctly, she ",{"opts":["would not have missed","would not miss","had not missed"],"decode":["hätte-nicht-versäumt","würde-nicht-versäumen","hatte-nicht-versäumt"],"correct":0}," the concert."],"solutionEn":"If Emma had set her alarm correctly, she would not have missed the concert.","solutionDe":"Wenn Emma ihren Wecker richtig gestellt hätte, hätte sie das Konzert nicht versäumt.","explain":"Typ III: if + Past Perfect (had set), Hauptsatz verneint: would not have missed."}]},{"id":"cond_ex08","title":"Welcher Typ ist das?","source":"Beispielsätze aus allen Arbeitsblättern – Typ bestimmen","type":"mc","instruction":"Welcher Conditional-Typ ist das? Schau auf die Zeitformen im if-Satz und im Hauptsatz.","questions":[{"parts":["“If you strike a match, it starts burning.” → ",{"opts":["Typ 0","Typ I","Typ II","Typ III"],"decode":["immer-wahr","reale-Zukunft","bloße-Annahme","unmögliche-Vergangenheit"],"correct":0}],"solutionEn":"Type 0: If you strike a match, it starts burning.","solutionDe":"Typ 0 – Wenn man ein Streichholz anreißt, beginnt es zu brennen (immer wahr).","explain":"Beide Teile Present Simple (strike / starts) → Typ 0: allgemein gültige Tatsache."},{"parts":["“If we learn Japanese, we will be able to communicate with people in Japan.” → ",{"opts":["Typ 0","Typ I","Typ II","Typ III"],"decode":["immer-wahr","reale-Zukunft","bloße-Annahme","unmögliche-Vergangenheit"],"correct":1}],"solutionEn":"Type I: If we learn Japanese, we will be able to communicate with people in Japan.","solutionDe":"Typ I – Wenn wir Japanisch lernen, werden wir mit Leuten in Japan kommunizieren können.","explain":"if-Satz Present Simple (learn), Hauptsatz will + Infinitiv → Typ I: reale Möglichkeit in der Zukunft."},{"parts":["“If you sent her a message, she would be happy.” → ",{"opts":["Typ 0","Typ I","Typ II","Typ III"],"decode":["immer-wahr","reale-Zukunft","bloße-Annahme","unmögliche-Vergangenheit"],"correct":2}],"solutionEn":"Type II: If you sent her a message, she would be happy.","solutionDe":"Typ II – Wenn du ihr eine Nachricht schicktest, würde sie sich freuen.","explain":"if-Satz Past Simple (sent), Hauptsatz would + Infinitiv → Typ II: bloße Annahme."},{"parts":["“If I hadn't broken my leg, I would have gone skiing.” → ",{"opts":["Typ 0","Typ I","Typ II","Typ III"],"decode":["immer-wahr","reale-Zukunft","bloße-Annahme","unmögliche-Vergangenheit"],"correct":3}],"solutionEn":"Type III: If I hadn't broken my leg, I would have gone skiing.","solutionDe":"Typ III – Wenn ich mir nicht das Bein gebrochen hätte, wäre ich Ski fahren gegangen.","explain":"if-Satz Past Perfect (hadn't broken), Hauptsatz would have + Past Participle → Typ III: Vergangenheit, nicht mehr änderbar."},{"parts":["“Get ready if you want to catch the bus!” → ",{"opts":["Typ 0","Typ I","Typ II","Typ III"],"decode":["immer-wahr","reale-Zukunft","bloße-Annahme","unmögliche-Vergangenheit"],"correct":1}],"solutionEn":"Type I: Get ready if you want to catch the bus!","solutionDe":"Typ I – Mach dich fertig, wenn du den Bus erwischen willst!","explain":"if-Satz Present Simple (want), Hauptsatz Imperativ (Get ready!) → Typ I: Im Hauptsatz ist auch ein Befehl möglich."},{"parts":["“It would be nice if we went to see Granny at the weekend.” → ",{"opts":["Typ 0","Typ I","Typ II","Typ III"],"decode":["immer-wahr","reale-Zukunft","bloße-Annahme","unmögliche-Vergangenheit"],"correct":2}],"solutionEn":"Type II: It would be nice if we went to see Granny at the weekend.","solutionDe":"Typ II – Es wäre schön, wenn wir am Wochenende Oma besuchen würden.","explain":"Hauptsatz would + Infinitiv (would be), if-Satz Past Simple (went) → Typ II. Der if-Satz darf auch hinten stehen."},{"parts":["“I would have said hello if I had seen you.” → ",{"opts":["Typ 0","Typ I","Typ II","Typ III"],"decode":["immer-wahr","reale-Zukunft","bloße-Annahme","unmögliche-Vergangenheit"],"correct":3}],"solutionEn":"Type III: I would have said hello if I had seen you.","solutionDe":"Typ III – Ich hätte Hallo gesagt, wenn ich dich gesehen hätte.","explain":"Hauptsatz would have + Past Participle (said), if-Satz Past Perfect (had seen) → Typ III: unreale Vergangenheit."},{"parts":["“If you want to study in the USA, you have to pass an exam in English.” → ",{"opts":["Typ 0","Typ I","Typ II","Typ III"],"decode":["immer-wahr","reale-Zukunft","bloße-Annahme","unmögliche-Vergangenheit"],"correct":0}],"solutionEn":"Type 0: If you want to study in the USA, you have to pass an exam in English.","solutionDe":"Typ 0 – Wenn man in den USA studieren will, muss man eine Englischprüfung bestehen (Regel).","explain":"Beide Teile Present Simple (want / have to pass) → Typ 0: beschreibt eine feste Regel."}]},{"id":"cond_ex09","title":"Typ umformen","source":"Zusatztraining – Umformen (Sätze aus den Arbeitsblättern)","type":"build","instruction":"Forme den Satz in den angegebenen Typ um – gleicher Inhalt, andere Zeitstufe.","questions":[{"parts":["Typ I: “If I pass my exam, I will celebrate.” → Typ II: If I ",{"opts":["passed","pass","had passed"],"decode":["bestünde","bestehe","bestanden-hätte"],"correct":0}," my exam, I ",{"opts":["would celebrate","will celebrate","would have celebrated"],"decode":["würde-feiern","werde-feiern","hätte-gefeiert"],"correct":0},"."],"solutionEn":"If I passed my exam, I would celebrate.","solutionDe":"Wenn ich meine Prüfung bestünde, würde ich feiern.","explain":"Typ I → Typ II: Present Simple → Past Simple (pass → passed), will → would."},{"parts":["Typ II: “If I had the money, I would pay my debts.” → Typ III: If I ",{"opts":["had had","had","would have had"],"decode":["gehabt-hätte","hätte","würde-gehabt-haben"],"correct":0}," the money, I ",{"opts":["would have paid","would pay","had paid"],"decode":["hätte-bezahlt","würde-bezahlen","hatte-bezahlt"],"correct":0}," my debts."],"solutionEn":"If I had had the money, I would have paid my debts.","solutionDe":"Wenn ich das Geld gehabt hätte, hätte ich meine Schulden bezahlt.","explain":"Typ II → Typ III: Past Simple → Past Perfect (had → had had), would → would have + Past Participle."},{"parts":["Typ I: “If it rains, I will stay at home.” → Typ III: If it ",{"opts":["had rained","rained","would have rained"],"decode":["geregnet-hätte","regnete","würde-geregnet-haben"],"correct":0},", I ",{"opts":["would have stayed","would stay","will stay"],"decode":["wäre-geblieben","würde-bleiben","werde-bleiben"],"correct":0}," at home."],"solutionEn":"If it had rained, I would have stayed at home.","solutionDe":"Wenn es geregnet hätte, wäre ich zu Hause geblieben.","explain":"Typ I → Typ III: Die Bedingung wandert in die Vergangenheit: rains → had rained, will stay → would have stayed."},{"parts":["Typ II: “If I were you, I would buy that new car.” → Typ III: If I ",{"opts":["had been","were","would have been"],"decode":["gewesen-wäre","wäre","würde-gewesen-sein"],"correct":0}," you, I ",{"opts":["would have bought","would buy","had bought"],"decode":["hätte-gekauft","würde-kaufen","hatte-gekauft"],"correct":0}," that new car."],"solutionEn":"If I had been you, I would have bought that new car.","solutionDe":"Wenn ich du gewesen wäre, hätte ich das neue Auto gekauft.","explain":"Typ II → Typ III: were → had been (Past Perfect), would buy → would have bought."},{"parts":["Typ III: “If I had studied more, I would have passed the exam.” → Typ II (jetzt allgemein): If I ",{"opts":["studied","had studied","study"],"decode":["lernte","gelernt-hätte","lerne"],"correct":0}," more, I ",{"opts":["would pass","would have passed","will pass"],"decode":["würde-bestehen","hätte-bestanden","werde-bestehen"],"correct":0}," the exam."],"solutionEn":"If I studied more, I would pass the exam.","solutionDe":"Wenn ich mehr lernte, würde ich die Prüfung bestehen.","explain":"Typ III → Typ II: aus der unrealen Vergangenheit wird eine Annahme über die Gegenwart: had studied → studied, would have passed → would pass."},{"parts":["Typ I: “If we save enough money, we can go on holiday.” → Typ II: If we ",{"opts":["saved","save","had saved"],"decode":["sparten","sparen","gespart-hätten"],"correct":0}," enough money, we ",{"opts":["could go","can go","could have gone"],"decode":["könnten-fahren","können-fahren","hätten-fahren-können"],"correct":0}," on holiday."],"solutionEn":"If we saved enough money, we could go on holiday.","solutionDe":"Wenn wir genug Geld sparten, könnten wir auf Urlaub fahren.","explain":"Typ I → Typ II: save → saved (Past Simple), can → could. Modalverben wandern mit der Zeitstufe."}]}]},{"id":"passive","title":"Passive Voice","icon":"🔄","phase":1,"birkenbihl":[{"id":"pas_t1","title":"Passiv-Beispielsätze (alle Zeiten)","sentences":[{"id":"pas_t1_s01","en":"The letters are delivered.","decode":[["The","Die"],["letters","Briefe"],["are delivered.","werden-zugestellt."]],"de":"(Aktiv: He delivers the letters.) Die Briefe werden zugestellt. – Present Simple"},{"id":"pas_t1_s02","en":"The letters were delivered.","decode":[["The","Die"],["letters","Briefe"],["were delivered.","wurden-zugestellt."]],"de":"(Aktiv: He delivered the letters.) Die Briefe wurden zugestellt. – Past Simple"},{"id":"pas_t1_s03","en":"The letters have been delivered.","decode":[["The","Die"],["letters","Briefe"],["have been delivered.","sind-zugestellt-worden."]],"de":"(Aktiv: He has delivered the letters.) Die Briefe sind zugestellt worden. – Present Perfect"},{"id":"pas_t1_s04","en":"The new library will be opened by the Queen.","decode":[["The","Die"],["new","neue"],["library","Bibliothek"],["will be opened","wird-eröffnet-werden"],["by","von"],["the","der"],["Queen.","Königin."]],"de":"(Aktiv: The Queen will open the new library.) Die neue Bibliothek wird von der Königin eröffnet werden. – will-Future"},{"id":"pas_t1_s05","en":"This book was written by Agatha Christie.","decode":[["This","Dieses"],["book","Buch"],["was written","wurde-geschrieben"],["by","von"],["Agatha","Agatha"],["Christie.","Christie."]],"de":"(Aktiv: Agatha Christie wrote this book.) Dieses Buch wurde von Agatha Christie geschrieben."},{"id":"pas_t1_s06","en":"I was given this book by Rick.","decode":[["I","Ich"],["was given","wurde-gegeben"],["this","dieses"],["book","Buch"],["by","von"],["Rick.","Rick."]],"de":"(Aktiv: Rick gave me this book.) Mir wurde dieses Buch von Rick gegeben. – persönliches Passiv!"},{"id":"pas_t1_s07","en":"The door was opened with a key.","decode":[["The","Die"],["door","Tür"],["was opened","wurde-geöffnet"],["with","mit"],["a","einem"],["key.","Schlüssel."]],"de":"(Aktiv: Someone opened the door with a key.) Die Tür wurde mit einem Schlüssel geöffnet. – with = Werkzeug, by = Täter!"}]},{"id":"pas_t2","title":"Die Fiat-Story im Passiv","sentences":[{"id":"pas_t2_s01","en":"Fiat was started by a group of Italian businessmen in 1899.","decode":[["Fiat","Fiat"],["was started","wurde-gegründet"],["by","von"],["a","einer"],["group","Gruppe"],["of","von"],["Italian","italienischen"],["businessmen","Geschäftsleuten"],["in","in"],["1899.","1899."]],"de":"(Aktiv: A group of Italian businessmen started Fiat in 1899.) Fiat wurde 1899 von einer Gruppe italienischer Geschäftsleute gegründet."},{"id":"pas_t2_s02","en":"Some of these cars were exported to the United States and Britain.","decode":[["Some","Einige"],["of","von"],["these","diesen"],["cars","Autos"],["were exported","wurden-exportiert"],["to","in"],["the","die"],["United States","USA"],["and","und"],["Britain.","Großbritannien."]],"de":"(Aktiv: The company exported some of these cars to the United States and Britain.) Einige dieser Autos wurden in die USA und nach Großbritannien exportiert."},{"id":"pas_t2_s03","en":"The cars were tested by technicians on the roof.","decode":[["The","Die"],["cars","Autos"],["were tested","wurden-getestet"],["by","von"],["technicians","Technikern"],["on","auf"],["the","dem"],["roof.","Dach."]],"de":"(Aktiv: Technicians tested the cars on the roof.) Die Autos wurden von Technikern auf dem Dach getestet."},{"id":"pas_t2_s04","en":"This car was called the Topolino.","decode":[["This","Dieses"],["car","Auto"],["was called","wurde-genannt"],["the","der"],["Topolino.","Topolino."]],"de":"(Aktiv: They called this car the Topolino.) Dieses Auto wurde 'Topolino' genannt – der italienische Name für Micky Maus."},{"id":"pas_t2_s05","en":"Today, Fiat's cars are sold all over the world.","decode":[["Today,","Heute,"],["Fiat's","Fiats"],["cars","Autos"],["are sold","werden-verkauft"],["all","überall"],["over","auf"],["the","der"],["world.","Welt."]],"de":"(Aktiv: Today, Fiat sells its cars all over the world.) Heute werden Fiats Autos auf der ganzen Welt verkauft."}]}],"exercises":[{"id":"pas_ex01","title":"Present Simple Passive","source":"The Passive Voice – Ex. 1","type":"build","instruction":"Setze die richtige Passivform im Present Simple ein: am/is/are + past participle.","questions":[{"parts":["English ",{"opts":["is","are","was"],"decode":["wird","werden","wurde"],"correct":0}," ",{"opts":["spoken","speak","spoke"],"decode":["gesprochen","sprechen","sprach"],"correct":0}," in many countries. (speak)"],"solutionEn":"English is spoken in many countries.","solutionDe":"Englisch wird in vielen Ländern gesprochen.","explain":"Present Simple Passive: is + past participle; speak–spoke–spoken. 'English' = Singular → is."},{"parts":["The post ",{"opts":["is","are","does"],"decode":["wird","werden","tut"],"correct":0}," ",{"opts":["delivered","deliver","delivering"],"decode":["zugestellt","zustellen","zustellend"],"correct":0}," at about 7 o'clock every morning. (deliver)"],"solutionEn":"The post is delivered at about 7 o'clock every morning.","solutionDe":"Die Post wird jeden Morgen gegen 7 Uhr zugestellt.","explain":"is + delivered. 'every morning' → Present Simple."},{"parts":["",{"opts":["Is","Does","Has"],"decode":["Wird","Tut","Hat"],"correct":0}," the building ",{"opts":["used","use","using"],"decode":["benutzt","benutzen","benutzend"],"correct":0}," any more? (the building / use)"],"solutionEn":"Is the building used any more?","solutionDe":"Wird das Gebäude noch benutzt?","explain":"Passivfrage: Is + Subjekt + past participle. KEIN do/does im Passiv!"},{"parts":["How often ",{"opts":["are","is","do"],"decode":["werden","wird","tun"],"correct":0}," the Olympic Games ",{"opts":["held","hold","holded"],"decode":["abgehalten","abhalten","hielt"],"correct":0},"? (the Olympic Games / hold)"],"solutionEn":"How often are the Olympic Games held?","solutionDe":"Wie oft werden die Olympischen Spiele abgehalten?","explain":"'the Olympic Games' = Plural → are; hold–held–held."},{"parts":["How ",{"opts":["is","are","does"],"decode":["wird","werden","tut"],"correct":0}," your name ",{"opts":["spelled","spell","spelling"],"decode":["buchstabiert","buchstabieren","buchstabierend"],"correct":0},"? (your name / spell)"],"solutionEn":"How is your name spelled?","solutionDe":"Wie wird dein Name geschrieben/buchstabiert?","explain":"is + spelled (britisch auch: spelt). 'your name' = Singular → is."},{"parts":["My salary ",{"opts":["is","are","have"],"decode":["wird","werden","haben"],"correct":0}," ",{"opts":["paid","payed","pay"],"decode":["bezahlt","zahlte","bezahlen"],"correct":0}," every month. (pay)"],"solutionEn":"My salary is paid every month.","solutionDe":"Mein Gehalt wird jeden Monat bezahlt.","explain":"is + paid. Achtung Schreibung: pay–paid–paid (NICHT payed)."},{"parts":["These cars ",{"opts":["are not","is not","do not"],"decode":["werden nicht","wird nicht","tun nicht"],"correct":0}," ",{"opts":["made","make","maked"],"decode":["hergestellt","herstellen","machte"],"correct":0}," in Japan. (not make)"],"solutionEn":"These cars are not made in Japan.","solutionDe":"Diese Autos werden nicht in Japan hergestellt.","explain":"Verneinung: are not + made; make–made–made. 'cars' = Plural → are."},{"parts":["The name of the people who committed the crime ",{"opts":["is not","are not","does not"],"decode":["ist nicht","sind nicht","tut nicht"],"correct":0}," ",{"opts":["known","knew","know"],"decode":["bekannt","wusste","wissen"],"correct":0},". (not know)"],"solutionEn":"The name of the people who committed the crime is not known.","solutionDe":"Der Name der Leute, die das Verbrechen begangen haben, ist nicht bekannt.","explain":"Falle! Subjekt ist 'The name' (Singular) → is not; know–knew–known."},{"parts":["His travel expenses ",{"opts":["are not","is not","have not"],"decode":["werden nicht","wird nicht","haben nicht"],"correct":0}," ",{"opts":["paid","payed","paying"],"decode":["bezahlt","zahlte","bezahlend"],"correct":0}," by his company. (not pay)"],"solutionEn":"His travel expenses are not paid by his company.","solutionDe":"Seine Reisekosten werden nicht von seiner Firma bezahlt.","explain":"'expenses' = Plural → are not + paid; Täter mit by (by his company)."}]},{"id":"pas_ex02","title":"Past Simple Passive","source":"The Passive Voice – Ex. 2","type":"build","instruction":"Setze die richtige Passivform im Past Simple ein: was/were + past participle.","questions":[{"parts":["My car ",{"opts":["was","were","is"],"decode":["wurde","wurden","wird"],"correct":0}," ",{"opts":["repaired","repair","repairing"],"decode":["repariert","reparieren","reparierend"],"correct":0}," last week. (repair)"],"solutionEn":"My car was repaired last week.","solutionDe":"Mein Auto wurde letzte Woche repariert.","explain":"Past Simple Passive: was + past participle. 'last week' → Past."},{"parts":["This song ",{"opts":["was not","were not","did not"],"decode":["wurde nicht","wurden nicht","tat nicht"],"correct":0}," ",{"opts":["written","wrote","write"],"decode":["geschrieben","schrieb","schreiben"],"correct":0}," by John Lennon. (not write)"],"solutionEn":"This song was not written by John Lennon.","solutionDe":"Dieses Lied wurde nicht von John Lennon geschrieben.","explain":"was not + written; write–wrote–written; Täter mit by."},{"parts":["",{"opts":["Was","Did","Were"],"decode":["Wurde","Tat","Wurden"],"correct":0}," the phone ",{"opts":["answered","answer","answering"],"decode":["abgehoben","abheben","abhebend"],"correct":0}," by a young girl? (the phone / answer)"],"solutionEn":"Was the phone answered by a young girl?","solutionDe":"Wurde das Telefon von einem jungen Mädchen abgehoben?","explain":"Passivfrage im Past: Was + Subjekt + past participle. 'the phone' = Singular → was; kein did im Passiv."},{"parts":["The film ",{"opts":["was","has been","were"],"decode":["wurde","ist worden","wurden"],"correct":0}," ",{"opts":["made","make","making"],"decode":["gedreht","drehen","drehend"],"correct":0}," ten years ago. (make)"],"solutionEn":"The film was made ten years ago.","solutionDe":"Der Film wurde vor zehn Jahren gedreht.","explain":"'ten years ago' → Past Simple (NICHT Present Perfect): was + made."},{"parts":["When ",{"opts":["was","did","were"],"decode":["wurde","tat","wurden"],"correct":0}," tennis ",{"opts":["invented","invent","inventing"],"decode":["erfunden","erfinden","erfindend"],"correct":0},"? (tennis / invent)"],"solutionEn":"When was tennis invented?","solutionDe":"Wann wurde Tennis erfunden?","explain":"Frage: When + was + Subjekt + past participle."},{"parts":["The car ",{"opts":["was not","were not","has not been"],"decode":["wurde nicht","wurden nicht","ist nicht worden"],"correct":0}," ",{"opts":["damaged","damage","damaging"],"decode":["beschädigt","beschädigen","beschädigend"],"correct":0}," in the accident. (not damage)"],"solutionEn":"The car was not damaged in the accident.","solutionDe":"Das Auto wurde bei dem Unfall nicht beschädigt.","explain":"was not + damaged. 'in the accident' → abgeschlossene Vergangenheit."},{"parts":["The original building ",{"opts":["was","were","had"],"decode":["wurde","wurden","hatte"],"correct":0}," ",{"opts":["pulled","pull","pulling"],"decode":["abgerissen","abreißen","abreißend"],"correct":0}," down in 1965. (pull)"],"solutionEn":"The original building was pulled down in 1965.","solutionDe":"Das ursprüngliche Gebäude wurde 1965 abgerissen.","explain":"was + pulled down (= abgerissen); Jahreszahl → Past Simple."},{"parts":["Where ",{"opts":["was","did","were"],"decode":["wurde","tat","wurden"],"correct":0}," this pot ",{"opts":["made","make","making"],"decode":["hergestellt","herstellen","herstellend"],"correct":0},"? (this pot / make)"],"solutionEn":"Where was this pot made?","solutionDe":"Wo wurde dieser Topf hergestellt?","explain":"Where + was + Subjekt + past participle; kein did im Passiv."},{"parts":["When ",{"opts":["was","were","did"],"decode":["wurde","wurden","tat"],"correct":0}," this bridge ",{"opts":["built","build","builded"],"decode":["gebaut","bauen","baute"],"correct":0},"? (this bridge / build)"],"solutionEn":"When was this bridge built?","solutionDe":"Wann wurde diese Brücke gebaut?","explain":"When + was + Subjekt + built; build–built–built."}]},{"id":"pas_ex03","title":"Fiat – Aktiv oder Passiv?","source":"The Passive Voice – Ex. 3 (Fiat-Text)","type":"mc","instruction":"Aktiv oder Passiv? Wähle die richtige Verbform für den Fiat-Text.","questions":[{"parts":["Fiat was started by a group of Italian businessmen in 1899. In 1903, Fiat ",{"opts":["produced","was produced"],"decode":["produzierte","wurde produziert"],"correct":0}," 132 cars."],"solutionEn":"In 1903, Fiat produced 132 cars.","solutionDe":"1903 produzierte Fiat 132 Autos.","explain":"Fiat handelt selbst (stellt die Autos her) und hat ein Objekt (132 cars) → Aktiv."},{"parts":["Some of these cars ",{"opts":["were exported","exported"],"decode":["wurden exportiert","exportierten"],"correct":0}," by the company to the United States and Britain."],"solutionEn":"Some of these cars were exported by the company to the United States and Britain.","solutionDe":"Einige dieser Autos wurden von der Firma in die USA und nach Großbritannien exportiert.","explain":"Die Autos exportieren nicht selbst – sie WERDEN exportiert. 'by the company' verrät das Passiv."},{"parts":["In 1920, Fiat ",{"opts":["started","was started"],"decode":["begann","wurde gegründet"],"correct":0}," making cars at a new factory at Lingotto, near Turin."],"solutionEn":"In 1920, Fiat started making cars at a new factory at Lingotto, near Turin.","solutionDe":"1920 begann Fiat, in einer neuen Fabrik in Lingotto bei Turin Autos zu bauen.","explain":"Fiat beginnt selbst etwas zu tun → Aktiv."},{"parts":["There was a track on the roof where the cars ",{"opts":["were tested","tested"],"decode":["wurden getestet","testeten"],"correct":0}," by technicians."],"solutionEn":"There was a track on the roof where the cars were tested by technicians.","solutionDe":"Auf dem Dach gab es eine Teststrecke, wo die Autos von Technikern getestet wurden.","explain":"'by technicians' → Passiv: were tested."},{"parts":["In 1936, Fiat launched the Fiat 500. This car ",{"opts":["was called","called"],"decode":["wurde genannt","nannte"],"correct":0}," the Topolino – the Italian name for Mickey Mouse."],"solutionEn":"This car was called the Topolino.","solutionDe":"Dieses Auto wurde 'Topolino' genannt.","explain":"Das Auto nennt sich nicht selbst – es WIRD genannt → Passiv."},{"parts":["The company grew, and in 1963 Fiat ",{"opts":["exported","was exported"],"decode":["exportierte","wurde exportiert"],"correct":0}," more than 300,000 vehicles."],"solutionEn":"In 1963 Fiat exported more than 300,000 vehicles.","solutionDe":"1963 exportierte Fiat mehr als 300.000 Fahrzeuge.","explain":"Fiat exportiert selbst und hat ein Objekt (vehicles) → Aktiv."},{"parts":["Today, Fiat is based in Turin, and its cars ",{"opts":["are sold","sold","are selling"],"decode":["werden verkauft","verkauften","verkaufen gerade"],"correct":0}," all over the world."],"solutionEn":"Today, Fiat is based in Turin, and its cars are sold all over the world.","solutionDe":"Heute sitzt Fiat in Turin, und seine Autos werden auf der ganzen Welt verkauft.","explain":"Die Autos verkaufen nicht selbst → Passiv; 'Today' → Present Simple: are sold."}]},{"id":"pas_ex04","title":"Aktiv → Passiv umformen","source":"The Passive Voice – Ex. 4","type":"build","instruction":"Forme den Aktivsatz ins Passiv um. Das Objekt wird zum Subjekt!","questions":[{"parts":["Aktiv: We sell tickets for all shows at the Box Office. → Tickets for all shows ",{"opts":["are","is","were"],"decode":["werden","wird","wurden"],"correct":0}," ",{"opts":["sold","selled","sell"],"decode":["verkauft","verkaufte","verkaufen"],"correct":0}," at the Box Office."],"solutionEn":"Tickets for all shows are sold at the Box Office.","solutionDe":"Karten für alle Vorstellungen werden an der Kasse verkauft.","explain":"Objekt (tickets) wird Subjekt; Zeit bleibt Present Simple: are + sold (sell–sold–sold). 'We' fällt weg."},{"parts":["Aktiv: Thomas Edison invented the electric light bulb. → The electric light bulb ",{"opts":["was","is","has been"],"decode":["wurde","wird","ist worden"],"correct":0}," ",{"opts":["invented","invent","inventing"],"decode":["erfunden","erfinden","erfindend"],"correct":0}," ",{"opts":["by","with","from"],"decode":["von","mit","aus"],"correct":0}," Thomas Edison."],"solutionEn":"The electric light bulb was invented by Thomas Edison.","solutionDe":"Die Glühbirne wurde von Thomas Edison erfunden.","explain":"Past Simple bleibt: was + invented; der Täter (agent) wird mit BY angehängt."},{"parts":["Aktiv: Someone painted the office last week. → The office ",{"opts":["was","were","is"],"decode":["wurde","wurden","wird"],"correct":0}," ",{"opts":["painted","paint","painting"],"decode":["gestrichen","streichen","streichend"],"correct":0}," last week."],"solutionEn":"The office was painted last week.","solutionDe":"Das Büro wurde letzte Woche gestrichen.","explain":"'someone' ist unwichtig/unbekannt → der Täter wird im Passiv WEGGELASSEN (kein 'by someone')."},{"parts":["Aktiv: Several people saw the accident. → The accident ",{"opts":["was","were","is"],"decode":["wurde","wurden","wird"],"correct":0}," ",{"opts":["seen","saw","see"],"decode":["gesehen","sah","sehen"],"correct":0}," by several people."],"solutionEn":"The accident was seen by several people.","solutionDe":"Der Unfall wurde von mehreren Leuten gesehen.","explain":"Neues Subjekt 'the accident' = Singular → was; see–saw–seen; Täter mit by."},{"parts":["Aktiv: Where do they make these video recorders? → Where ",{"opts":["are","do","is"],"decode":["werden","tun","wird"],"correct":0}," these video recorders ",{"opts":["made","make","making"],"decode":["hergestellt","herstellen","herstellend"],"correct":0},"?"],"solutionEn":"Where are these video recorders made?","solutionDe":"Wo werden diese Videorekorder hergestellt?","explain":"Passivfrage: Where + are + Subjekt + made. Das 'do' aus der Aktivfrage verschwindet, 'they' fällt weg."}]},{"id":"pas_ex05","title":"Passiv-Zeiten-Mix","source":"Zeitentabellen beider Grammatik-Blätter","type":"build","instruction":"Passiv in allen Zeiten: Wähle die richtige be-Form und die Verbform.","questions":[{"parts":["will-Future – Aktiv: He will deliver the letters. → The letters ",{"opts":["will be","will","will been"],"decode":["werden ... werden","werden","werden gewesen"],"correct":0}," ",{"opts":["delivered","deliver","delivering"],"decode":["zugestellt","zustellen","zustellend"],"correct":0},"."],"solutionEn":"The letters will be delivered.","solutionDe":"Die Briefe werden zugestellt werden.","explain":"will-Future Passiv: will + BE + past participle."},{"parts":["Present Perfect – Aktiv: The police have arrested him. → He ",{"opts":["has been","has","is been"],"decode":["ist ... worden","hat","ist gewesen"],"correct":0}," ",{"opts":["arrested","arrest","arresting"],"decode":["verhaftet","verhaften","verhaftend"],"correct":0},"."],"solutionEn":"He has been arrested.","solutionDe":"Er ist verhaftet worden.","explain":"Present Perfect Passiv: has/have + BEEN + past participle. Täter (Polizei) ist offensichtlich → weglassen."},{"parts":["Modalverb – Aktiv: He must deliver the letters. → The letters ",{"opts":["must be","must","must been"],"decode":["müssen ... werden","müssen","müssen gewesen"],"correct":0}," ",{"opts":["delivered","deliver","delivering"],"decode":["zugestellt","zustellen","zustellend"],"correct":0},"."],"solutionEn":"The letters must be delivered.","solutionDe":"Die Briefe müssen zugestellt werden.","explain":"Modalverb-Passiv: must/can/may + BE + past participle."},{"parts":["Present Continuous – Aktiv: He is delivering the letters. → The letters ",{"opts":["are being","are","is being"],"decode":["werden gerade","werden","wird gerade"],"correct":0}," ",{"opts":["delivered","delivering","deliver"],"decode":["zugestellt","zustellend","zustellen"],"correct":0},"."],"solutionEn":"The letters are being delivered.","solutionDe":"Die Briefe werden gerade zugestellt.","explain":"Present Continuous Passiv: am/is/are + BEING + past participle; 'letters' = Plural → are."},{"parts":["going-to-Future – Aktiv: You are going to help him. → He is going to ",{"opts":["be helped","helped","be help"],"decode":["geholfen werden","geholfen","helfen werden"],"correct":0}," by you."],"solutionEn":"He is going to be helped by you.","solutionDe":"Ihm wird von dir geholfen werden.","explain":"going-to-Future Passiv: is/are going to + BE + past participle."}]}]},{"id":"reported","title":"Reported Speech","icon":"💬","phase":1,"birkenbihl":[{"id":"rep_t1","title":"Aussagesätze – Beispielsätze (mit Backshift)","sentences":[{"id":"rep_t1_s01","en":"Sally said that she walked the dog every day.","decode":[["Sally","Sally"],["said","sagte"],["that","dass"],["she","sie"],["walked","ausführte"],["the","den"],["dog","Hund"],["every","jeden"],["day.","Tag."]],"de":"(Direkt: 'I walk the dog every day.') Sally sagte, dass sie jeden Tag den Hund ausführe."},{"id":"rep_t1_s02","en":"Sally told me that she was walking the dog.","decode":[["Sally","Sally"],["told","erzählte"],["me","mir"],["that","dass"],["she","sie"],["was walking","gerade-ausführte"],["the","den"],["dog.","Hund."]],"de":"(Direkt: 'I am walking the dog.') Sally erzählte mir, dass sie gerade den Hund ausführe."},{"id":"rep_t1_s03","en":"Sally mentioned that she would walk the dog every day.","decode":[["Sally","Sally"],["mentioned","erwähnte"],["that","dass"],["she","sie"],["would walk","ausführen-würde"],["the","den"],["dog","Hund"],["every","jeden"],["day.","Tag."]],"de":"(Direkt: 'I will walk the dog every day.') Sally erwähnte, dass sie den Hund jeden Tag ausführen würde."},{"id":"rep_t1_s04","en":"Sally answered that she had walked the dog the night before.","decode":[["Sally","Sally"],["answered","antwortete"],["that","dass"],["she","sie"],["had walked","ausgeführt-hatte"],["the","den"],["dog","Hund"],["the night before.","am-Abend-davor."]],"de":"(Direkt: 'I walked the dog last night.') Sally antwortete, dass sie den Hund am Abend davor ausgeführt habe."},{"id":"rep_t1_s05","en":"Sally said that she had walked the dog that day.","decode":[["Sally","Sally"],["said","sagte"],["that","dass"],["she","sie"],["had walked","ausgeführt-hatte"],["the","den"],["dog","Hund"],["that day.","an-jenem-Tag."]],"de":"(Direkt: 'I have walked the dog today.') Sally sagte, dass sie den Hund an jenem Tag ausgeführt habe."},{"id":"rep_t1_s06","en":"Peter said that he was at home.","decode":[["Peter","Peter"],["said","sagte"],["that","dass"],["he","er"],["was","war"],["at","zu"],["home.","Hause."]],"de":"(Direkt: 'I'm at home.') Peter sagte, dass er zu Hause sei."},{"id":"rep_t1_s07","en":"Omar said that he had never been to China.","decode":[["Omar","Omar"],["said","sagte"],["that","dass"],["he","er"],["had","war"],["never","nie"],["been","gewesen"],["to","in"],["China.","China."]],"de":"(Direkt: 'I've never been to China.') Omar sagte, dass er noch nie in China gewesen sei."},{"id":"rep_t1_s08","en":"Daniel said that he couldn't speak French.","decode":[["Daniel","Daniel"],["said","sagte"],["that","dass"],["he","er"],["couldn't","nicht-konnte"],["speak","sprechen"],["French.","Französisch."]],"de":"(Direkt: 'I can't speak French.') Daniel sagte, dass er kein Französisch sprechen könne."}]},{"id":"rep_t2","title":"Fragen und Aufforderungen – Beispielsätze","sentences":[{"id":"rep_t2_s01","en":"The policeman asked the man where he had parked the car.","decode":[["The","Der"],["policeman","Polizist"],["asked","fragte"],["the","den"],["man","Mann"],["where","wo"],["he","er"],["had parked","geparkt-hatte"],["the","das"],["car.","Auto."]],"de":"(Direkt: 'Where did you park the car?') Der Polizist fragte den Mann, wo er das Auto geparkt habe."},{"id":"rep_t2_s02","en":"The policeman asked the man whether it was his car.","decode":[["The","Der"],["policeman","Polizist"],["asked","fragte"],["the","den"],["man","Mann"],["whether","ob"],["it","es"],["was","war"],["his","sein"],["car.","Auto."]],"de":"(Direkt: 'Is this your car?') Der Polizist fragte den Mann, ob es sein Auto sei."},{"id":"rep_t2_s03","en":"She asked if I was tired.","decode":[["She","Sie"],["asked","fragte"],["if","ob"],["I","ich"],["was","war"],["tired.","müde."]],"de":"(Direkt: 'Are you tired?') Sie fragte, ob ich müde sei."},{"id":"rep_t2_s04","en":"Billy asked his brother to take him to the movies.","decode":[["Billy","Billy"],["asked","bat"],["his","seinen"],["brother","Bruder"],["to take","zu-bringen"],["him","ihn"],["to the movies.","ins-Kino."]],"de":"(Direkt: 'Could you take me to the movies?') Billy bat seinen Bruder, ihn ins Kino zu bringen."},{"id":"rep_t2_s05","en":"Jenny told Michael to hurry up.","decode":[["Jenny","Jenny"],["told","sagte"],["Michael","Michael"],["to hurry up.","sich-zu-beeilen."]],"de":"(Direkt: 'Hurry up!') Jenny sagte Michael, er solle sich beeilen."},{"id":"rep_t2_s06","en":"Jenny told Michael not to shout that way.","decode":[["Jenny","Jenny"],["told","sagte"],["Michael","Michael"],["not","nicht"],["to shout","zu-schreien"],["that way.","auf-diese-Art."]],"de":"(Direkt: 'Don't shout like that!') Jenny sagte Michael, er solle nicht so schreien."}]}],"exercises":[{"id":"rep_ex01","title":"Martins Ausreden – direkte → indirekte Rede","source":"reported-speech student B1-B2 – Practice: Dialogues 1–8","type":"build","instruction":"Martin hat Daniella letzte Woche etwas anderes erzählt. Baue Daniellas Antwort in der indirekten Rede.","questions":[{"parts":["Letzte Woche: \"I have my own business.\" – Jetzt: \"My boss gave me a promotion today!\" → Daniella: But I thought you said ",{"opts":["you had","you have","I had"],"decode":["du hattest","du hast","ich hatte"],"correct":0}," your own business."],"solutionEn":"But I thought you said you had your own business.","solutionDe":"Aber ich dachte, du hättest gesagt, du hättest eine eigene Firma.","explain":"Backshift: have (Present Simple) → had (Past Simple); Pronomen I → you, weil Daniella Martin direkt anspricht."},{"parts":["Letzte Woche: \"I've travelled all over the world.\" – Jetzt: \"I've never been to China.\" → Daniella: But I thought you told me ",{"opts":["you had travelled","you have travelled","you travelled"],"decode":["du warst gereist","du bist gereist","du reistest"],"correct":0}," all over the world."],"solutionEn":"But I thought you told me you had travelled all over the world.","solutionDe":"Aber ich dachte, du hättest mir erzählt, du seist um die ganze Welt gereist.","explain":"Backshift: have travelled (Present Perfect) → had travelled (Past Perfect)."},{"parts":["Letzte Woche: \"I have a Mercedes.\" – Jetzt: \"I take the train to work every day.\" → Daniella: But didn't you say ",{"opts":["you had","you have","you would have"],"decode":["du hattest","du hast","du hättest"],"correct":0}," a Mercedes?"],"solutionEn":"But didn't you say you had a Mercedes?","solutionDe":"Aber hast du nicht gesagt, du hättest einen Mercedes?","explain":"Backshift: have → had (Present → Past). Der Einleitungssatz (didn't you say) steht im Past."},{"parts":["Letzte Woche: \"I don't drink alcohol.\" – Jetzt: \"Let's go for a beer tomorrow evening.\" → Daniella: But you said ",{"opts":["you didn't drink","you don't drink","you hadn't drunk"],"decode":["du trankst nicht","du trinkst nicht","du hattest nicht getrunken"],"correct":0}," alcohol."],"solutionEn":"But you said you didn't drink alcohol.","solutionDe":"Aber du hast gesagt, du trinkst keinen Alkohol.","explain":"Backshift: don't drink (Present Simple) → didn't drink (Past Simple). Past Perfect wäre eine Stufe zu viel."},{"parts":["Letzte Woche: \"I can speak French fluently.\" – Jetzt: \"The waiters refused to speak English!\" → Daniella: But I thought you said ",{"opts":["you could speak","you can speak","you would speak"],"decode":["du konntest sprechen","du kannst sprechen","du würdest sprechen"],"correct":0}," French fluently."],"solutionEn":"But I thought you said you could speak French fluently.","solutionDe":"Aber ich dachte, du hättest gesagt, du könntest fließend Französisch sprechen.","explain":"Modalverb-Backshift: can → could."},{"parts":["Letzte Woche: \"I live alone.\" – Jetzt: \"Sorry, I have to answer the phone. It's my flatmate.\" → Daniella: But you told me ",{"opts":["you lived","you live","you had lived"],"decode":["du wohntest","du wohnst","du hattest gewohnt"],"correct":0}," alone."],"solutionEn":"But you told me you lived alone.","solutionDe":"Aber du hast mir erzählt, du wohnst allein.","explain":"Backshift: live → lived (Present → Past Simple). tell braucht ein Objekt: you told ME."},{"parts":["Letzte Woche: \"I'm going to Miami this summer.\" – Jetzt: \"I'm going to stay at home this summer.\" → Daniella: But didn't you say ",{"opts":["you were going","you are going","you had gone"],"decode":["du würdest fahren","du fährst","du warst gefahren"],"correct":0}," to Miami this summer?"],"solutionEn":"But didn't you say you were going to Miami this summer?","solutionDe":"Aber hast du nicht gesagt, du würdest diesen Sommer nach Miami fahren?","explain":"Backshift: are going (Present Progressive) → were going (Past Progressive). 'this summer' bleibt, weil es noch derselbe Sommer ist."},{"parts":["Letzte Woche: \"I won't forget your name.\" – Jetzt: \"It was nice to see you again, Maria.\" → Daniella: It's Daniella! I thought you said ",{"opts":["you wouldn't forget","you won't forget","you didn't forget"],"decode":["du würdest nicht vergessen","du wirst nicht vergessen","du vergaßest nicht"],"correct":0}," ",{"opts":["my","your","her"],"decode":["meinen","deinen","ihren"],"correct":0}," name."],"solutionEn":"I thought you said you wouldn't forget my name.","solutionDe":"Ich dachte, du hättest gesagt, du würdest meinen Namen nicht vergessen.","explain":"Backshift: won't → wouldn't; Pronomen: your name → my name (aus Daniellas Sicht)."}]},{"id":"rep_ex02","title":"Backshift nur wenn nötig","source":"reported-speech student B1-B2 – Practice: Reported statements 1–6","type":"gap","instruction":"Verändere die Zeit NUR, wenn es nötig ist. Achte auf die Zeitangabe im Satz!","questions":[{"parts":["Joe said, \"I'm going away this week.\" → Joe said he ",{"opts":["was going away","is going away","had gone away"],"decode":["war am Wegfahren","ist am Wegfahren","war weggefahren"],"correct":0}," that week."],"solutionEn":"Joe said he was going away that week.","solutionDe":"Joe sagte, er verreise in jener Woche.","explain":"'that week' (statt 'this week') zeigt: Die Woche ist vorbei → Backshift: am going → was going."},{"parts":["The athlete said, \"I will win the race tomorrow.\" → The athlete said he ",{"opts":["will win the race","would win the race","won the race"],"decode":["wird das Rennen gewinnen","würde das Rennen gewinnen","gewann das Rennen"],"correct":0}," tomorrow."],"solutionEn":"The athlete said he will win the race tomorrow.","solutionDe":"Der Athlet sagte, er wird das Rennen morgen gewinnen.","explain":"'tomorrow' bleibt im Satz → das Rennen ist immer noch morgen, die Situation ist unverändert → KEIN Backshift. 'would win' wäre nur richtig, wenn aus tomorrow 'the next day' würde."},{"parts":["The news reporter said, \"People have been protesting in the streets today.\" → The news reporter said people ",{"opts":["had been protesting","have been protesting","were protested"],"decode":["hatten protestiert","haben protestiert","wurden protestiert"],"correct":0}," in the streets that day."],"solutionEn":"The news reporter said people had been protesting in the streets that day.","solutionDe":"Der Reporter sagte, die Menschen hätten an jenem Tag auf den Straßen protestiert.","explain":"'that day' → Situation vorbei → Backshift: Present Perfect Progressive → Past Perfect Progressive."},{"parts":["The director said, \"The company will continue to grow next year.\" → The director said the company ",{"opts":["will continue to grow","would continue to grow","continued to grow"],"decode":["wird weiter wachsen","würde weiter wachsen","wuchs weiter"],"correct":0}," next year."],"solutionEn":"The director said the company will continue to grow next year.","solutionDe":"Der Direktor sagte, die Firma wird nächstes Jahr weiter wachsen.","explain":"'next year' bleibt → die Aussage gilt noch → KEIN Backshift nötig."},{"parts":["Last year, the doctor said, \"You need to rest more.\" → Last year, the doctor told me I ",{"opts":["needed to rest more","need to rest more","had needed to rest more"],"decode":["müsse mich mehr ausruhen","muss mich mehr ausruhen","hatte mich mehr ausruhen müssen"],"correct":0},"."],"solutionEn":"Last year, the doctor told me I needed to rest more.","solutionDe":"Letztes Jahr sagte mir der Arzt, ich müsse mich mehr ausruhen.","explain":"'Last year' → liegt lange zurück → Backshift: need → needed. Pronomen: you → I."},{"parts":["The president said, \"I won't lose the election.\" → The president said he ",{"opts":["wouldn't lose the election","won't lose the election","didn't lose the election"],"decode":["würde die Wahl nicht verlieren","wird die Wahl nicht verlieren","verlor die Wahl nicht"],"correct":0},", but he did."],"solutionEn":"The president said he wouldn't lose the election, but he did.","solutionDe":"Der Präsident sagte, er würde die Wahl nicht verlieren – aber er hat sie verloren.","explain":"'but he did' → die Situation hat sich geändert (er hat doch verloren) → Backshift: won't → wouldn't."}]},{"id":"rep_ex03","title":"Zeitverschiebung – der Backshift-Trainer","source":"Grammatik-Blätter (Klett + mein-lernen.at)","type":"gap","instruction":"Der Einleitungssatz steht im Past – wähle die richtige Zeitform für die indirekte Rede.","questions":[{"parts":["Present Simple: She said, \"I drink a coke.\" → She said that she ",{"opts":["drank","drinks","had drunk"],"decode":["trank","trinkt","hatte getrunken"],"correct":0}," a coke."],"solutionEn":"She said that she drank a coke.","solutionDe":"Sie sagte, dass sie eine Cola trinke.","explain":"Present Simple → Past Simple (drink → drank)."},{"parts":["Present Progressive: Sally said, \"I am walking the dog.\" → Sally said that she ",{"opts":["was walking","is walking","walked"],"decode":["führte gerade aus","führt gerade aus","führte aus"],"correct":0}," the dog."],"solutionEn":"Sally said that she was walking the dog.","solutionDe":"Sally sagte, dass sie gerade den Hund ausführe.","explain":"Present Progressive → Past Progressive (am walking → was walking)."},{"parts":["Past Simple: She said, \"I drank a coke.\" → She said that she ",{"opts":["had drunk","drank","has drunk"],"decode":["hatte getrunken","trank","hat getrunken"],"correct":0}," a coke."],"solutionEn":"She said that she had drunk a coke.","solutionDe":"Sie sagte, dass sie eine Cola getrunken habe.","explain":"Past Simple → Past Perfect (drank → had drunk)."},{"parts":["Present Perfect: She said, \"I have drunk a coke.\" → She said that she ",{"opts":["had drunk","has drunk","drank"],"decode":["hatte getrunken","hat getrunken","trank"],"correct":0}," a coke."],"solutionEn":"She said that she had drunk a coke.","solutionDe":"Sie sagte, dass sie eine Cola getrunken habe.","explain":"Present Perfect → Past Perfect (have drunk → had drunk)."},{"parts":["will-Future: She said, \"I will drink a coke.\" → She said that she ",{"opts":["would drink","will drink","would drank"],"decode":["würde trinken","wird trinken","würde trank"],"correct":0}," a coke."],"solutionEn":"She said that she would drink a coke.","solutionDe":"Sie sagte, dass sie eine Cola trinken würde.","explain":"will → would; nach would steht immer der Infinitiv (drink, nicht drank)."},{"parts":["going-to-Future: She said, \"I am going to drink a coke.\" → She said that she ",{"opts":["was going to drink","is going to drink","had gone to drink"],"decode":["würde trinken","wird gleich trinken","war trinken gegangen"],"correct":0}," a coke."],"solutionEn":"She said that she was going to drink a coke.","solutionDe":"Sie sagte, dass sie eine Cola trinken werde.","explain":"going-to-Future: am/is going to → was/were going to."},{"parts":["Modalverb can: Tom said, \"I can help you.\" → Tom said that he ",{"opts":["could help","can help","could helped"],"decode":["könne helfen","kann helfen","könnte half"],"correct":0}," me."],"solutionEn":"Tom said that he could help me.","solutionDe":"Tom sagte, dass er mir helfen könne.","explain":"Modalverb: can → could; Pronomen: I → he, you → me."},{"parts":["Modalverb may: She said, \"I may be late.\" → She said that she ",{"opts":["might be","may be","might was"],"decode":["könnte sein","kann sein","könnte war"],"correct":0}," late."],"solutionEn":"She said that she might be late.","solutionDe":"Sie sagte, dass sie vielleicht zu spät kommen könnte.","explain":"Modalverb: may → might."},{"parts":["Fakten: He said, \"The Rhine flows through Vorarlberg.\" → He said that the Rhine ",{"opts":["flows","flowed","had flowed"],"decode":["fließt","floss","war geflossen"],"correct":0}," through Vorarlberg."],"solutionEn":"He said that the Rhine flows through Vorarlberg.","solutionDe":"Er sagte, dass der Rhein durch Vorarlberg fließt.","explain":"Allgemeine Fakten und Wahrheiten: KEINE Zeitverschiebung nötig."},{"parts":["Einleitungssatz im Present: Frank says, \"Mary buys new shoes.\" → Frank says that Mary ",{"opts":["buys","bought","had bought"],"decode":["kauft","kaufte","hatte gekauft"],"correct":0}," new shoes."],"solutionEn":"Frank says that Mary buys new shoes.","solutionDe":"Frank sagt, dass Mary neue Schuhe kauft.","explain":"Einleitungsverb im Present/Present Perfect/Future (says) → KEIN Backshift."}]},{"id":"rep_ex04","title":"Zeit- und Ortsangaben","source":"Grammatik-Blätter (Klett + mein-lernen.at)","type":"mc","instruction":"Wähle die richtige Zeit- bzw. Ortsangabe für die indirekte Rede.","questions":[{"parts":["\"I am busy now,\" she said. → She said she was busy ",{"opts":["then","now","today"],"decode":["dann/da","jetzt","heute"],"correct":0},"."],"solutionEn":"She said she was busy then.","solutionDe":"Sie sagte, sie sei da gerade beschäftigt.","explain":"now → then."},{"parts":["\"I saw him yesterday,\" Tom said. → Tom said he had seen him ",{"opts":["the day before","yesterday","the next day"],"decode":["am Tag davor","gestern","am nächsten Tag"],"correct":0},"."],"solutionEn":"Tom said he had seen him the day before.","solutionDe":"Tom sagte, er habe ihn am Tag davor gesehen.","explain":"yesterday → the day before / the previous day; außerdem Backshift saw → had seen."},{"parts":["\"We will meet tomorrow,\" they said. → They said they would meet ",{"opts":["the next day","tomorrow","the last day"],"decode":["am nächsten Tag","morgen","am letzten Tag"],"correct":0},"."],"solutionEn":"They said they would meet the next day.","solutionDe":"Sie sagten, sie würden sich am nächsten Tag treffen.","explain":"tomorrow → the next day / the following day."},{"parts":["\"I like it here,\" Ann said. → Ann said she liked it ",{"opts":["there","here","everywhere"],"decode":["dort","hier","überall"],"correct":0},"."],"solutionEn":"Ann said she liked it there.","solutionDe":"Ann sagte, es gefalle ihr dort.","explain":"here → there."},{"parts":["\"I am leaving today,\" he said. → He said he was leaving ",{"opts":["that day","this day","today"],"decode":["an jenem Tag","an diesem Tag","heute"],"correct":0},"."],"solutionEn":"He said he was leaving that day.","solutionDe":"Er sagte, er reise an jenem Tag ab.","explain":"today → that day."},{"parts":["\"I bought this car last week,\" he said. → He said he had bought ",{"opts":["that","this","these"],"decode":["jenes","dieses","diese"],"correct":0}," car ",{"opts":["the week before","last week","the next week"],"decode":["die Woche davor","letzte Woche","nächste Woche"],"correct":0},"."],"solutionEn":"He said he had bought that car the week before.","solutionDe":"Er sagte, er habe jenes Auto in der Woche davor gekauft.","explain":"this → that; last week → the week before / the previous week."},{"parts":["\"We are moving next week,\" she said. → She said they were moving ",{"opts":["the following week","next week","the previous week"],"decode":["die folgende Woche","nächste Woche","die Woche davor"],"correct":0},"."],"solutionEn":"She said they were moving the following week.","solutionDe":"Sie sagte, sie würden in der folgenden Woche umziehen.","explain":"next week → the following week; Pronomen: we → they."},{"parts":["\"I started my job a year ago,\" he said. → He said he had started his job ",{"opts":["the previous year","a year ago","the following year"],"decode":["im Jahr davor","vor einem Jahr","im folgenden Jahr"],"correct":0},"."],"solutionEn":"He said he had started his job the previous year.","solutionDe":"Er sagte, er habe seinen Job im Jahr davor begonnen.","explain":"a year ago → the previous year / the year before; außerdem Backshift started → had started."}]},{"id":"rep_ex05","title":"Reported questions & commands","source":"mein-lernen.at Blatt 3 + Klett-Blatt","type":"build","instruction":"Bilde indirekte Fragen und Aufforderungen.","questions":[{"parts":["He said, \"Where do you buy your car?\" → He wanted to know where I ",{"opts":["bought","buy","had bought"],"decode":["kaufte","kaufe","hatte gekauft"],"correct":0}," my car."],"solutionEn":"He wanted to know where I bought my car.","solutionDe":"Er wollte wissen, wo ich mein Auto kaufe.","explain":"Fragewort (where) bleibt; Aussagesatz-Wortstellung ohne do; Backshift: buy → bought; Pronomen: you → I."},{"parts":["She said, \"Are you tired?\" → She asked ",{"opts":["if","that","what"],"decode":["ob","dass","was"],"correct":0}," I ",{"opts":["was","am","had been"],"decode":["war","bin","war gewesen"],"correct":0}," tired."],"solutionEn":"She asked if I was tired.","solutionDe":"Sie fragte, ob ich müde sei.","explain":"Frage OHNE Fragewort → if/whether (= ob); Backshift: are → was."},{"parts":["\"Where did you park the car?\" → The policeman asked the man where ",{"opts":["he had parked","had he parked","did he park"],"decode":["er geparkt hatte","hatte er geparkt","parkte er"],"correct":0}," the car."],"solutionEn":"The policeman asked the man where he had parked the car.","solutionDe":"Der Polizist fragte den Mann, wo er das Auto geparkt habe.","explain":"Indirekte Frage = Aussagesatz-Wortstellung (Subjekt VOR Verb), kein did; Past Simple → Past Perfect."},{"parts":["Höfliche Bitte: She said, \"Help me, please.\" → She ",{"opts":["asked","told","shouted at"],"decode":["bat","befahl","schrie an"],"correct":0}," me ",{"opts":["to help","help","helping"],"decode":["zu helfen","helfen","helfend"],"correct":0}," her."],"solutionEn":"She asked me to help her.","solutionDe":"Sie bat mich, ihr zu helfen.","explain":"Höfliche Bitte (please) → ask + Objekt + to-Infinitiv; Pronomen: me → her."},{"parts":["Aufforderung: She said, \"Help me.\" → She ",{"opts":["told","asked","suggested"],"decode":["forderte auf","bat","schlug vor"],"correct":0}," me to help her."],"solutionEn":"She told me to help her.","solutionDe":"Sie forderte mich auf, ihr zu helfen.","explain":"Normale Aufforderung → tell + Objekt + to-Infinitiv."},{"parts":["Verneinte Aufforderung: Jenny said, \"Don't shout like that!\" → Jenny told Michael ",{"opts":["not to shout","to not shout","don't shout"],"decode":["nicht zu schreien","zu nicht schreien","schrei nicht"],"correct":0}," that way."],"solutionEn":"Jenny told Michael not to shout that way.","solutionDe":"Jenny sagte Michael, er solle nicht so schreien.","explain":"Verneinte Aufforderung → told + Objekt + NOT + to-Infinitiv. 'not' steht VOR 'to'."},{"parts":["Bitte: Billy said, \"Could you take me to the movies?\" → Billy asked his brother ",{"opts":["to take","take","that he took"],"decode":["zu bringen","bringen","dass er brachte"],"correct":0}," him to the movies."],"solutionEn":"Billy asked his brother to take him to the movies.","solutionDe":"Billy bat seinen Bruder, ihn ins Kino zu bringen.","explain":"Bitte (Could you ...?) → ask + Objekt + to-Infinitiv; Pronomen: me → him."},{"parts":["Vorschlag: Alex said, \"Let's go to the cinema.\" → Alex suggested ",{"opts":["going","to go","go"],"decode":["zu gehen (-ing)","zu gehen (Infinitiv)","gehen"],"correct":0}," to the cinema."],"solutionEn":"Alex suggested going to the cinema.","solutionDe":"Alex schlug vor, ins Kino zu gehen.","explain":"suggest + Verb-ing (oder: suggested that we go). 'suggested to go' ist FALSCH."}]}]},{"id":"modals","title":"Modal Verbs","icon":"🧭","phase":2,"birkenbihl":[{"id":"mod_t1","title":"Fähigkeit, Verpflichtung, Verbot – Beispielsätze","sentences":[{"id":"mod_t1_s01","en":"I can help you if you like.","decode":[["I","ich"],["can","kann"],["help","helfen"],["you","dir"],["if","wenn"],["you","du"],["like.","möchtest."]],"de":"Ich kann dir helfen, wenn du möchtest. (can = Fähigkeit, Gegenwart)"},{"id":"mod_t1_s02","en":"He could swim when he was three years old.","decode":[["He","er"],["could","konnte"],["swim","schwimmen"],["when","als"],["he","er"],["was","war"],["three years old.","drei-Jahre-alt."]],"de":"Er konnte mit drei Jahren schwimmen. (could = Fähigkeit in der Vergangenheit)"},{"id":"mod_t1_s03","en":"She will be able to swim after a few more lessons.","decode":[["She","sie"],["will be able to","wird-imstande-sein-zu"],["swim","schwimmen"],["after","nach"],["a few","ein-paar"],["more","weiteren"],["lessons.","Übungsstunden."]],"de":"Nach ein paar weiteren Stunden wird sie schwimmen können. (Zukunft: will be able to statt can)"},{"id":"mod_t1_s04","en":"All Austrian children have to start school at the age of six.","decode":[["All","alle"],["Austrian","österreichischen"],["children","Kinder"],["have to","müssen"],["start","beginnen"],["school","Schule"],["at the age of","im-Alter-von"],["six.","sechs."]],"de":"Alle österreichischen Kinder müssen mit sechs Jahren in die Schule kommen. (have to = Verpflichtung von außen)"},{"id":"mod_t1_s05","en":"I must try harder at school.","decode":[["I","ich"],["must","muss"],["try","versuchen"],["harder","härter"],["at school.","in-der-Schule."]],"de":"Ich muss mich in der Schule mehr anstrengen. (must = eigene, persönliche Verpflichtung)"},{"id":"mod_t1_s06","en":"You do not have to clean your room today.","decode":[["You","du"],["do not have to","musst-nicht"],["clean","aufräumen"],["your","dein"],["room","Zimmer"],["today.","heute."]],"de":"Du musst dein Zimmer heute nicht aufräumen. (do not have to = keine Verpflichtung)"},{"id":"mod_t1_s07","en":"Drivers must not drive under the influence of alcohol.","decode":[["Drivers","Autofahrer"],["must not","dürfen-nicht"],["drive","fahren"],["under the influence of","unter-dem-Einfluss-von"],["alcohol.","Alkohol."]],"de":"Autofahrer dürfen nicht unter Alkoholeinfluss fahren. (must not = Verbot!)"}]},{"id":"mod_t2","title":"Rat, Erlaubnis, Möglichkeit, Sicherheit – Beispielsätze","sentences":[{"id":"mod_t2_s01","en":"You should go to bed if you are tired.","decode":[["You","du"],["should","solltest"],["go","gehen"],["to bed","ins-Bett"],["if","wenn"],["you","du"],["are","bist"],["tired.","müde."]],"de":"Du solltest ins Bett gehen, wenn du müde bist. (should = Rat)"},{"id":"mod_t2_s02","en":"We ought to do more exercises to pass next week's exam.","decode":[["We","wir"],["ought to","sollten"],["do","machen"],["more","mehr"],["exercises","Übungen"],["to pass","um-zu-bestehen"],["next week's","der-nächsten-Woche"],["exam.","Prüfung."]],"de":"Wir sollten mehr Übungen machen, um die Prüfung nächste Woche zu bestehen. (ought to = should)"},{"id":"mod_t2_s03","en":"May I go to Pete's birthday party next Saturday?","decode":[["May","darf"],["I","ich"],["go","gehen"],["to","zu"],["Pete's","Petes"],["birthday party","Geburtstagsparty"],["next","nächsten"],["Saturday?","Samstag?"]],"de":"Darf ich nächsten Samstag zu Petes Geburtstagsparty gehen? (may = höfliche Erlaubnis)"},{"id":"mod_t2_s04","en":"It might rain tomorrow.","decode":[["It","es"],["might","könnte"],["rain","regnen"],["tomorrow.","morgen."]],"de":"Es könnte morgen regnen. (might = Möglichkeit, vielleicht)"},{"id":"mod_t2_s05","en":"That may be the postman.","decode":[["That","das"],["may","könnte"],["be","sein"],["the","der"],["postman.","Postbote."]],"de":"Das könnte der Postbote sein. (may/might/could = vielleicht)"},{"id":"mod_t2_s06","en":"Anne should be on her way now.","decode":[["Anne","Anne"],["should","dürfte"],["be","sein"],["on her way","auf-dem-Weg"],["now.","jetzt."]],"de":"Anne dürfte jetzt unterwegs sein. (should = Wahrscheinlichkeit, „müsste eigentlich“)"},{"id":"mod_t2_s07","en":"You must be tired after this long journey.","decode":[["You","du"],["must","musst"],["be","sein"],["tired","müde"],["after","nach"],["this","dieser"],["long","langen"],["journey.","Reise."]],"de":"Du musst nach dieser langen Reise müde sein. (must = ich bin sicher; Gegenteil: can't be)"}]}],"exercises":[{"id":"mod_ex01","title":"Welche Funktion? (Fähigkeit, Rat, Verbot …)","source":"Modal Verbs Grammar (PPTX) – Practice-Folien 17/18","type":"mc","instruction":"Welche Funktion hat das Modalverb in diesem Satz?","questions":[{"parts":["She can speak three languages fluently. → Funktion: ",{"opts":["permission","ability","possibility"],"decode":["Erlaubnis","Fähigkeit","Möglichkeit"],"correct":1}],"solutionEn":"She can speak three languages fluently. → ability","solutionDe":"Sie kann drei Sprachen fließend sprechen. → Fähigkeit","explain":"can + Grundverb = Fähigkeit in der Gegenwart (können)."},{"parts":["When he was younger, he could run 10 miles without stopping. → Funktion: ",{"opts":["past ability","past permission","advice"],"decode":["Fähigkeit-in-der-Vergangenheit","Erlaubnis-in-der-Vergangenheit","Rat"],"correct":0}],"solutionEn":"When he was younger, he could run 10 miles without stopping. → past ability","solutionDe":"Als er jünger war, konnte er 10 Meilen ohne Pause laufen. → Fähigkeit in der Vergangenheit","explain":"could = Vergangenheitsform von can: Fähigkeit in der Vergangenheit."},{"parts":["May I borrow your pen for a moment? → Funktion: ",{"opts":["obligation","probability","formal permission"],"decode":["Verpflichtung","Wahrscheinlichkeit","höfliche-Erlaubnis"],"correct":2}],"solutionEn":"May I borrow your pen for a moment? → formal permission","solutionDe":"Darf ich mir kurz deinen Stift ausborgen? → höfliche/formelle Erlaubnis","explain":"May I …? = höfliche, formelle Frage nach Erlaubnis. Umgangssprachlich: Can I …?"},{"parts":["It looks cloudy today. It might rain later. → Funktion: ",{"opts":["possibility","certainty","ability"],"decode":["Möglichkeit","Sicherheit","Fähigkeit"],"correct":0}],"solutionEn":"It looks cloudy today. It might rain later. → possibility","solutionDe":"Es ist bewölkt. Es könnte später regnen. → Möglichkeit","explain":"might/may/could = Möglichkeit (vielleicht). must wäre Sicherheit."},{"parts":["You should see a doctor about that cough. → Funktion: ",{"opts":["obligation","advice","permission"],"decode":["Verpflichtung","Rat","Erlaubnis"],"correct":1}],"solutionEn":"You should see a doctor about that cough. → advice / recommendation","solutionDe":"Du solltest wegen des Hustens zum Arzt gehen. → Rat/Empfehlung","explain":"should/ought to = Rat (solltest). must wäre eine starke Pflicht."},{"parts":["You must wear a seatbelt while driving. → Funktion: ",{"opts":["advice","possibility","obligation"],"decode":["Rat","Möglichkeit","Verpflichtung"],"correct":2}],"solutionEn":"You must wear a seatbelt while driving. → obligation / strong necessity","solutionDe":"Du musst beim Autofahren einen Gurt tragen. → Verpflichtung (Gesetz/Regel)","explain":"must = starke Verpflichtung, Regel oder Gesetz."}]},{"id":"mod_ex02","title":"Das richtige Modalverb wählen","source":"modals_extension – Practise 1–14","type":"gap","instruction":"Wähle das richtige Modalverb.","questions":[{"parts":["My son ",{"opts":["have to","would","should","could"],"decode":["müssen","würde","müsste/sollte","könnte"],"correct":2}," be home by now. Where can he be?"],"solutionEn":"My son should be home by now. Where can he be?","solutionDe":"Mein Sohn müsste inzwischen zu Hause sein. Wo kann er nur sein?","explain":"should = Erwartung/Wahrscheinlichkeit („müsste eigentlich“). have to passt grammatikalisch nicht (er → has to)."},{"parts":["I think your thumb is broken. You ",{"opts":["might","could","ought to","can"],"decode":["könntest","könntest","solltest","kannst"],"correct":2}," go to the emergency room."],"solutionEn":"I think your thumb is broken. You ought to go to the emergency room.","solutionDe":"Ich glaube, dein Daumen ist gebrochen. Du solltest in die Notaufnahme gehen.","explain":"ought to = dringender Rat (wie should). might/could wären nur vage Möglichkeiten – hier ist klarer Rat gefragt."},{"parts":["If you are interested in losing weight, you ",{"opts":["could","mustn't","don't have to","had to"],"decode":["könntest","darfst-nicht","musst-nicht","musstest"],"correct":0}," try this new diet."],"solutionEn":"If you are interested in losing weight, you could try this new diet.","solutionDe":"Wenn du abnehmen willst, könntest du diese neue Diät ausprobieren.","explain":"could = Vorschlag („du könntest …“). mustn't (Verbot) und don't have to (keine Pflicht) ergeben hier keinen Sinn."},{"parts":["John's fallen down the stairs! I ",{"opts":["will","might","may","ought to"],"decode":["werde","könnte","könnte","sollte"],"correct":0}," call an ambulance!"],"solutionEn":"John's fallen down the stairs! I will call an ambulance!","solutionDe":"John ist die Treppe hinuntergefallen! Ich rufe (sofort) einen Krankenwagen!","explain":"will = spontane Entscheidung im Moment des Sprechens. might/may (vielleicht) wären in diesem Notfall absurd."},{"parts":["You ",{"opts":["has to","must","needn't","can't"],"decode":["muss-(falsche-Form)","musst","brauchst-nicht","kannst-nicht"],"correct":2}," come too early. We won't leave until 9 o'clock."],"solutionEn":"You needn't come too early. We won't leave until 9 o'clock.","solutionDe":"Du brauchst nicht zu früh zu kommen. Wir fahren erst um 9 Uhr los.","explain":"needn't = musst nicht / brauchst nicht (keine Notwendigkeit). has to wäre 3. Person Singular."},{"parts":["Children ",{"opts":["ought to","must","would","mustn't"],"decode":["sollten","müssen","würden","dürfen-nicht"],"correct":1}," be accompanied by an adult at the zoo."],"solutionEn":"Children must be accompanied by an adult at the zoo.","solutionDe":"Kinder müssen im Zoo von einem Erwachsenen begleitet werden.","explain":"must = Regel/Vorschrift. ought to wäre nur ein Rat – hier ist es eine Zoo-Regel."},{"parts":["You ",{"opts":["don't have to","mustn't","couldn't","ought to"],"decode":["musst-nicht","darfst-nicht","konntest-nicht","solltest"],"correct":1}," talk during tests. It's forbidden!"],"solutionEn":"You mustn't talk during tests. It's forbidden!","solutionDe":"Du darfst während Tests nicht reden. Es ist verboten!","explain":"mustn't = Verbot (nicht dürfen). Achtung: don't have to = „musst nicht“ (keine Pflicht) – das wäre hier falsch, denn es IST verboten."},{"parts":["I can feel the heat. We ",{"opts":["can","would","must","have to"],"decode":["können","würden","müssen-(sicher)","müssen-(Pflicht)"],"correct":2}," be near the fire."],"solutionEn":"I can feel the heat. We must be near the fire.","solutionDe":"Ich spüre die Hitze. Wir müssen (ganz sicher) in der Nähe des Feuers sein.","explain":"must = logische Schlussfolgerung / Sicherheit („ich bin sicher, dass …“), nicht Verpflichtung."},{"parts":["They ",{"opts":["wouldn't","mustn't","shouldn't","couldn't"],"decode":["würden-nicht","dürfen-nicht","sollten-nicht","konnten-nicht"],"correct":3}," hear him because he was whispering."],"solutionEn":"They couldn't hear him because he was whispering.","solutionDe":"Sie konnten ihn nicht hören, weil er flüsterte.","explain":"couldn't = konnten nicht (verneinte Fähigkeit in der Vergangenheit)."},{"parts":["You've never heard of Britney Spears? You ",{"opts":["must","had to","can't","shouldn't"],"decode":["musst","musstest","kannst-nicht","solltest-nicht"],"correct":2}," be serious!"],"solutionEn":"You've never heard of Britney Spears? You can't be serious!","solutionDe":"Du hast noch nie von Britney Spears gehört? Das kann nicht dein Ernst sein!","explain":"can't = Sicherheit, dass etwas NICHT so ist (Gegenteil von must = sicher so)."},{"parts":[{"opts":["Could","May","Should","Would"],"decode":["könntest","dürftest","solltest","würdest"],"correct":3}," you like to have dinner with me tonight?"],"solutionEn":"Would you like to have dinner with me tonight?","solutionDe":"Möchtest du heute Abend mit mir essen gehen?","explain":"Would you like …? = feste höfliche Wendung für Angebote/Einladungen („Möchtest du …?“)."},{"parts":["You ",{"opts":["mustn't","wouldn't","couldn't","can"],"decode":["darfst-nicht","würdest-nicht","könntest-nicht","kannst"],"correct":0}," let him hear about the party tomorrow. It's a surprise!"],"solutionEn":"You mustn't let him hear about the party tomorrow. It's a surprise!","solutionDe":"Er darf auf keinen Fall von der Party morgen erfahren. Es ist eine Überraschung!","explain":"mustn't = Verbot: Du darfst ihn nichts davon hören lassen."},{"parts":[{"opts":["Must","May","Would","Need"],"decode":["muss","darf","würde","brauche"],"correct":1}," I speak to the Chief Councellor, please?"],"solutionEn":"May I speak to the Chief Councellor, please?","solutionDe":"Dürfte ich bitte mit dem Chief Councellor sprechen?","explain":"May I …? = sehr höfliche, formelle Bitte um Erlaubnis – passt zu „please“ und der förmlichen Situation."},{"parts":["He has arrived late. He ",{"opts":["must have","should have","could have","must"],"decode":["muss-sicher-…-haben","hätte-…-sollen","hätte-…-können","muss"],"correct":0}," missed the bus."],"solutionEn":"He has arrived late. He must have missed the bus.","solutionDe":"Er ist zu spät gekommen. Er hat sicher den Bus verpasst.","explain":"must have + 3. Verbform = logische Schlussfolgerung über die Vergangenheit. must allein bräuchte einen Gegenwartssatz."}]},{"id":"mod_ex03","title":"Sätze umformen mit Modalverben","source":"modals_extension – More practise 1–6 (an den Possible answers ausgerichtet)","type":"gap","instruction":"Forme den Satz mit einem Modalverb um: Wähle die richtige Ergänzung.","questions":[{"parts":["I suggest that you get a good lawyer! → You ",{"opts":["must get","should get","might get"],"decode":["musst-nehmen","solltest-nehmen","nimmst-vielleicht"],"correct":1}," a good lawyer."],"solutionEn":"You should get a good lawyer.","solutionDe":"Du solltest dir einen guten Anwalt nehmen.","explain":"I suggest (Vorschlag/Rat) → should."},{"parts":["A university degree isn't necessary for that job. → You ",{"opts":["mustn't have","don't have to have","can't have"],"decode":["darfst-nicht-haben","musst-nicht-haben","kannst-nicht-haben"],"correct":1}," a university degree for that job."],"solutionEn":"You don't have to have a university degree for that job. (auch: You needn't have a university degree …)","solutionDe":"Du musst für diesen Job keinen Universitätsabschluss haben.","explain":"nicht notwendig = don't have to / needn't. Achtung: mustn't wäre ein Verbot!"},{"parts":["Perhaps my father will pick you up. → My father ",{"opts":["should pick","may pick","has to pick"],"decode":["sollte-abholen","holt-vielleicht-ab","muss-abholen"],"correct":1}," you up."],"solutionEn":"My father may pick you up. (auch: might pick you up)","solutionDe":"Mein Vater holt dich vielleicht ab.","explain":"perhaps (vielleicht) = Möglichkeit → may/might."},{"parts":["Eating is forbidden in class! → You ",{"opts":["don't have to eat","shouldn't eat","mustn't eat"],"decode":["musst-nicht-essen","solltest-nicht-essen","darfst-nicht-essen"],"correct":2}," in class."],"solutionEn":"You mustn't eat in class.","solutionDe":"Du darfst in der Klasse nicht essen.","explain":"forbidden (verboten) → mustn't. don't have to hieße nur „musst nicht“."},{"parts":["Look at his dirty clothes! I'm sure he is a poor person. → He ",{"opts":["might be","can't be","must be"],"decode":["ist-vielleicht","kann-nicht-sein","muss-sein"],"correct":2}," a poor person."],"solutionEn":"He must be a poor person.","solutionDe":"Er muss (ganz sicher) ein armer Mensch sein.","explain":"I'm sure (positiv) → must be (Sicherheit). might wäre nur „vielleicht“."},{"parts":["I don't believe that the legend of Hercules is true – there are many contradictions. → The legend of Hercules ",{"opts":["can't be","mustn't be","may not be"],"decode":["kann-nicht-sein","darf-nicht-sein","ist-vielleicht-nicht"],"correct":0}," true."],"solutionEn":"The legend of Hercules can't be true.","solutionDe":"Die Hercules-Legende kann nicht wahr sein.","explain":"Sicher NICHT wahr → can't be (verneinte Sicherheit). mustn't wäre ein Verbot, may not nur „vielleicht nicht“."}]},{"id":"mod_ex04","title":"Gleiche Bedeutung erkennen","source":"WS-Modals-2 – Grammar 11, Ex. 4","type":"mc","instruction":"Welcher Satz bedeutet (fast) dasselbe wie der vorgegebene Satz?","questions":[{"parts":["It's possible that we'll know the answers tomorrow. → ",{"opts":["We may know the answers tomorrow.","We should know the answers tomorrow."],"decode":["wir-wissen-vielleicht-morgen","wir-müssten-morgen-eigentlich-wissen"],"correct":0}],"solutionEn":"We may know the answers tomorrow.","solutionDe":"Vielleicht kennen wir morgen die Antworten.","explain":"It's possible = Möglichkeit → may. should wäre Erwartung („müsste eigentlich“)."},{"parts":["I don't think you should ring him now. It's rather late. → ",{"opts":["You might not ring him now. It's rather late.","You'd better not ring him now. It's rather late."],"decode":["du-rufst-vielleicht-nicht-an","du-solltest-besser-nicht-anrufen"],"correct":1}],"solutionEn":"You'd better not ring him now. It's rather late.","solutionDe":"Du rufst ihn jetzt besser nicht an. Es ist ziemlich spät.","explain":"had better (not) = dringender Rat/Empfehlung. might not = nur „vielleicht nicht“ – kein Rat."},{"parts":["You needn't come if you don't want to. → ",{"opts":["You won't come if you don't want to.","You don't have to come if you don't want to."],"decode":["du-wirst-nicht-kommen","du-musst-nicht-kommen"],"correct":1}],"solutionEn":"You don't have to come if you don't want to.","solutionDe":"Du musst nicht kommen, wenn du nicht willst.","explain":"needn't = don't have to = keine Verpflichtung."},{"parts":["I think it's wrong for you to work so hard. → ",{"opts":["You don't have to work so hard.","You shouldn't work so hard."],"decode":["du-musst-nicht-so-hart-arbeiten","du-solltest-nicht-so-hart-arbeiten"],"correct":1}],"solutionEn":"You shouldn't work so hard.","solutionDe":"Du solltest nicht so hart arbeiten.","explain":"„I think it's wrong“ = Kritik/Rat → shouldn't. don't have to = keine Pflicht (andere Bedeutung!)."},{"parts":["Perhaps these are the keys. → ",{"opts":["These might be the keys.","These must be the keys."],"decode":["das-könnten-die-Schlüssel-sein","das-müssen-die-Schlüssel-sein"],"correct":0}],"solutionEn":"These might be the keys.","solutionDe":"Das könnten die Schlüssel sein.","explain":"Perhaps = vielleicht → might (Möglichkeit). must = Sicherheit."},{"parts":["It would be wrong for us to lock the cat in the house for a week. → ",{"opts":["We'd better not lock the cat in the house for a week.","We can't lock the cat in the house for a week."],"decode":["wir-sollten-besser-nicht-einsperren","das-können/dürfen-wir-nicht-machen"],"correct":1}],"solutionEn":"We can't lock the cat in the house for a week.","solutionDe":"Wir können die Katze unmöglich eine Woche im Haus einsperren. (Das wäre falsch.)","explain":"„It would be wrong“ = moralisch unmöglich → can't. had better not wäre eine Warnung (sonst passiert etwas Schlimmes)."},{"parts":["It's possible that the decision will be announced next week. → ",{"opts":["The decision might be announced next week.","The decision will be announced next week."],"decode":["wird-vielleicht-verkündet","wird-sicher-verkündet"],"correct":0}],"solutionEn":"The decision might be announced next week.","solutionDe":"Die Entscheidung wird vielleicht nächste Woche verkündet.","explain":"possible → might (Möglichkeit). will = sichere Zukunft."},{"parts":["Although I try hard, I can never solve The Times crossword. → ",{"opts":["Try as I may, I can never solve The Times crossword.","Try as I can, I may never solve The Times crossword."],"decode":["sosehr-ich-es-auch-versuche","(diese-Struktur-gibt-es-nicht)"],"correct":0}],"solutionEn":"Try as I may, I can never solve The Times crossword.","solutionDe":"Sosehr ich es auch versuche – ich kann das Times-Kreuzworträtsel nie lösen.","explain":"Feste Wendung: Try as I may (Gegenwart) / Try as I might (Vergangenheit) = sosehr ich es auch versuche."},{"parts":["I know. Why don't we go out to eat instead? → ",{"opts":["I know. We must go out to eat instead.","I know. We could go out to eat instead."],"decode":["wir-müssen-stattdessen-essen-gehen","wir-könnten-stattdessen-essen-gehen"],"correct":1}],"solutionEn":"I know. We could go out to eat instead.","solutionDe":"Ich weiß was – wir könnten stattdessen essen gehen.","explain":"Why don't we …? = Vorschlag → could (could wird für Vorschläge verwendet)."}]},{"id":"mod_ex05","title":"Modalverben in der Vergangenheit","source":"WS-Modals-2 – Grammar 12, Ex. 1 (Auswahl)","type":"gap","instruction":"Vergangenheit: Wähle die richtige Modalverb-Form.","questions":[{"parts":["That ",{"opts":["can't have been","shouldn't have been"],"decode":["kann-nicht-gewesen-sein","hätte-nicht-sein-sollen"],"correct":0}," Nick that you saw."],"solutionEn":"That can't have been Nick that you saw.","solutionDe":"Das kann unmöglich Nick gewesen sein, den du gesehen hast.","explain":"can't have + 3. Verbform = Sicherheit, dass etwas in der Vergangenheit NICHT so war."},{"parts":["I caught a later train because I ",{"opts":["had to see","must have seen"],"decode":["musste-treffen","muss-getroffen-haben"],"correct":0}," a client."],"solutionEn":"I caught a later train because I had to see a client.","solutionDe":"Ich habe einen späteren Zug genommen, weil ich einen Kunden treffen musste.","explain":"had to = Vergangenheitsform von must (Verpflichtung). must have seen wäre eine Vermutung („muss wohl getroffen haben“)."},{"parts":["I don't know who rang, but it ",{"opts":["could have been","must have been"],"decode":["könnte-gewesen-sein","muss-gewesen-sein"],"correct":0}," Jim."],"solutionEn":"I don't know who rang, but it could have been Jim.","solutionDe":"Ich weiß nicht, wer angerufen hat, aber es könnte Jim gewesen sein.","explain":"„I don't know“ = Unsicherheit → could have been. must have been wäre Sicherheit."},{"parts":["It's a pity you didn't ask because I ",{"opts":["can't help","could have helped"],"decode":["kann-nicht-helfen","hätte-helfen-können"],"correct":1}," you."],"solutionEn":"It's a pity you didn't ask because I could have helped you.","solutionDe":"Schade, dass du nicht gefragt hast – ich hätte dir helfen können.","explain":"could have + 3. Verbform = ungenutzte Möglichkeit in der Vergangenheit (hätte können, ist aber nicht passiert)."},{"parts":["It's your own fault, you ",{"opts":["can't have","shouldn't have"],"decode":["kannst-nicht-haben","hättest-nicht-sollen"],"correct":1}," gone to bed so late."],"solutionEn":"It's your own fault, you shouldn't have gone to bed so late.","solutionDe":"Selber schuld – du hättest nicht so spät schlafen gehen sollen.","explain":"shouldn't have + 3. Verbform = Kritik an einer vergangenen Handlung."}]}]},{"id":"music","title":"Music","icon":"🎵","phase":2,"birkenbihl":[{"id":"mus_t1","title":"Moved by Music – Lesetext (Unit 9)","sentences":[{"id":"mus_t1_s01","en":"What made the song 'Happy' by Pharrell Williams such a massive hit?","decode":[["What","was"],["made","machte"],["the","das"],["song","Lied"],["'Happy'","„Happy“"],["by","von"],["Pharrell Williams","Pharrell Williams"],["such a","zu solch einem"],["massive","riesigen"],["hit?","Hit?"]],"de":"Was machte das Lied „Happy“ von Pharrell Williams zu so einem Riesenhit?"},{"id":"mus_t1_s02","en":"Was it the catchy tune that made people want to dance?","decode":[["Was it","war es"],["the","die"],["catchy","eingängige"],["tune","Melodie"],["that","die"],["made","dazu-brachte"],["people","Leute"],["want","wollen"],["to dance?","zu tanzen?"]],"de":"War es die eingängige Melodie, die die Leute zum Tanzen brachte?"},{"id":"mus_t1_s03","en":"Was it the upbeat lyrics, which more or less commanded people to be happy?","decode":[["Was it","war es"],["the","der"],["upbeat","fröhlich-optimistische"],["lyrics,","Liedtext,"],["which","der"],["more or less","mehr oder weniger"],["commanded","befahl"],["people","den Leuten"],["to be","zu sein"],["happy?","glücklich?"]],"de":"War es der fröhliche Text, der den Leuten mehr oder weniger befahl, glücklich zu sein?"},{"id":"mus_t1_s04","en":"But creating 'Happy' was by no means as effortless as the song sounds.","decode":[["But","aber"],["creating","das Erschaffen von"],["'Happy'","„Happy“"],["was","war"],["by no means","keineswegs"],["as effortless as","so mühelos wie"],["the","das"],["song","Lied"],["sounds.","klingt."]],"de":"Aber „Happy“ zu erschaffen war keineswegs so mühelos, wie das Lied klingt."},{"id":"mus_t1_s05","en":"There were nine other versions of it before the one that we know and can sing along to now.","decode":[["There were","es gab"],["nine","neun"],["other","andere"],["versions","Versionen"],["of it","davon"],["before","vor"],["the one","derjenigen"],["that","die"],["we","wir"],["know","kennen"],["and","und"],["can","können"],["sing along to","mitsingen"],["now.","jetzt."]],"de":"Es gab neun andere Versionen davon vor der einen, die wir jetzt kennen und mitsingen können."},{"id":"mus_t1_s06","en":"He was recording a track to move his audience.","decode":[["He","er"],["was recording","nahm auf"],["a","einen"],["track","Song/Titel"],["to move","um zu bewegen"],["his","sein"],["audience.","Publikum."]],"de":"Er nahm einen Song auf, um sein Publikum zu bewegen."},{"id":"mus_t1_s07","en":"A recent study from Canada has shown that music can release a chemical in the brain which causes people to feel happy.","decode":[["A","eine"],["recent","aktuelle"],["study","Studie"],["from Canada","aus Kanada"],["has shown","hat gezeigt"],["that","dass"],["music","Musik"],["can","kann"],["release","freisetzen"],["a","eine"],["chemical","chemische-Substanz"],["in the brain","im Gehirn"],["which","die"],["causes","bewirkt"],["people","dass Menschen"],["to feel","sich fühlen"],["happy.","glücklich."]],"de":"Eine aktuelle Studie aus Kanada hat gezeigt, dass Musik im Gehirn eine chemische Substanz freisetzen kann, die Menschen glücklich macht."},{"id":"mus_t1_s08","en":"This chemical is called dopamine, and it is normally produced as the body's reward for doing something that is good for survival, such as eating.","decode":[["This","diese"],["chemical","Substanz"],["is called","heißt"],["dopamine,","Dopamin,"],["and","und"],["it","sie"],["is","wird"],["normally","normalerweise"],["produced","produziert"],["as","als"],["the body's","die körpereigene"],["reward","Belohnung"],["for doing","für das Tun von"],["something","etwas"],["that","das"],["is","ist"],["good","gut"],["for survival,","fürs Überleben,"],["such as","wie zum Beispiel"],["eating.","Essen."]],"de":"Diese Substanz heißt Dopamin und wird normalerweise als Belohnung des Körpers ausgeschüttet, wenn man etwas tut, das gut fürs Überleben ist – wie zum Beispiel essen."},{"id":"mus_t1_s09","en":"It's not clear why music is good for survival, but it certainly can stimulate dopamine release.","decode":[["It's","es ist"],["not","nicht"],["clear","klar"],["why","warum"],["music","Musik"],["is","ist"],["good","gut"],["for survival,","fürs Überleben,"],["but","aber"],["it","sie"],["certainly","sicherlich"],["can","kann"],["stimulate","anregen"],["dopamine","Dopamin-"],["release.","Ausschüttung."]],"de":"Es ist nicht klar, warum Musik gut fürs Überleben ist, aber sie kann sicherlich die Dopamin-Ausschüttung anregen."},{"id":"mus_t1_s10","en":"It must be a piece of music that you are into – the kind of music that sends a shiver down your spine.","decode":[["It","es"],["must","muss"],["be","sein"],["a piece of","ein Stück"],["music","Musik"],["that","auf das"],["you","du"],["are into","stehst"],["–","–"],["the kind of","die Art von"],["music","Musik"],["that","die"],["sends","jagt"],["a","einen"],["shiver","Schauer"],["down your spine.","über deinen Rücken."]],"de":"Es muss ein Musikstück sein, auf das du stehst – die Art von Musik, die dir einen Schauer über den Rücken jagt."},{"id":"mus_t1_s11","en":"However, there are very few songs that everybody likes.","decode":[["However,","jedoch"],["there are","gibt es"],["very","sehr"],["few","wenige"],["songs","Lieder"],["that","die"],["everybody","jeder"],["likes.","mag."]],"de":"Es gibt jedoch nur sehr wenige Lieder, die jeder mag."},{"id":"mus_t1_s12","en":"For example, there is some music that almost everybody hates, such as the screeching noise made by a neighbour who has just bought a drum kit or taken up the violin.","decode":[["For example,","zum Beispiel"],["there is","gibt es"],["some","manche"],["music","Musik"],["that","die"],["almost","fast"],["everybody","jeder"],["hates,","hasst,"],["such as","wie etwa"],["the","das"],["screeching","kreischende"],["noise","Geräusch"],["made by","gemacht von"],["a","einem"],["neighbour","Nachbarn"],["who","der"],["has just","gerade"],["bought","gekauft hat"],["a","ein"],["drum kit","Schlagzeug"],["or","oder"],["taken up","angefangen hat mit"],["the violin.","der Geige."]],"de":"Zum Beispiel gibt es Musik, die fast jeder hasst – etwa das kreischende Geräusch eines Nachbarn, der sich gerade ein Schlagzeug gekauft oder mit der Geige angefangen hat."},{"id":"mus_t1_s13","en":"At the other end of the spectrum, the nearest you will get to a piece of music which is universally popular is perhaps a song like 'Happy'.","decode":[["At the other end","am anderen Ende"],["of the spectrum,","des Spektrums"],["the nearest","das Nächste"],["you will get","das du herankommst"],["to","an"],["a piece of music","ein Musikstück"],["which","das"],["is","ist"],["universally","allgemein"],["popular","beliebt"],["is","ist"],["perhaps","vielleicht"],["a","ein"],["song","Lied"],["like","wie"],["'Happy'.","„Happy“."]],"de":"Am anderen Ende des Spektrums: Das, was einem allgemein beliebten Musikstück am nächsten kommt, ist vielleicht ein Lied wie „Happy“."},{"id":"mus_t1_s14","en":"Music is not only used to make people feel happy, though.","decode":[["Music","Musik"],["is","wird"],["not only","nicht nur"],["used","verwendet"],["to make","um zu machen"],["people","Menschen"],["feel happy,","glücklich,"],["though.","allerdings."]],"de":"Musik wird allerdings nicht nur verwendet, um Menschen glücklich zu machen."},{"id":"mus_t1_s15","en":"Supermarkets often play relaxing music when they want people to browse for longer, and research suggests that this can increase sales.","decode":[["Supermarkets","Supermärkte"],["often","oft"],["play","spielen"],["relaxing","entspannende"],["music","Musik"],["when","wenn"],["they","sie"],["want","wollen"],["people","dass Leute"],["to browse","stöbern"],["for longer,","länger,"],["and","und"],["research","die Forschung"],["suggests","legt nahe"],["that","dass"],["this","das"],["can","kann"],["increase","steigern"],["sales.","den Umsatz."]],"de":"Supermärkte spielen oft entspannende Musik, wenn sie wollen, dass die Leute länger stöbern – und die Forschung legt nahe, dass das den Umsatz steigern kann."},{"id":"mus_t1_s16","en":"Owners of clothes stores, on the other hand, try to fit in with the musical taste of their customers by choosing music that is fashionable.","decode":[["Owners","Besitzer"],["of clothes stores,","von Bekleidungsgeschäften"],["on the other hand,","andererseits"],["try","versuchen"],["to fit in with","sich anzupassen an"],["the","den"],["musical","musikalischen"],["taste","Geschmack"],["of their","ihrer"],["customers","Kunden"],["by choosing","indem sie wählen"],["music","Musik"],["that","die"],["is","ist"],["fashionable.","angesagt."]],"de":"Besitzer von Bekleidungsgeschäften versuchen dagegen, sich an den Musikgeschmack ihrer Kunden anzupassen, indem sie angesagte Musik wählen."},{"id":"mus_t1_s17","en":"National anthems have been used for centuries to stimulate feelings of patriotism.","decode":[["National anthems","Nationalhymnen"],["have been used","werden verwendet"],["for centuries","seit Jahrhunderten"],["to stimulate","um anzuregen"],["feelings","Gefühle"],["of patriotism.","von Patriotismus."]],"de":"Nationalhymnen werden seit Jahrhunderten verwendet, um patriotische Gefühle zu wecken."},{"id":"mus_t1_s18","en":"Classical music is often played outside shops, stations and other places where youths like to hang out.","decode":[["Classical","klassische"],["music","Musik"],["is","wird"],["often","oft"],["played","gespielt"],["outside","vor"],["shops,","Geschäften,"],["stations","Bahnhöfen"],["and","und"],["other","anderen"],["places","Orten"],["where","wo"],["youths","Jugendliche"],["like to","gerne"],["hang out.","abhängen."]],"de":"Klassische Musik wird oft vor Geschäften, Bahnhöfen und anderen Orten gespielt, wo Jugendliche gerne abhängen."},{"id":"mus_t1_s19","en":"Store managers have found that there is nothing better than a little Mozart or opera to get rid of young people.","decode":[["Store managers","Filialleiter"],["have found","haben festgestellt"],["that","dass"],["there is","es gibt"],["nothing","nichts"],["better","Besseres"],["than","als"],["a little","ein wenig"],["Mozart","Mozart"],["or","oder"],["opera","Oper"],["to get rid of","um loszuwerden"],["young people.","junge Leute."]],"de":"Filialleiter haben festgestellt, dass es nichts Besseres gibt als ein wenig Mozart oder Oper, um junge Leute loszuwerden."},{"id":"mus_t1_s20","en":"And who knows – perhaps in 100 years, Pharrell Williams' 'Happy' will be used for the same purpose!","decode":[["And","und"],["who knows","wer weiß"],["–","–"],["perhaps","vielleicht"],["in 100 years,","in 100 Jahren"],["Pharrell Williams'","Pharrell Williams'"],["'Happy'","„Happy“"],["will be used","wird verwendet werden"],["for the same","für denselben"],["purpose!","Zweck!"]],"de":"Und wer weiß – vielleicht wird Pharrell Williams' „Happy“ in 100 Jahren für denselben Zweck verwendet!"}]}],"exercises":[{"id":"mus_ex01","title":"Wörter aus dem Lesetext","source":"Unit 9, Reading Ex. 2","type":"mc","instruction":"Welches Wort aus dem Text „Moved by music“ passt zur Definition?","questions":[{"parts":["an excited or frightened feeling: ",{"opts":["a shiver","a screeching noise","a catchy tune","upbeat lyrics"],"decode":["ein Schauer","ein kreischendes Geräusch","eine eingängige Melodie","ein fröhlicher Liedtext"],"correct":0}],"solutionEn":"a shiver","solutionDe":"ein Schauer (vor Aufregung oder Angst)","explain":"Im Text: 'music that sends a shiver down your spine' = Musik, die dir einen Schauer über den Rücken jagt."},{"parts":["words of a song full of hope, happiness and good feelings: ",{"opts":["a shiver","a screeching noise","a catchy tune","upbeat lyrics"],"decode":["ein Schauer","ein kreischendes Geräusch","eine eingängige Melodie","ein fröhlicher Liedtext"],"correct":3}],"solutionEn":"upbeat lyrics","solutionDe":"fröhlicher, optimistischer Liedtext","explain":"upbeat = fröhlich, optimistisch; lyrics = Liedtext (immer Plural!)."},{"parts":["an unpleasant, loud, high sound: ",{"opts":["a shiver","a screeching noise","a catchy tune","upbeat lyrics"],"decode":["ein Schauer","ein kreischendes Geräusch","eine eingängige Melodie","ein fröhlicher Liedtext"],"correct":1}],"solutionEn":"a screeching noise","solutionDe":"ein kreischendes Geräusch","explain":"screeching = kreischend. Im Text: das Geräusch des Nachbarn, der gerade Schlagzeug oder Geige lernt."},{"parts":["a pleasing and easy to remember song or piece of music: ",{"opts":["a shiver","a screeching noise","a catchy tune","upbeat lyrics"],"decode":["ein Schauer","ein kreischendes Geräusch","eine eingängige Melodie","ein fröhlicher Liedtext"],"correct":2}],"solutionEn":"a catchy tune","solutionDe":"eine eingängige Melodie (ein Ohrwurm)","explain":"catchy = eingängig, bleibt im Ohr; tune = Melodie."}]},{"id":"mus_ex02","title":"Reading Comprehension","source":"Unit 9, Reading Ex. 5 + Ex. 8","type":"mc","instruction":"Wähle die richtige Antwort laut Text. Nur eine Antwort ist möglich.","questions":[{"parts":["The writer thinks the song 'Happy' … ",{"opts":["will be popular for a long time","is liked by most people","will definitely become unpopular in the future"],"decode":["wird lange Zeit beliebt sein","wird von den meisten Menschen gemocht","wird in Zukunft sicher unbeliebt werden"],"correct":1}],"solutionEn":"is liked by most people","solutionDe":"wird von den meisten Menschen gemocht","explain":"Textstelle: 'the nearest you will get to a piece of music which is universally popular is perhaps a song like Happy.' Über die Zukunft sagt der Autor nichts Sicheres ('who knows – perhaps …')."},{"parts":["Why did Pharrell Williams write so many versions of 'Happy'? ",{"opts":["People are moved in different ways by the same type of music.","He wanted to get just the right version to move people.","People enjoy different versions of the same song.","He wanted to research people's mood when they listened to music."],"decode":["Menschen werden von derselben Musik unterschiedlich bewegt.","Er wollte genau die richtige Version finden, um Menschen zu bewegen.","Menschen genießen verschiedene Versionen desselben Lieds.","Er wollte die Stimmung der Menschen beim Musikhören erforschen."],"correct":1}],"solutionEn":"He wanted to get just the right version to move people.","solutionDe":"Er wollte genau die richtige Version finden, um die Menschen zu bewegen.","explain":"Textstelle: 'He was recording a track to move his audience.' – Es gab neun Versionen, bevor die richtige gefunden war."},{"parts":["What is the main point of the whole text? ",{"opts":["Music releases a chemical in the brain.","Music stimulates people to follow famous people.","Music influences the way people feel and act.","Music inspires people to dance and march."],"decode":["Musik setzt eine chemische Substanz im Gehirn frei.","Musik bringt Menschen dazu, Berühmtheiten zu folgen.","Musik beeinflusst, wie Menschen fühlen und handeln.","Musik inspiriert Menschen zum Tanzen und Marschieren."],"correct":2}],"solutionEn":"Music influences the way people feel and act.","solutionDe":"Musik beeinflusst, wie Menschen fühlen und handeln.","explain":"Alle Absätze zeigen das: Stimmung (Dopamin), Einkaufsverhalten, Patriotismus, „move along“. Die anderen Antworten sind nur einzelne Details."}]},{"id":"mus_ex03","title":"True or False?","source":"Unit 9, Reading Ex. 7","type":"mc","instruction":"Richtig oder falsch laut Text? Die Lösung zeigt dir die genaue Textstelle.","questions":[{"parts":["'Happy' was an easy song to write. ",{"opts":["True","False"],"decode":["richtig","falsch"],"correct":1}],"solutionEn":"False – 'creating Happy was by no means as effortless as the song sounds.'","solutionDe":"Falsch – „Happy“ zu erschaffen war keineswegs so mühelos, wie das Lied klingt.","explain":"by no means = keineswegs; effortless = mühelos. Es gab neun Versionen vor der endgültigen!"},{"parts":["Relaxing music can encourage people to spend money. ",{"opts":["True","False"],"decode":["richtig","falsch"],"correct":0}],"solutionEn":"True – 'Supermarkets often play relaxing music … and research suggests that this can increase sales.'","solutionDe":"Richtig – Supermärkte spielen entspannende Musik, und das kann laut Forschung den Umsatz steigern.","explain":"browse for longer = länger stöbern → die Leute kaufen mehr."},{"parts":["In recent times, music has been used to make people feel patriotic. ",{"opts":["True","False"],"decode":["richtig","falsch"],"correct":1}],"solutionEn":"False – 'National anthems have been used for centuries to stimulate feelings of patriotism.'","solutionDe":"Falsch – Nationalhymnen werden schon seit Jahrhunderten dafür verwendet, nicht erst seit Kurzem.","explain":"for centuries = seit Jahrhunderten ≠ in recent times (in letzter Zeit). Genau lesen!"}]},{"id":"mus_ex04","title":"Phrasal Verbs","source":"Unit 9, Vocabulary Ex. 6 + Phrasal-verbs-Kasten","type":"gap","instruction":"Vervollständige die Sätze mit dem richtigen Phrasal Verb.","questions":[{"parts":["He only listens to rap to fit ",{"opts":["out in","in with","up with"],"decode":["draußen in","dazupassen zu (fit in with)","mithalten mit (keep up with)"],"correct":1}," his friends."],"solutionEn":"fit in with","solutionDe":"dazupassen zu / sich anpassen an","explain":"fit in with = zu etwas/jemandem passen, sich anpassen. Auch im Lesetext: Geschäfte 'fit in with the musical taste of their customers'."},{"parts":["I know a lot of kids who are ",{"opts":["into","up to","out of"],"decode":["begeistert von (be into)","bis zu","heraus aus"],"correct":0}," electronic music."],"solutionEn":"be into","solutionDe":"auf etwas stehen / von etwas begeistert sein","explain":"be into something = etwas sehr mögen. Im Lesetext: 'a piece of music that you are into'."},{"parts":["In the USA, teenagers like to hang ",{"opts":["up","out","on"],"decode":["auflegen (hang up)","abhängen (hang out)","warten (hang on)"],"correct":1}," in the big malls."],"solutionEn":"hang out","solutionDe":"Zeit verbringen / abhängen","explain":"hang out = viel Zeit an einem Ort oder mit jemandem verbringen. Im Lesetext: 'places where youths like to hang out'."},{"parts":["My mum wants me to take ",{"opts":["over","up","off"],"decode":["übernehmen (take over)","anfangen mit (take up)","ausziehen/abheben (take off)"],"correct":1}," the piano."],"solutionEn":"take up","solutionDe":"(ein Hobby/Instrument) anfangen","explain":"take up = mit einer Tätigkeit beginnen. Im Lesetext: 'a neighbour who has … taken up the violin'."}]},{"id":"mus_ex05","title":"In the Band – Music Vocabulary","source":"Unit 9, Review Ex. 1","type":"gap","instruction":"Vervollständige den Text mit den passenden Musik-Wörtern.","questions":[{"parts":["I'm the ",{"opts":["rock","lead","drum"],"decode":["Rock-","Lead-/Haupt-","Schlagzeug-"],"correct":1}," guitarist in a ",{"opts":["drum","rock","opera"],"decode":["Schlagzeug-","Rock-","Opern-"],"correct":1}," band. We play about one ",{"opts":["studio","microphone","concert"],"decode":["Studio","Mikrofon","Konzert"],"correct":2}," a month. Last summer, we performed on an outdoor ",{"opts":["stage","drum kit","studio"],"decode":["Bühne","Schlagzeug","Studio"],"correct":0}," at a music festival. We practise in a recording ",{"opts":["concert","studio","stage"],"decode":["Konzert","Studio","Bühne"],"correct":1}," once a week. It's great fun doing ",{"opts":["gigs","stages","drum kits"],"decode":["Gigs/Auftritte","Bühnen","Schlagzeuge"],"correct":0},", but it's hard work carrying all the heavy equipment. I feel sorry for our drummer – he has to carry the ",{"opts":["microphone","drum kit","stage"],"decode":["Mikrofon","Schlagzeug","Bühne"],"correct":1},". Our singer is very lucky – she only has to carry her ",{"opts":["microphone","stage","drum kit"],"decode":["Mikrofon","Bühne","Schlagzeug"],"correct":0},"!"],"solutionEn":"lead – rock – concert – stage – studio – gigs – drum kit – microphone","solutionDe":"Ich bin der Leadgitarrist in einer Rockband. Wir spielen etwa ein Konzert pro Monat. Letzten Sommer sind wir bei einem Musikfestival auf einer Freiluftbühne aufgetreten. Wir proben einmal pro Woche in einem Aufnahmestudio. Gigs zu spielen macht großen Spaß, aber das schwere Equipment zu tragen ist harte Arbeit. Unser Schlagzeuger tut mir leid – er muss das Schlagzeug tragen. Unsere Sängerin hat Glück – sie muss nur ihr Mikrofon tragen!","explain":"lead guitarist = Hauptgitarrist; gig = Live-Auftritt; recording studio = Aufnahmestudio; outdoor stage = Bühne im Freien; drum kit = Schlagzeug."}]},{"id":"mus_ex06","title":"Relative Pronouns: Festival Photos","source":"Unit 9, Grammar Ex. 1 (Defining relative clauses)","type":"gap","instruction":"Setze das richtige Relativpronomen ein: who, which, where, when oder whose.","questions":[{"parts":["Here are some photos from the rock festival which I went to last summer in Benicàssim. This is the bus ",{"opts":["which","who","where"],"decode":["der/die/das (Sachen)","der/die (Personen)","wo (Orte)"],"correct":0}," took us from the station to the festival site. Those are the girls ",{"opts":["whose","who","which"],"decode":["deren (Besitz)","die (Personen)","die (Sachen)"],"correct":1}," I went with – we're having lunch. That's the place ",{"opts":["when","where","which"],"decode":["als/wenn (Zeit)","wo (Orte)","der/die/das (Sachen)"],"correct":1}," we ate. It wasn't always so quiet – we tried to go ",{"opts":["where","when","who"],"decode":["wo (Orte)","als/wenn (Zeit)","der/die (Personen)"],"correct":1}," it was less busy! This is the place ",{"opts":["when","whose","where"],"decode":["als/wenn (Zeit)","deren (Besitz)","wo (Orte)"],"correct":2}," we slept. That's Laura inside – she's the girl ",{"opts":["who","whose","which"],"decode":["die (Person)","deren (Besitz)","die (Sache)"],"correct":1}," tent it was."],"solutionEn":"which – who – where – when – where – whose","solutionDe":"which (Bus = Sache) – who (Mädchen = Personen) – where (Ort) – when (Zeit) – where (Ort) – whose (das Mädchen, DEREN Zelt es war)","explain":"who/that = Personen, which/that = Sachen, where = Orte, when = Zeitangaben, whose = Besitz. 'the girl whose tent it was' = das Mädchen, dem das Zelt gehörte."}]},{"id":"mus_ex07","title":"Relative Clauses: defining & non-defining","source":"Unit 9, Grammar Ex. 5 + Ex. 12","type":"mc","instruction":"Wähle das richtige Relativpronomen. Achtung bei Sätzen mit Kommas (non-defining)!","questions":[{"parts":["'Happy' is a song ",{"opts":["who","which","whose"],"decode":["der/die (Personen)","das (Sachen)","dessen/deren"],"correct":1}," almost everybody likes."],"solutionEn":"which (oder: that)","solutionDe":"das – „Happy“ ist ein Lied, das fast jeder mag.","explain":"Sachen → which/that. Da das Pronomen hier Objekt ist, könnte man es sogar ganz weglassen: 'Happy is a song almost everybody likes.'"},{"parts":["I've got a neighbour ",{"opts":["who","which","whose"],"decode":["der/die (Personen)","das (Sachen)","dessen/deren"],"correct":0}," has just taken up the violin."],"solutionEn":"who (oder: that)","solutionDe":"der – Ich habe einen Nachbarn, der gerade mit der Geige angefangen hat.","explain":"Personen → who/that. Hier ist das Pronomen Subjekt des Relativsatzes und darf NICHT weggelassen werden."},{"parts":["Mozart, ",{"opts":["that","who","whose"],"decode":["der (nur defining!)","der (Personen)","dessen"],"correct":1}," was born in Austria, was a great composer."],"solutionEn":"who","solutionDe":"der – Mozart, der in Österreich geboren wurde, war ein großartiger Komponist.","explain":"Non-defining relative clause (Zusatzinfo zwischen Kommas): Hier ist 'that' NICHT erlaubt – nur who (Personen) oder which (Sachen)."},{"parts":["Bob Marley, ",{"opts":["who's","whose","which"],"decode":["who is (Kurzform!)","dessen (Besitz)","der/das (Sachen)"],"correct":1}," home was in Jamaica, was the most famous reggae singer."],"solutionEn":"whose","solutionDe":"dessen – Bob Marley, dessen Zuhause in Jamaika war, war der berühmteste Reggae-Sänger.","explain":"whose = dessen/deren (Besitz). Nicht verwechseln: who's = who is!"}]},{"id":"mus_ex08","title":"American English vs. British English","source":"Unit 9, Vocabulary (AE/BE) + Review Ex. 2","type":"mc","instruction":"Wie heißt das Wort im britischen Englisch?","questions":[{"parts":["American English: 'fall' → British English: ",{"opts":["spring","autumn","sunset"],"decode":["Frühling","Herbst","Sonnenuntergang"],"correct":1}],"solutionEn":"autumn","solutionDe":"Herbst","explain":"AE fall = BE autumn. Weitere Paare aus der Unit: movies–cinema, parking lot–car park, gas–petrol."},{"parts":["American English: 'sneakers' → British English: ",{"opts":["trainers","slippers","wellies"],"decode":["Turnschuhe","Hausschuhe","Gummistiefel"],"correct":0}],"solutionEn":"trainers","solutionDe":"Turnschuhe","explain":"AE sneakers = BE trainers. Auch wichtig: AE pants = BE trousers (Hose), AE sidewalk = BE pavement (Gehsteig)."},{"parts":["American English: 'cookie' → British English: ",{"opts":["muffin","toast","biscuit"],"decode":["Muffin","Toast","Keks"],"correct":2}],"solutionEn":"biscuit","solutionDe":"Keks","explain":"AE cookie = BE biscuit. Auch: AE candy store = BE sweet shop, AE subway = BE underground."},{"parts":["Which spelling is British English? ",{"opts":["color","colour"],"decode":["Farbe (amerikanische Schreibung)","Farbe (britische Schreibung)"],"correct":1}],"solutionEn":"colour","solutionDe":"Farbe – britische Schreibweise mit -our","explain":"BE: colour, humour, centre, theatre, tyre, traveller – AE: color, humor, center, theater, tire, traveler."}]},{"id":"mus_ex09","title":"Album Review: Divide by Ed Sheeran","source":"Folien „Writing Short Review“ (How to give a Presentation, Folie 32–33)","type":"gap","instruction":"Vervollständige die Album-Rezension. Diese Bausteine kannst du für jede eigene Review verwenden!","questions":[{"parts":["",{"opts":["A song which I hate","One album that I really like","One concert I visited"],"decode":["ein Lied, das ich hasse","ein Album, das ich wirklich mag","ein Konzert, das ich besucht habe"],"correct":1}," is 'Divide' by Ed Sheeran. It was ",{"opts":["published","performed","released"],"decode":["veröffentlicht (Bücher)","aufgeführt","veröffentlicht (Musik/Alben)"],"correct":2}," in 2017. The album mainly belongs to the ",{"opts":["folk","pop","classical"],"decode":["Folk-","Pop-","Klassik-"],"correct":1}," genre, but it also includes some folk and acoustic elements. Ed Sheeran ",{"opts":["is known","knows","is knowing"],"decode":["ist bekannt","weiß/kennt","(falsche Verbform)"],"correct":0}," for his expressive lyrics, catchy melodies, and clear vocals. Many of the songs are based on guitar music and have a strong beat and rhythm. My favourite ",{"opts":["listener on the album","track on the album","genre on the album"],"decode":["Hörer auf dem Album","Titel/Song auf dem Album","Genre auf dem Album"],"correct":1}," is 'Perfect'. It is a romantic ballad with gentle instrumentals and emotional lyrics. Many ",{"opts":["singers","listeners","melodies"],"decode":["Sänger","Hörer","Melodien"],"correct":1}," enjoy this song because it is calm, melodic, and pleasant to listen to. I ",{"opts":["like this album","belong to this album","sound this album"],"decode":["mag dieses Album","gehöre zu diesem Album","(ergibt keinen Sinn)"],"correct":0}," because it offers a variety of musical styles and tempos. Some tracks are lively and rhythmic, like 'Shape of You', while ",{"opts":["other","others","each other"],"decode":["andere (vor einem Nomen)","andere (allein stehend)","einander"],"correct":1}," are slower and more emotional. The album has strong songwriting and an enjoyable sound. I would definitely ",{"opts":["release","record","recommend"],"decode":["veröffentlichen","aufnehmen","empfehlen"],"correct":2}," it to people who like modern pop music."],"solutionEn":"One album that I really like – released – pop – is known – track on the album – listeners – like this album – others – recommend","solutionDe":"Bausteine: Ein Album, das ich wirklich mag, ist … / Es wurde … veröffentlicht / gehört zum …-Genre / ist bekannt für … / Mein Lieblingstitel auf dem Album / viele Hörer / Ich mag dieses Album, weil … / andere (Songs) / Ich würde es … empfehlen.","explain":"Diese Review-Bausteine für die Schularbeit merken: 'One album that I really like is …', 'It was released in …', 'belongs to the … genre', 'is known for …', 'My favourite track', 'I would recommend it to people who …'. – 'others' steht allein (Pronomen), 'other' nur vor einem Nomen."}]}]},{"id":"prepositions","title":"Prepositions","icon":"📍","phase":2,"birkenbihl":[{"id":"prep_t1","title":"Verb + Preposition – die wichtigsten Kollokationen","sentences":[{"id":"prep_t1_s01","en":"It's so noisy – I can't concentrate on my homework.","decode":[["It's","es-ist"],["so","so"],["noisy –","laut –"],["I","ich"],["can't","kann-nicht"],["concentrate","konzentrieren"],["on","auf"],["my","meine"],["homework.","Hausübung."]],"de":"Es ist so laut – ich kann mich nicht auf meine Hausübung konzentrieren. (concentrate ON)"},{"id":"prep_t1_s02","en":"Don't worry – I'll pay for the tickets.","decode":[["Don't worry –","keine-Sorge –"],["I'll","ich-werde"],["pay","zahlen"],["for","für"],["the","die"],["tickets.","Karten."]],"de":"Keine Sorge – ich zahle für die Karten. (pay FOR)"},{"id":"prep_t1_s03","en":"The car belongs to my father.","decode":[["The","das"],["car","Auto"],["belongs","gehört"],["to","zu"],["my","meinem"],["father.","Vater."]],"de":"Das Auto gehört meinem Vater. (belong TO)"},{"id":"prep_t1_s04","en":"I borrowed a pen from my classmate.","decode":[["I","ich"],["borrowed","borgte"],["a","einen"],["pen","Stift"],["from","von"],["my","meinem"],["classmate.","Mitschüler."]],"de":"Ich habe mir von meinem Mitschüler einen Stift ausgeborgt. (borrow FROM)"},{"id":"prep_t1_s05","en":"I've been waiting for the bus for more than twenty minutes!","decode":[["I've been waiting","ich-warte-schon"],["for","auf"],["the","den"],["bus","Bus"],["for","seit"],["more than","mehr-als"],["twenty","zwanzig"],["minutes!","Minuten!"]],"de":"Ich warte schon seit mehr als zwanzig Minuten auf den Bus! (wait FOR – nicht „wait on“!)"},{"id":"prep_t1_s06","en":"It depends on John – we'll eat when he gets home.","decode":[["It","es"],["depends","hängt-ab"],["on","von"],["John –","John –"],["we'll","wir-werden"],["eat","essen"],["when","wenn"],["he","er"],["gets","kommt"],["home.","nach-Hause."]],"de":"Es hängt von John ab – wir essen, wenn er nach Hause kommt. (depend ON – nicht „depend from“!)"},{"id":"prep_t1_s07","en":"When we arrived at the cinema, the film had already started.","decode":[["When","als"],["we","wir"],["arrived","ankamen"],["at","bei"],["the","dem"],["cinema,","Kino,"],["the","der"],["film","Film"],["had","hatte"],["already","schon"],["started.","begonnen."]],"de":"Als wir beim Kino ankamen, hatte der Film schon begonnen. (arrive AT + Gebäude/Ort)"},{"id":"prep_t1_s08","en":"Please explain this problem to us.","decode":[["Please","bitte"],["explain","erkläre"],["this","dieses"],["problem","Problem"],["to us.","uns."]],"de":"Bitte erkläre uns dieses Problem. (explain something TO somebody)"},{"id":"prep_t1_s09","en":"She was listening to the radio when the doorbell rang.","decode":[["She","sie"],["was listening","hörte-gerade"],["to","zu"],["the","dem"],["radio","Radio"],["when","als"],["the","die"],["doorbell","Türklingel"],["rang.","läutete."]],"de":"Sie hörte gerade Radio, als es an der Tür läutete. (listen TO)"},{"id":"prep_t1_s10","en":"John worries about his exam results all the time.","decode":[["John","John"],["worries","macht-sich-Sorgen"],["about","um"],["his","seine"],["exam results","Prüfungsergebnisse"],["all the time.","die-ganze-Zeit."]],"de":"John macht sich ständig Sorgen um seine Prüfungsergebnisse. (worry ABOUT)"}]},{"id":"prep_t2","title":"at, in, on – Ort und Zeit","sentences":[{"id":"prep_t2_s01","en":"When will we arrive in Beijing?","decode":[["When","wann"],["will","werden"],["we","wir"],["arrive","ankommen"],["in","in"],["Beijing?","Peking?"]],"de":"Wann kommen wir in Peking an? (arrive IN + Stadt/Land, arrive AT + Gebäude/Ort)"},{"id":"prep_t2_s02","en":"They arrived in Bombay at 8:00 p.m. on July 30.","decode":[["They","sie"],["arrived","kamen-an"],["in","in"],["Bombay","Bombay"],["at","um"],["8:00 p.m.","20:00-Uhr"],["on","am"],["July 30.","30.-Juli."]],"de":"Sie kamen am 30. Juli um 20:00 Uhr in Bombay an. (in + Stadt, at + Uhrzeit, on + Datum)"}]}],"exercises":[{"id":"prep_ex01","title":"Verb + Preposition I (concentrate on, pay for …)","source":"Key_Practice – Verb-Prepositions 1–10","type":"gap","instruction":"Wähle die richtige Präposition.","questions":[{"parts":["It's so noisy – I can't concentrate ",{"opts":["at","on","in"],"decode":["bei","auf","in"],"correct":1}," my homework."],"solutionEn":"It's so noisy – I can't concentrate on my homework.","solutionDe":"Es ist so laut – ich kann mich nicht auf meine Hausübung konzentrieren.","explain":"concentrate ON = sich konzentrieren auf. Niemals „concentrate at/in“."},{"parts":["Don't worry – I'll pay ",{"opts":["to","about","for"],"decode":["zu","über","für"],"correct":2}," the tickets."],"solutionEn":"Don't worry – I'll pay for the tickets.","solutionDe":"Keine Sorge – ich zahle für die Karten.","explain":"pay FOR something = für etwas (be)zahlen."},{"parts":["The car belongs ",{"opts":["of","to","with"],"decode":["von","zu","mit"],"correct":1}," my father, so I don't think we can use it."],"solutionEn":"The car belongs to my father, so I don't think we can use it.","solutionDe":"Das Auto gehört meinem Vater, also können wir es wohl nicht benutzen.","explain":"belong TO somebody = jemandem gehören."},{"parts":["I borrowed a pen ",{"opts":["to","of","from"],"decode":["zu","von","von"],"correct":2}," my classmate."],"solutionEn":"I borrowed a pen from my classmate.","solutionDe":"Ich habe mir von meinem Mitschüler einen Stift ausgeborgt.","explain":"borrow FROM somebody = sich von jemandem ausborgen. (lend to = jemandem borgen)"},{"parts":["I've been waiting ",{"opts":["on","for","to"],"decode":["auf","auf","zu"],"correct":1}," the bus for more than twenty minutes!"],"solutionEn":"I've been waiting for the bus for more than twenty minutes!","solutionDe":"Ich warte schon seit mehr als zwanzig Minuten auf den Bus!","explain":"wait FOR = warten auf. Das deutsche „auf“ verleitet zu „wait on“ – falsch!"},{"parts":["What time shall we eat dinner? – It depends ",{"opts":["on","of","from"],"decode":["von","von","von"],"correct":0}," John: we'll eat when he gets home."],"solutionEn":"It depends on John – we'll eat when he gets home.","solutionDe":"Es hängt von John ab – wir essen, wenn er nach Hause kommt.","explain":"depend ON = abhängen von. Das deutsche „von“ verleitet zu „depend from/of“ – beides falsch!"},{"parts":["When we arrived ",{"opts":["in","at","to"],"decode":["in","bei","zu"],"correct":1}," the cinema, the film had already started."],"solutionEn":"When we arrived at the cinema, the film had already started.","solutionDe":"Als wir beim Kino ankamen, hatte der Film schon begonnen.","explain":"arrive AT + Gebäude/Ort (cinema, station, airport); arrive IN + Stadt/Land. Niemals „arrive to“!"},{"parts":["Please explain this problem ",{"opts":["for","to","at"],"decode":["für","zu","bei"],"correct":1}," us."],"solutionEn":"Please explain this problem to us.","solutionDe":"Bitte erkläre uns dieses Problem.","explain":"explain something TO somebody = jemandem etwas erklären."},{"parts":["She was listening ",{"opts":["at","to","on"],"decode":["bei","zu","auf"],"correct":1}," the radio when the doorbell rang."],"solutionEn":"She was listening to the radio when the doorbell rang.","solutionDe":"Sie hörte gerade Radio, als es an der Tür läutete.","explain":"listen TO = zuhören / anhören. Im Deutschen ohne Präposition („Radio hören“) – im Englischen immer mit to!"},{"parts":["John worries ",{"opts":["of","on","about"],"decode":["von","auf","um"],"correct":2}," his exam results all the time."],"solutionEn":"John worries about his exam results all the time.","solutionDe":"John macht sich ständig Sorgen um seine Prüfungsergebnisse.","explain":"worry ABOUT = sich Sorgen machen um/über."}]},{"id":"prep_ex02","title":"Verb + Preposition II (listen to, depend on …)","source":"Key_Practice – Verb-Prepositions 11–20","type":"gap","instruction":"Wähle die richtige Präposition.","questions":[{"parts":["My flatmate listens ",{"opts":["at","for","to"],"decode":["bei","für","zu"],"correct":2}," a lot of jazz."],"solutionEn":"My flatmate listens to a lot of jazz.","solutionDe":"Mein Mitbewohner hört viel Jazz.","explain":"listen TO music/jazz/the radio."},{"parts":["David paid ",{"opts":["for","to","about"],"decode":["für","zu","über"],"correct":0}," the drinks."],"solutionEn":"David paid for the drinks.","solutionDe":"David hat die Getränke bezahlt.","explain":"pay FOR something."},{"parts":["Who does that house belong ",{"opts":["to","of","for"],"decode":["zu","von","für"],"correct":0},"?"],"solutionEn":"Who does that house belong to?","solutionDe":"Wem gehört dieses Haus?","explain":"belong TO – die Präposition bleibt auch in der Frage am Satzende stehen."},{"parts":["Don't worry ",{"opts":["for","about","of"],"decode":["für","um","von"],"correct":1}," Gemma, she'll be fine."],"solutionEn":"Don't worry about Gemma, she'll be fine.","solutionDe":"Mach dir keine Sorgen um Gemma, ihr wird nichts passieren.","explain":"worry ABOUT somebody/something."},{"parts":["She borrowed a jumper ",{"opts":["of","to","from"],"decode":["von","zu","von"],"correct":2}," Julie."],"solutionEn":"She borrowed a jumper from Julie.","solutionDe":"Sie hat sich von Julie einen Pullover ausgeborgt.","explain":"borrow FROM somebody."},{"parts":["Please be quiet – I need to concentrate ",{"opts":["on","in","at"],"decode":["auf","in","bei"],"correct":0}," this book."],"solutionEn":"Please be quiet – I need to concentrate on this book.","solutionDe":"Bitte sei leise – ich muss mich auf dieses Buch konzentrieren.","explain":"concentrate ON something."},{"parts":["I want to go to the beach tomorrow but it depends ",{"opts":["from","of","on"],"decode":["von","von","von"],"correct":2}," the weather."],"solutionEn":"I want to go to the beach tomorrow but it depends on the weather.","solutionDe":"Ich will morgen an den Strand, aber es hängt vom Wetter ab.","explain":"depend ON – Klassiker: Im Deutschen „von“, im Englischen ON!"},{"parts":["Who are you waiting ",{"opts":["on","for","to"],"decode":["auf","auf","zu"],"correct":1},"?"],"solutionEn":"Who are you waiting for?","solutionDe":"Auf wen wartest du?","explain":"wait FOR somebody – auch in Fragen bleibt for am Ende stehen."},{"parts":["When will we arrive ",{"opts":["at","to","in"],"decode":["bei","zu","in"],"correct":2}," Beijing?"],"solutionEn":"When will we arrive in Beijing?","solutionDe":"Wann kommen wir in Peking an?","explain":"arrive IN + Stadt/Land (Beijing); arrive AT + Gebäude/Ort (cinema, airport)."},{"parts":["The policeman explained ",{"opts":["to","at","for"],"decode":["zu","bei","für"],"correct":0}," the children why they should never run across a road."],"solutionEn":"The policeman explained to the children why they should never run across a road.","solutionDe":"Der Polizist erklärte den Kindern, warum sie nie über eine Straße laufen sollten.","explain":"explain TO somebody – das to steht direkt vor der Person."}]},{"id":"prep_ex03","title":"Basic Prepositions (Schulübung komplett)","source":"Key_Practice – Basic Prepositions 1–20","type":"gap","instruction":"Wähle die richtige Präposition.","questions":[{"parts":["They arrived ",{"opts":["at","in","on"],"decode":["bei","in","auf"],"correct":1}," Bombay ",{"opts":["at","on","in"],"decode":["um","am","im"],"correct":0}," 8:00 p.m. ",{"opts":["in","at","on"],"decode":["im","um","am"],"correct":2}," July 30."],"solutionEn":"They arrived in Bombay at 8:00 p.m. on July 30.","solutionDe":"Sie kamen am 30. Juli um 20:00 Uhr in Bombay an.","explain":"arrive in + Stadt; at + Uhrzeit; on + Datum/Tag."},{"parts":["Charles lives ",{"opts":["in","on","at"],"decode":["in","auf","bei"],"correct":1}," College Avenue ",{"opts":["on","in","at"],"decode":["auf","in","bei"],"correct":1}," an apartment. Phoenix is located ",{"opts":["at","on","in"],"decode":["bei","auf","in"],"correct":2}," the state of Arizona."],"solutionEn":"Charles lives on College Avenue in an apartment. Phoenix is located in the state of Arizona.","solutionDe":"Charles wohnt in einer Wohnung in der College Avenue. Phoenix liegt im Bundesstaat Arizona.","explain":"on + Straße; in + Wohnung/Gebiet/Bundesstaat."},{"parts":["John asked me to go ",{"opts":["with","to","by"],"decode":["mit","zu","bei"],"correct":0}," him to buy a pair of shoes. Put a pad ",{"opts":["under","below","on"],"decode":["unter","unterhalb","auf"],"correct":0}," the hot dish to protect the table."],"solutionEn":"John asked me to go with him to buy a pair of shoes. Put a pad under the hot dish to protect the table.","solutionDe":"John bat mich, mit ihm Schuhe kaufen zu gehen. Leg eine Unterlage unter die heiße Schüssel, um den Tisch zu schützen.","explain":"go with somebody = mitgehen; under = direkt unter etwas."},{"parts":["Mr. Walker has ",{"opts":["on","in","at"],"decode":["an","in","bei"],"correct":0}," a grey suit today. This story was written ",{"opts":["from","by","of"],"decode":["von","von","von"],"correct":1}," Conan Doyle."],"solutionEn":"Mr. Walker has on a grey suit today. This story was written by Conan Doyle.","solutionDe":"Mr. Walker trägt heute einen grauen Anzug (have on = anhaben). Diese Geschichte wurde von Conan Doyle geschrieben.","explain":"have on = anhaben/tragen; im Passiv steht der Urheber mit BY (nicht from!)."},{"parts":["My aunt stayed ",{"opts":["at","in","by"],"decode":["bei","in","neben"],"correct":0}," our house ",{"opts":["since","for","during"],"decode":["seit","für/lang","während"],"correct":1}," two weeks. Mary is a good housekeeper; she always sweeps ",{"opts":["under","over","behind"],"decode":["unter","über","hinter"],"correct":0}," the bed."],"solutionEn":"My aunt stayed at our house for two weeks. Mary is a good housekeeper; she always sweeps under the bed.","solutionDe":"Meine Tante blieb zwei Wochen bei uns zu Hause. Mary ist eine gute Hausfrau; sie kehrt immer unter dem Bett.","explain":"at our house = bei uns; for + Zeitdauer (zwei Wochen lang), since + Zeitpunkt!"},{"parts":["They had to drive ",{"opts":["around","across","along"],"decode":["um-…-herum","quer-über","entlang"],"correct":0}," the block four times before they found a parking place. There is an ink spot ",{"opts":["in","at","on"],"decode":["in","bei","auf"],"correct":2}," the collar ",{"opts":["of","from","off"],"decode":["von","von","weg-von"],"correct":0}," your shirt."],"solutionEn":"They had to drive around the block four times before they found a parking place. There is an ink spot on the collar of your shirt.","solutionDe":"Sie mussten viermal um den Block fahren, bevor sie einen Parkplatz fanden. Auf dem Kragen deines Hemdes ist ein Tintenfleck.","explain":"drive around the block = um den Block fahren; on + Oberfläche (Kragen); of = Genitiv (des Hemdes)."},{"parts":["Please write ",{"opts":["with","in","by"],"decode":["mit","in/mit","durch"],"correct":1}," ink, and don't forget to write ",{"opts":["on","in","at"],"decode":["auf","in","bei"],"correct":0}," every other line."],"solutionEn":"Please write in ink, and don't forget to write on every other line.","solutionDe":"Bitte schreib mit Tinte und vergiss nicht, nur jede zweite Zeile zu beschreiben.","explain":"write in ink = feste Wendung (mit Tinte schreiben); on a line = auf einer Zeile."},{"parts":["Did you receive a letter ",{"opts":["of","from","by"],"decode":["von","von","durch"],"correct":1}," your brother yesterday? The bus will not leave ",{"opts":["for","in","until"],"decode":["für/lang","in","bis"],"correct":0}," fifteen minutes."],"solutionEn":"Did you receive a letter from your brother yesterday? The bus will not leave for fifteen minutes.","solutionDe":"Hast du gestern einen Brief von deinem Bruder bekommen? Der Bus fährt erst in fünfzehn Minuten ab.","explain":"receive from = bekommen von; not … for fifteen minutes = die nächsten 15 Minuten (noch) nicht."},{"parts":["Elections are held ",{"opts":["at","in","on"],"decode":["um","im","am"],"correct":2}," the first Tuesday ",{"opts":["on","in","at"],"decode":["am","im","um"],"correct":1}," November. Maximo always entertains us ",{"opts":["with","by","of"],"decode":["mit","durch","von"],"correct":0}," stories of his experiences."],"solutionEn":"Elections are held on the first Tuesday in November. Maximo always entertains us with stories of his experiences.","solutionDe":"Wahlen finden am ersten Dienstag im November statt. Maximo unterhält uns immer mit Geschichten über seine Erlebnisse.","explain":"on + Tag (Tuesday); in + Monat (November); entertain with = unterhalten mit."},{"parts":["Does this bus go ",{"opts":["to","at","until"],"decode":["nach","bei","bis"],"correct":0}," Central City? Mr. and Mrs. Simpson have lived ",{"opts":["in","at","on"],"decode":["in","bei","auf/in"],"correct":2}," Chesnut Street ",{"opts":["since","for","from"],"decode":["seit","seit/lang","von"],"correct":1}," six years."],"solutionEn":"Does this bus go to Central City? Mr. and Mrs. Simpson have lived on Chesnut Street for six years.","solutionDe":"Fährt dieser Bus nach Central City? Die Simpsons wohnen seit sechs Jahren in der Chesnut Street.","explain":"go to + Ziel; on + Straße; for + Zeitdauer (six years), since + Zeitpunkt (z. B. since 2020)."},{"parts":["Dr. Parks has been living ",{"opts":["at","on","in"],"decode":["bei","auf","in"],"correct":2}," Mobile ",{"opts":["for","since","from"],"decode":["seit/lang","seit","von"],"correct":1}," October. He dived ",{"opts":["into","to","in"],"decode":["hinein-in","zu","in"],"correct":0}," the lake and swam ",{"opts":["at","into","to"],"decode":["bei","hinein-in","zu"],"correct":2}," the boat."],"solutionEn":"Dr. Parks has been living in Mobile since October. He dived into the lake and swam to the boat.","solutionDe":"Dr. Parks lebt seit Oktober in Mobile. Er tauchte in den See und schwamm zum Boot.","explain":"in + Stadt; since + Zeitpunkt (October); into = Bewegung hinein; to = Bewegung zu einem Ziel."}]},{"id":"prep_ex04","title":"Prepositions II – Verben","source":"Prepositions II – Verbs and Prepositions 1–12 (mit Key_Practice abgeglichen)","type":"gap","instruction":"Wähle die richtige Präposition nach dem Verb.","questions":[{"parts":["Stop worrying ",{"opts":["about","for","on"],"decode":["um/über","für","auf"],"correct":0}," your exam – everything will be fine. I've waited ",{"opts":["on","for","at"],"decode":["auf","auf","bei"],"correct":1}," Judy for 30 minutes. I'm going home."],"solutionEn":"Stop worrying about your exam – everything will be fine. I've waited for Judy for 30 minutes.","solutionDe":"Hör auf, dir wegen der Prüfung Sorgen zu machen – alles wird gut. Ich habe 30 Minuten auf Judy gewartet. Ich gehe heim.","explain":"worry ABOUT; wait FOR."},{"parts":["Stop talking and concentrate ",{"opts":["at","in","on"],"decode":["bei","in","auf"],"correct":2}," your work. Don't forget to pay ",{"opts":["for","to","of"],"decode":["für","zu","von"],"correct":0}," the newspaper."],"solutionEn":"Stop talking and concentrate on your work. Don't forget to pay for the newspaper.","solutionDe":"Hör auf zu reden und konzentriere dich auf deine Arbeit. Vergiss nicht, die Zeitung zu bezahlen.","explain":"concentrate ON; pay FOR."},{"parts":["He explained the computer program ",{"opts":["to","for","with"],"decode":["zu","für","mit"],"correct":0}," me. I don't know what we'll do at the weekend. It depends ",{"opts":["from","on","of"],"decode":["von","von","von"],"correct":1}," the weather."],"solutionEn":"He explained the computer program to me. It depends on the weather.","solutionDe":"Er hat mir das Computerprogramm erklärt. Es hängt vom Wetter ab.","explain":"explain TO somebody; depend ON something."},{"parts":["She will arrive ",{"opts":["at","to","in"],"decode":["bei","zu","in"],"correct":2}," Beijing at 3pm. I like to listen ",{"opts":["to","at","on"],"decode":["zu","bei","auf"],"correct":0}," the radio when I wake up."],"solutionEn":"She will arrive in Beijing at 3pm. I like to listen to the radio when I wake up.","solutionDe":"Sie kommt um 15 Uhr in Peking an. Ich höre gern Radio, wenn ich aufwache.","explain":"arrive IN + Stadt; listen TO."},{"parts":["He borrowed £20 ",{"opts":["from","of","by"],"decode":["von","von","durch"],"correct":0}," his brother. Who does this coat belong ",{"opts":["with","to","of"],"decode":["mit","zu","von"],"correct":1},"?"],"solutionEn":"He borrowed £20 from his brother. Who does this coat belong to?","solutionDe":"Er hat sich 20 Pfund von seinem Bruder ausgeborgt. Wem gehört dieser Mantel?","explain":"borrow FROM; belong TO."},{"parts":["She left without paying ",{"opts":["for","about","to"],"decode":["für","über","zu"],"correct":0}," the meal. It was so hot, I couldn't concentrate ",{"opts":["on","at","for"],"decode":["auf","bei","für"],"correct":0}," my book."],"solutionEn":"She left without paying for the meal. It was so hot, I couldn't concentrate on my book.","solutionDe":"Sie ging, ohne das Essen zu bezahlen. Es war so heiß, dass ich mich nicht auf mein Buch konzentrieren konnte.","explain":"pay FOR; concentrate ON."}]},{"id":"prep_ex05","title":"Prepositions II – Adjektive (famous for, proud of …)","source":"Prepositions II – Prepositions after adjectives 1–12","type":"gap","instruction":"Wähle die richtige Präposition nach dem Adjektiv.","questions":[{"parts":["England is famous ",{"opts":["of","for","about"],"decode":["von","für","über"],"correct":1}," its rainy weather. I'm very proud ",{"opts":["on","about","of"],"decode":["auf","über","auf/von"],"correct":2}," my daughter, she worked very hard."],"solutionEn":"England is famous for its rainy weather. I'm very proud of my daughter, she worked very hard.","solutionDe":"England ist für sein Regenwetter berühmt. Ich bin sehr stolz auf meine Tochter, sie hat hart gearbeitet.","explain":"famous FOR = berühmt für; proud OF = stolz auf (nicht „proud on“ – typischer Deutsch-Fehler!)."},{"parts":["He isn't really interested ",{"opts":["in","on","for"],"decode":["in/an","auf","für"],"correct":0}," getting married. Luke is very pleased ",{"opts":["about","with","of"],"decode":["über","mit","von"],"correct":1}," his exam results."],"solutionEn":"He isn't really interested in getting married. Luke is very pleased with his exam results.","solutionDe":"Er ist nicht wirklich daran interessiert zu heiraten. Luke ist mit seinen Prüfungsergebnissen sehr zufrieden.","explain":"interested IN; pleased WITH = zufrieden mit."},{"parts":["Unfortunately, I'm very bad ",{"opts":["in","at","with"],"decode":["in","bei/in","mit"],"correct":1}," music. I've been married ",{"opts":["with","to","at"],"decode":["mit","zu/mit","bei"],"correct":1}," my husband for 10 years."],"solutionEn":"Unfortunately, I'm very bad at music. I've been married to my husband for 10 years.","solutionDe":"Leider bin ich sehr schlecht in Musik. Ich bin seit 10 Jahren mit meinem Mann verheiratet.","explain":"good/bad AT = gut/schlecht in (nicht „in“!); married TO = verheiratet mit (nicht „with“!)."},{"parts":["She's very excited ",{"opts":["about","for","of"],"decode":["über/auf","für","von"],"correct":0}," the party. Julie is very different ",{"opts":["to","than","from"],"decode":["zu","als","von"],"correct":2}," her sister."],"solutionEn":"She's very excited about the party. Julie is very different from her sister.","solutionDe":"Sie freut sich sehr auf die Party. Julie ist ganz anders als ihre Schwester.","explain":"excited ABOUT = aufgeregt/freut sich auf; different FROM = anders als."},{"parts":["My niece is afraid ",{"opts":["from","of","about"],"decode":["vor","vor/von","über"],"correct":1}," dogs. A ball gown is similar ",{"opts":["with","as","to"],"decode":["mit","wie","zu"],"correct":2}," an evening dress."],"solutionEn":"My niece is afraid of dogs. A ball gown is similar to an evening dress.","solutionDe":"Meine Nichte hat Angst vor Hunden. Ein Ballkleid ist einem Abendkleid ähnlich.","explain":"afraid OF = Angst vor (das deutsche „vor“ verleitet zu from!); similar TO = ähnlich wie."},{"parts":["What is your town famous ",{"opts":["for","of","with"],"decode":["für","von","mit"],"correct":0},"? English cheese is very different ",{"opts":["from","of","to"],"decode":["von","von","zu"],"correct":0}," French cheese."],"solutionEn":"What is your town famous for? English cheese is very different from French cheese.","solutionDe":"Wofür ist deine Stadt berühmt? Englischer Käse ist ganz anders als französischer Käse.","explain":"famous FOR (auch in Fragen am Ende); different FROM."}]},{"id":"prep_ex06","title":"at, on, in – Zeit und Ort","source":"prepositions unit (Unit 9) – Activity 2 + Activity 4","type":"gap","instruction":"at, on oder in? Wähle die richtige Präposition.","questions":[{"parts":["",{"opts":["at","on","in"],"decode":["um","am","im"],"correct":1}," Monday, ",{"opts":["at","on","in"],"decode":["um","am","im"],"correct":0}," 9 o'clock, ",{"opts":["at","on","in"],"decode":["um","am","im"],"correct":0}," midnight, ",{"opts":["at","on","in"],"decode":["um","am","im"],"correct":2}," 2012"],"solutionEn":"on Monday – at 9 o'clock – at midnight – in 2012","solutionDe":"am Montag – um 9 Uhr – um Mitternacht – im Jahr 2012","explain":"at + Uhrzeit (at 9 o'clock, at midnight); on + Tag (on Monday); in + Jahr (in 2012)."},{"parts":["",{"opts":["at","on","in"],"decode":["um","am","im"],"correct":1}," Friday, ",{"opts":["at","on","in"],"decode":["um","am","im"],"correct":1}," January 1st, ",{"opts":["at","on","in"],"decode":["um","am","im"],"correct":2}," January, ",{"opts":["at","on","in"],"decode":["um","am","im"],"correct":2}," summer"],"solutionEn":"on Friday – on January 1st – in January – in summer","solutionDe":"am Freitag – am 1. Jänner – im Jänner – im Sommer","explain":"on + Tag und Datum (on Friday, on January 1st); in + Monat und Jahreszeit (in January, in summer)."},{"parts":["",{"opts":["at","on","in"],"decode":["bei/in","auf","in"],"correct":0}," Union Bank, ",{"opts":["at","on","in"],"decode":["bei","auf/in","in"],"correct":1}," Pine Street, ",{"opts":["at","on","in"],"decode":["bei/in","auf","in"],"correct":0}," 277 Pine Street, ",{"opts":["at","on","in"],"decode":["bei","auf","in"],"correct":2}," Los Angeles"],"solutionEn":"at Union Bank – on Pine Street – at 277 Pine Street – in Los Angeles","solutionDe":"bei der Union Bank – in der Pine Street – Pine Street 277 (genaue Adresse) – in Los Angeles","explain":"at + bestimmter Ort/genaue Adresse mit Hausnummer; on + Straße (ohne Nummer); in + Stadt."},{"parts":["",{"opts":["at","on","in"],"decode":["bei","auf","in"],"correct":2}," California, ",{"opts":["at","on","in"],"decode":["bei","auf","in"],"correct":2}," the United States, ",{"opts":["at","on","in"],"decode":["bei/an","auf","in"],"correct":0}," Minnesota University, ",{"opts":["at","on","in"],"decode":["bei","auf","in"],"correct":0}," Shoes for Less"],"solutionEn":"in California – in the United States – at Minnesota University – at Shoes for Less","solutionDe":"in Kalifornien – in den USA – an der Minnesota University – bei „Shoes for Less“ (Geschäft)","explain":"in + Bundesstaat/Land; at + Institution/Geschäft (Universität, Bank, Shop)."}]}]},{"id":"presentation","title":"Presentations","icon":"🎤","phase":2,"birkenbihl":[{"id":"pres_t1","title":"Opening: Welcome, Topic, Structure","sentences":[{"id":"pres_t1_s01","en":"Good morning, ladies and gentlemen – it's a pleasure to welcome you today.","decode":[["Good morning,","guten Morgen,"],["ladies","Damen"],["and","und"],["gentlemen","Herren"],["–","–"],["it's","es ist"],["a","eine"],["pleasure","Freude"],["to welcome","zu begrüßen"],["you","Sie"],["today.","heute."]],"de":"Guten Morgen, meine Damen und Herren – es ist mir eine Freude, Sie heute zu begrüßen."},{"id":"pres_t1_s02","en":"First of all, let me thank you all for coming here today.","decode":[["First of all,","zuallererst"],["let me","lassen Sie mich"],["thank","danken"],["you all","Ihnen allen"],["for coming","für das Kommen"],["here","hierher"],["today.","heute."]],"de":"Zuallererst möchte ich Ihnen allen dafür danken, dass Sie heute hierhergekommen sind."},{"id":"pres_t1_s03","en":"Let me introduce myself – my name is Ann Brown.","decode":[["Let me","lassen Sie mich"],["introduce","vorstellen"],["myself","mich selbst"],["–","–"],["my","mein"],["name","Name"],["is","ist"],["Ann Brown.","Ann Brown."]],"de":"Darf ich mich vorstellen – mein Name ist Ann Brown."},{"id":"pres_t1_s04","en":"Today I'm going to talk about music streaming.","decode":[["Today","heute"],["I'm going to","werde ich"],["talk about","sprechen über"],["music streaming.","Musik-Streaming."]],"de":"Heute werde ich über Musik-Streaming sprechen."},{"id":"pres_t1_s05","en":"I've divided my presentation into three main parts.","decode":[["I've divided","ich habe unterteilt"],["my","meine"],["presentation","Präsentation"],["into","in"],["three","drei"],["main","Haupt-"],["parts.","Teile."]],"de":"Ich habe meine Präsentation in drei Hauptteile gegliedert."},{"id":"pres_t1_s06","en":"I'll begin by looking at the first point, and then I'll move on to the second.","decode":[["I'll begin","ich beginne"],["by looking at","mit dem Betrachten von"],["the first","dem ersten"],["point,","Punkt,"],["and then","und dann"],["I'll move on","gehe ich weiter"],["to the second.","zum zweiten."]],"de":"Ich beginne mit dem ersten Punkt und gehe dann zum zweiten über."},{"id":"pres_t1_s07","en":"If you have any questions, feel free to interrupt me at any time.","decode":[["If","falls"],["you","Sie"],["have","haben"],["any","irgendwelche"],["questions,","Fragen,"],["feel free","zögern Sie nicht"],["to interrupt","zu unterbrechen"],["me","mich"],["at any time.","jederzeit."]],"de":"Wenn Sie Fragen haben, unterbrechen Sie mich gerne jederzeit."}]},{"id":"pres_t2","title":"Main Part: Transitions and Visuals","sentences":[{"id":"pres_t2_s01","en":"This brings me to the end of my first point.","decode":[["This","das"],["brings","bringt"],["me","mich"],["to the end","zum Ende"],["of my","meines"],["first","ersten"],["point.","Punktes."]],"de":"Das bringt mich zum Ende meines ersten Punktes."},{"id":"pres_t2_s02","en":"Let's now move on to the next question.","decode":[["Let's","lassen Sie uns"],["now","jetzt"],["move on","weitergehen"],["to the next","zur nächsten"],["question.","Frage."]],"de":"Gehen wir jetzt zur nächsten Frage über."},{"id":"pres_t2_s03","en":"As I mentioned earlier, this point is particularly important.","decode":[["As","wie"],["I","ich"],["mentioned","erwähnte"],["earlier,","vorhin,"],["this","dieser"],["point","Punkt"],["is","ist"],["particularly","besonders"],["important.","wichtig."]],"de":"Wie ich vorhin erwähnt habe, ist dieser Punkt besonders wichtig."},{"id":"pres_t2_s04","en":"Let's now look at the next slide, which shows the sales figures.","decode":[["Let's","lassen Sie uns"],["now","jetzt"],["look at","ansehen"],["the next","die nächste"],["slide,","Folie,"],["which","die"],["shows","zeigt"],["the","die"],["sales figures.","Verkaufszahlen."]],"de":"Schauen wir uns jetzt die nächste Folie an, die die Verkaufszahlen zeigt."},{"id":"pres_t2_s05","en":"As you can see here, sales increased slightly in summer.","decode":[["As","wie"],["you","Sie"],["can","können"],["see","sehen"],["here,","hier,"],["sales","die Verkäufe"],["increased","stiegen"],["slightly","leicht"],["in summer.","im Sommer."]],"de":"Wie Sie hier sehen können, stiegen die Verkäufe im Sommer leicht an."}]},{"id":"pres_t3","title":"Conclusion and Questions","sentences":[{"id":"pres_t3_s01","en":"Well, this brings me to the end of my presentation.","decode":[["Well,","nun,"],["this","das"],["brings","bringt"],["me","mich"],["to the end","zum Ende"],["of my","meiner"],["presentation.","Präsentation."]],"de":"Nun, das bringt mich zum Ende meiner Präsentation."},{"id":"pres_t3_s02","en":"Before I stop, let me go over the key issues again.","decode":[["Before","bevor"],["I","ich"],["stop,","aufhöre,"],["let me","lassen Sie mich"],["go over","durchgehen"],["the key issues","die Kernpunkte"],["again.","noch einmal."]],"de":"Bevor ich zum Schluss komme, möchte ich die Kernpunkte noch einmal durchgehen."},{"id":"pres_t3_s03","en":"And now I'll be happy to answer any questions you may have.","decode":[["And","und"],["now","jetzt"],["I'll be happy","beantworte ich gerne"],["to answer","–"],["any","alle"],["questions","Fragen"],["you may have.","die Sie haben."]],"de":"Und jetzt beantworte ich gerne alle Fragen, die Sie haben."}]}],"exercises":[{"id":"pres_ex01","title":"Welche Phrase gehört zu welcher Phase?","source":"Useful Phrases (Cornelsen) – Zuordnungsübung","type":"mc","instruction":"Zu welcher Phase der Präsentation gehört diese Phrase?","questions":[{"parts":["'First of all, let me thank you all for coming here today.' ",{"opts":["moving to the next point","welcoming the audience","ending the talk"],"decode":["Übergang zum nächsten Punkt","Begrüßung des Publikums","Ende des Vortrags"],"correct":1}],"solutionEn":"welcoming the audience","solutionDe":"Begrüßung des Publikums (Einleitung)","explain":"Dankes- und Begrüßungsphrasen ('thank you all for coming') stehen ganz am Anfang der Präsentation."},{"parts":["'This leads directly to my next point.' ",{"opts":["moving to the next point","dealing with questions","welcoming the audience"],"decode":["Übergang zum nächsten Punkt","Umgang mit Fragen","Begrüßung des Publikums"],"correct":0}],"solutionEn":"moving to the next point","solutionDe":"Übergang zum nächsten Punkt (Hauptteil)","explain":"lead to = führen zu. Alternative Übergänge: 'Let's now move on to …', 'This brings us to the next question.'"},{"parts":["'Let's now look at the next slide, which shows our results.' ",{"opts":["introducing yourself","quoting a well-known person","introducing a visual"],"decode":["sich vorstellen","eine berühmte Person zitieren","eine Folie/Grafik einführen"],"correct":2}],"solutionEn":"introducing a visual","solutionDe":"eine Folie/Grafik einführen","explain":"slide = Folie. Weitere Visual-Phrasen: 'As you can see here, …', 'The chart on the following slide shows …'"},{"parts":["'To conclude, I'd like to run through my main points again.' ",{"opts":["stating your purpose","summarizing at the end","using an interesting fact as an opener"],"decode":["das Ziel nennen","Zusammenfassung am Schluss","mit einem interessanten Fakt einsteigen"],"correct":1}],"solutionEn":"summarizing at the end","solutionDe":"Zusammenfassung am Schluss","explain":"to conclude = abschließend; run through = durchgehen. Auch: 'To sum up …', 'Just to summarize the main points of my talk …'"},{"parts":["'I'm sorry, could you repeat your question, please?' ",{"opts":["dealing with questions","explaining a visual","introducing your topic"],"decode":["Umgang mit Fragen","eine Grafik erklären","das Thema vorstellen"],"correct":0}],"solutionEn":"dealing with questions","solutionDe":"Umgang mit Fragen (nach der Präsentation)","explain":"Wenn man eine Frage nicht verstanden hat: 'I'm afraid I didn't quite catch that.' / 'Could you repeat your question, please?'"},{"parts":["'The purpose of this presentation is to give you an overview of our project.' ",{"opts":["indicating the end of your talk","going back to an earlier point","stating your purpose"],"decode":["das Ende ankündigen","auf einen früheren Punkt zurückkommen","das Ziel/den Zweck nennen"],"correct":2}],"solutionEn":"stating your purpose","solutionDe":"das Ziel/den Zweck der Präsentation nennen (Einleitung)","explain":"purpose = Zweck/Ziel. Auch: 'My objective is to …', 'Today I'd like to give you an overview of …'"}]},{"id":"pres_ex02","title":"Complete the Phrase","source":"Useful Phrases (Cornelsen) – Lückentexte","type":"gap","instruction":"Vervollständige die Präsentationsphrase mit dem richtigen Wort.","questions":[{"parts":["Let me ",{"opts":["welcome","introduce","present"],"decode":["begrüßen","vorstellen","präsentieren"],"correct":1}," myself. My name is Lisa Berger."],"solutionEn":"introduce","solutionDe":"vorstellen","explain":"Let me introduce myself = Darf ich mich vorstellen. 'welcome myself' und 'present myself' sagt man nicht."},{"parts":["I've ",{"opts":["divided","cut","broken"],"decode":["unterteilt","geschnitten","zerbrochen"],"correct":0}," my presentation into three main parts."],"solutionEn":"divided","solutionDe":"unterteilt/gegliedert","explain":"divide into = unterteilen in. Feste Phrase: 'I've divided my presentation into three (main) parts.'"},{"parts":["Let's now move ",{"opts":["over","on","up"],"decode":["hinüber","weiter","hinauf"],"correct":1}," to my next point."],"solutionEn":"on","solutionDe":"weiter – move on to = übergehen zu","explain":"move on to = zum nächsten Punkt übergehen. Auch: 'Let's now turn to …'"},{"parts":["By the ",{"opts":["end","finish","stop"],"decode":["Ende","Ziel(einlauf)","Halt"],"correct":0}," of this talk you will be familiar with the topic."],"solutionEn":"end","solutionDe":"Ende – by the end of = am Ende von","explain":"'By the end of this talk you will be familiar with …' = Am Ende dieses Vortrags werden Sie … kennen. be familiar with = vertraut sein mit."},{"parts":["As you can ",{"opts":["watch","look","see"],"decode":["zuschauen","schauen","sehen"],"correct":2}," here, prices went up significantly."],"solutionEn":"see","solutionDe":"sehen – as you can see = wie Sie sehen können","explain":"Feste Phrase: 'As you can see here, …'. 'look' bräuchte 'look at' und 'watch' passt nur bei bewegten Bildern."},{"parts":["This ",{"opts":["brings","carries","puts"],"decode":["bringt","trägt","setzt"],"correct":0}," me to the end of my presentation."],"solutionEn":"brings","solutionDe":"bringt – this brings me to = das bringt mich zu","explain":"Feste Phrase: 'This brings me to the end of my presentation.' Auch für Übergänge: 'This brings us to the next question.'"},{"parts":["I'd like to draw your ",{"opts":["eyes","attention","interest"],"decode":["Augen","Aufmerksamkeit","Interesse"],"correct":1}," to this chart."],"solutionEn":"attention","solutionDe":"Aufmerksamkeit – draw attention to = Aufmerksamkeit lenken auf","explain":"draw someone's attention to = jemandes Aufmerksamkeit auf etwas lenken. chart = Diagramm/Grafik."},{"parts":["Feel ",{"opts":["free","happy","glad"],"decode":["frei","glücklich","froh"],"correct":0}," to ask questions at any time."],"solutionEn":"free","solutionDe":"feel free to = Sie können gerne …","explain":"'Feel free to ask questions at any time.' = Stellen Sie jederzeit gerne Fragen. Feste Wendung: feel free to + Infinitiv."}]},{"id":"pres_ex03","title":"Aufbau einer Präsentation","source":"How to give a Presentation (PPTX), Folien 6–13","type":"order","instruction":"Bringe die Teile in die richtige Reihenfolge (Schritt 1 bis Schritt 4).","questions":[{"parts":["So beginnt die Einleitung – Schritt 1: ",{"opts":["Greeting and introducing yourself","Introducing the topic and why you chose it","Giving a short overview of the presentation","Saying when the audience can ask questions"],"decode":["Begrüßung und sich vorstellen","das Thema vorstellen und begründen","kurzen Überblick über die Präsentation geben","sagen, wann das Publikum Fragen stellen darf"],"correct":0}," → Schritt 2: ",{"opts":["Greeting and introducing yourself","Introducing the topic and why you chose it","Giving a short overview of the presentation","Saying when the audience can ask questions"],"decode":["Begrüßung und sich vorstellen","das Thema vorstellen und begründen","kurzen Überblick über die Präsentation geben","sagen, wann das Publikum Fragen stellen darf"],"correct":1}," → Schritt 3: ",{"opts":["Greeting and introducing yourself","Introducing the topic and why you chose it","Giving a short overview of the presentation","Saying when the audience can ask questions"],"decode":["Begrüßung und sich vorstellen","das Thema vorstellen und begründen","kurzen Überblick über die Präsentation geben","sagen, wann das Publikum Fragen stellen darf"],"correct":2}," → Schritt 4: ",{"opts":["Greeting and introducing yourself","Introducing the topic and why you chose it","Giving a short overview of the presentation","Saying when the audience can ask questions"],"decode":["Begrüßung und sich vorstellen","das Thema vorstellen und begründen","kurzen Überblick über die Präsentation geben","sagen, wann das Publikum Fragen stellen darf"],"correct":3}],"solutionEn":"1. Greeting and introducing yourself → 2. Introducing the topic and why you chose it → 3. Giving a short overview → 4. Saying when the audience can ask questions","solutionDe":"1. Begrüßung + Vorstellung → 2. Thema + Warum dieses Thema? → 3. Kurzer Überblick → 4. Fragen-Regelung","explain":"Typische Reihenfolge der Einleitung laut Folien: Greeting → Topic (+ why this topic?) → Short overview ('What will I talk about?') → Hinweis, wann Fragen erlaubt sind."},{"parts":["Die ganze Präsentation – Teil 1: ",{"opts":["Introduction: greeting, topic, overview","Main part: points with explanations and examples","Conclusion: short summary and final thought","Questions from the audience"],"decode":["Einleitung: Begrüßung, Thema, Überblick","Hauptteil: Punkte mit Erklärungen und Beispielen","Schluss: kurze Zusammenfassung und Schlussgedanke","Fragen aus dem Publikum"],"correct":0}," → Teil 2: ",{"opts":["Introduction: greeting, topic, overview","Main part: points with explanations and examples","Conclusion: short summary and final thought","Questions from the audience"],"decode":["Einleitung: Begrüßung, Thema, Überblick","Hauptteil: Punkte mit Erklärungen und Beispielen","Schluss: kurze Zusammenfassung und Schlussgedanke","Fragen aus dem Publikum"],"correct":1}," → Teil 3: ",{"opts":["Introduction: greeting, topic, overview","Main part: points with explanations and examples","Conclusion: short summary and final thought","Questions from the audience"],"decode":["Einleitung: Begrüßung, Thema, Überblick","Hauptteil: Punkte mit Erklärungen und Beispielen","Schluss: kurze Zusammenfassung und Schlussgedanke","Fragen aus dem Publikum"],"correct":2}," → Teil 4: ",{"opts":["Introduction: greeting, topic, overview","Main part: points with explanations and examples","Conclusion: short summary and final thought","Questions from the audience"],"decode":["Einleitung: Begrüßung, Thema, Überblick","Hauptteil: Punkte mit Erklärungen und Beispielen","Schluss: kurze Zusammenfassung und Schlussgedanke","Fragen aus dem Publikum"],"correct":3}],"solutionEn":"1. Introduction → 2. Main part (point 1, 2, 3 – each with explanation and example/fact) → 3. Conclusion (short summary, final thought) → 4. Questions","solutionDe":"1. Einleitung → 2. Hauptteil (Punkt 1–3, je mit Erklärung und Beispiel/Fakt; ggf. Vor-/Nachteile und eigene Meinung) → 3. Schluss (kurze Zusammenfassung, Schlussgedanke) → 4. Fragen","explain":"Laut Folien: Im Hauptteil jeder Punkt mit Explanation + Example/Fact. Im Schluss: Signal, dass die Präsentation endet, Zusammenfassung ODER Kernbotschaft wiederholen, dann Fragen zulassen."}]},{"id":"pres_ex04","title":"How to Present: Tipps aus den Folien","source":"How to give a Presentation (PPTX), Folien 15–21","type":"mc","instruction":"Was empfehlen die Folien? Wähle die richtige Antwort.","questions":[{"parts":["According to the slides, your slides should … ",{"opts":["be crowded and full of text","use minimal text and meaningful visuals","use as many animations and transitions as possible"],"decode":["überladen und voller Text sein","wenig Text und aussagekräftige Bilder verwenden","so viele Animationen und Übergänge wie möglich verwenden"],"correct":1}],"solutionEn":"use minimal text and meaningful visuals","solutionDe":"wenig Text und aussagekräftige Bilder verwenden","explain":"Folie 15: 'Adopt a clean, uncluttered approach' – volle Folien lenken ab (crowded or dense = distracting). Animationen sparsam einsetzen."},{"parts":["What is a 'hook' in a presentation? ",{"opts":["a strategy to gain and maintain the audience's interest","a cable for the projector","a difficult question from the audience"],"decode":["eine Strategie, um das Interesse des Publikums zu gewinnen und zu halten","ein Kabel für den Beamer","eine schwierige Frage aus dem Publikum"],"correct":0}],"solutionEn":"a strategy to gain and maintain the audience's interest","solutionDe":"eine Strategie, um das Interesse des Publikums zu gewinnen und zu halten","explain":"Folie 19: Hooks = ein Problem aufwerfen, eine Frage stellen oder ein Bild einsetzen. Beispiel-Titel: 'Music: The Soundtrack of Our Generation'."},{"parts":["Good body language during a presentation means … ",{"opts":["reading from your notes all the time","an open stance, facial expressions and eye contact","standing completely still with your hands in your pockets"],"decode":["die ganze Zeit von den Notizen ablesen","eine offene Haltung, Mimik und Blickkontakt","völlig still stehen mit den Händen in den Taschen"],"correct":1}],"solutionEn":"an open stance, facial expressions and eye contact","solutionDe":"eine offene Haltung, Mimik und Blickkontakt","explain":"Folie 20: body language = Körpersprache; open stance = offene Haltung; eye contact = Blickkontakt."},{"parts":["Why is repetition useful in a presentation? ",{"opts":["It makes the talk longer.","It helps memory and creates emphasis.","It replaces the conclusion."],"decode":["sie macht den Vortrag länger","sie hilft dem Gedächtnis und betont Wichtiges","sie ersetzt den Schluss"],"correct":1}],"solutionEn":"It helps memory and creates emphasis.","solutionDe":"Sie hilft dem Gedächtnis und betont Wichtiges.","explain":"Folie 21: 'Repetition: repeating key phrases – memory and emphasis'. Bei der Stimme außerdem wichtig: pacing, pausing, stress and intonation."}]}]},{"id":"quantifiers","title":"Quantifiers","icon":"🔢","phase":2,"birkenbihl":[{"id":"quant_t1","title":"much, many, a lot of, some, any – Beispielsätze","sentences":[{"id":"quant_t1_s01","en":"There isn't much water in the bottle.","decode":[["There isn't","es-gibt-nicht"],["much","viel"],["water","Wasser"],["in","in"],["the","der"],["bottle.","Flasche."]],"de":"In der Flasche ist nicht viel Wasser. (much + unzählbar, in Verneinung/Frage)"},{"id":"quant_t1_s02","en":"He doesn't have many cups.","decode":[["He","er"],["doesn't have","hat-nicht"],["many","viele"],["cups.","Tassen."]],"de":"Er hat nicht viele Tassen. (many + zählbar, in Verneinung/Frage)"},{"id":"quant_t1_s03","en":"There are a lot of people in the park.","decode":[["There are","es-gibt"],["a lot of","viele"],["people","Leute"],["in","in"],["the","dem"],["park.","Park."]],"de":"Im Park sind viele Leute. (a lot of = bejahter Satz, zählbar UND unzählbar)"},{"id":"quant_t1_s04","en":"She bought some milk from the store.","decode":[["She","sie"],["bought","kaufte"],["some","etwas"],["milk","Milch"],["from","aus"],["the","dem"],["store.","Geschäft."]],"de":"Sie hat im Geschäft etwas Milch gekauft. (some = bejahter Satz)"},{"id":"quant_t1_s05","en":"Is there any coffee left?","decode":[["Is there","gibt-es"],["any","(irgend)etwas"],["coffee","Kaffee"],["left?","übrig?"]],"de":"Ist noch Kaffee übrig? (any = Frage und Verneinung)"}]},{"id":"quant_t2","title":"(a) few, (a) little, no – Beispielsätze","sentences":[{"id":"quant_t2_s01","en":"There is no cake left! Ben's eaten the whole thing!","decode":[["There is","es-gibt"],["no","keinen"],["cake","Kuchen"],["left!","übrig!"],["Ben's eaten","Ben-hat-gegessen"],["the whole thing!","das-Ganze!"]],"de":"Es ist kein Kuchen mehr übrig! Ben hat alles aufgegessen! (no + Nomen = kein)"},{"id":"quant_t2_s02","en":"She has very few friends.","decode":[["She","sie"],["has","hat"],["very","sehr"],["few","wenige"],["friends.","Freunde."]],"de":"Sie hat sehr wenige Freunde. (few + zählbar = wenige, negativ gemeint)"},{"id":"quant_t2_s03","en":"We've got very little petrol left.","decode":[["We've got","wir-haben"],["very","sehr"],["little","wenig"],["petrol","Benzin"],["left.","übrig."]],"de":"Wir haben nur noch sehr wenig Benzin. (little + unzählbar = wenig, negativ gemeint)"},{"id":"quant_t2_s04","en":"We stayed a few days in Florence and visited the museums.","decode":[["We","wir"],["stayed","blieben"],["a few","ein-paar"],["days","Tage"],["in","in"],["Florence","Florenz"],["and","und"],["visited","besuchten"],["the","die"],["museums.","Museen."]],"de":"Wir blieben ein paar Tage in Florenz und besuchten die Museen. (a few = ein paar, positiv gemeint)"},{"id":"quant_t2_s05","en":"She drank some tea and ate a little bread.","decode":[["She","sie"],["drank","trank"],["some","etwas"],["tea","Tee"],["and","und"],["ate","aß"],["a little","ein-wenig"],["bread.","Brot."]],"de":"Sie trank etwas Tee und aß ein wenig Brot. (a little = ein wenig, positiv gemeint)"}]}],"exercises":[{"id":"quant_ex01","title":"Annas Party (Lückentext)","source":"Quantifiers (PPTX) – Folien 3/4","type":"gap","instruction":"Setze den richtigen Quantifier ein.","questions":[{"parts":["Anna is planning a party for her friends. She bought ",{"opts":["some","any","much"],"decode":["ein-paar/etwas","irgendwelche","viel"],"correct":0}," snacks and ",{"opts":["a little","a few","much"],"decode":["ein-wenig","ein-paar","viel"],"correct":1}," bottles of juice."],"solutionEn":"She bought some snacks and a few bottles of juice.","solutionDe":"Sie hat ein paar Snacks und ein paar Flaschen Saft gekauft.","explain":"some = bejahter Satz; a few + zählbares Nomen im Plural (bottles)."},{"parts":["She didn't buy ",{"opts":["many","much","a few"],"decode":["viele","viel","ein-paar"],"correct":1}," soda because ",{"opts":["much","many","a little"],"decode":["viel","viele","ein-wenig"],"correct":1}," of her friends prefer water."],"solutionEn":"She didn't buy much soda because many of her friends prefer water.","solutionDe":"Sie hat nicht viel Limonade gekauft, weil viele ihrer Freunde lieber Wasser trinken.","explain":"much + unzählbar (soda) in der Verneinung; many + zählbar (friends)."},{"parts":["There are also ",{"opts":["a lot of","much","any"],"decode":["viele","viel","irgendwelche"],"correct":0}," sandwiches, but there aren't ",{"opts":["some","no","any"],"decode":["einige","keine","irgendwelche"],"correct":2}," vegetarian options yet. She still has ",{"opts":["a few","a little","many"],"decode":["ein-paar","ein-wenig","viele"],"correct":1}," time to go to the supermarket."],"solutionEn":"There are also a lot of sandwiches, but there aren't any vegetarian options yet. She still has a little time to go to the supermarket.","solutionDe":"Es gibt auch viele Sandwiches, aber noch keine vegetarischen Optionen. Sie hat noch ein wenig Zeit, um in den Supermarkt zu gehen.","explain":"a lot of im bejahten Satz; any in der Verneinung (aren't … any); a little + unzählbar (time)."}]},{"id":"quant_ex02","title":"Quantifiers – Key Practice 1–10","source":"Key_Practice – Quantifiers 1–10","type":"gap","instruction":"Wähle den richtigen Quantifier.","questions":[{"parts":["There aren't ",{"opts":["much","many","a little"],"decode":["viel","viele","ein-wenig"],"correct":1}," honest people in the world these days."],"solutionEn":"There aren't many honest people in the world these days.","solutionDe":"Es gibt heutzutage nicht viele ehrliche Menschen auf der Welt.","explain":"people = zählbar (Plural) → many. much nur bei unzählbaren Nomen."},{"parts":["This man is a mystery. We have very ",{"opts":["few","little","a little"],"decode":["wenige","wenig","ein-wenig"],"correct":1}," information about his private life."],"solutionEn":"We have very little information about his private life.","solutionDe":"Wir haben sehr wenig Informationen über sein Privatleben.","explain":"information = unzählbar → little. few nur bei zählbaren Nomen; a little wäre positiv („ein wenig“), hier ist „fast nichts“ gemeint."},{"parts":["She isn't the most popular person in the class. She has very ",{"opts":["few","little","a few"],"decode":["wenige","wenig","ein-paar"],"correct":0}," friends."],"solutionEn":"She has very few friends.","solutionDe":"Sie hat sehr wenige Freunde.","explain":"friends = zählbar → few (negativ: fast keine). a few wäre positiv („ein paar“)."},{"parts":["Our team is losing 1:0 but there is still ",{"opts":["any","no","some"],"decode":["irgendeine","keine","etwas"],"correct":2}," hope that they'll turn the game around."],"solutionEn":"There is still some hope that they'll turn the game around.","solutionDe":"Es gibt noch etwas Hoffnung, dass sie das Spiel drehen.","explain":"Bejahter Satz → some. any nur in Frage/Verneinung."},{"parts":["",{"opts":["Few","A few","Little"],"decode":["wenige","ein-paar","wenig"],"correct":0}," students have such good marks. She is an unmatched genius."],"solutionEn":"Few students have such good marks.","solutionDe":"Nur wenige Schüler haben so gute Noten.","explain":"Gemeint ist „fast niemand“ → Few (negativ). A few („ein paar“) würde den Sinn abschwächen; little nur bei unzählbaren Nomen."},{"parts":["I've read only the first chapter, that's why I don't have ",{"opts":["many","much","a few"],"decode":["viele","viel","ein-paar"],"correct":1}," to say about the characters."],"solutionEn":"I don't have much to say about the characters.","solutionDe":"Ich kann nicht viel über die Figuren sagen.","explain":"much in der Verneinung (nicht viel zu sagen) – „much“ steht hier allein (unzählbare Menge)."},{"parts":["There is ",{"opts":["no","any","none"],"decode":["kein","irgendein","keiner"],"correct":0}," cake left! Ben's eaten the whole thing!"],"solutionEn":"There is no cake left! Ben's eaten the whole thing!","solutionDe":"Es ist kein Kuchen mehr übrig! Ben hat alles aufgegessen!","explain":"no + Nomen = kein (im bejahten Satzbau). any bräuchte eine Verneinung (isn't any); none steht ohne Nomen."},{"parts":["Can I ask you for ",{"opts":["a few","little","a little"],"decode":["ein-paar","wenig","ein-wenig"],"correct":2}," patience? I'll be back in 5 minutes."],"solutionEn":"Can I ask you for a little patience?","solutionDe":"Darf ich dich um ein wenig Geduld bitten?","explain":"patience = unzählbar → (a) little; positiv gemeint („ein wenig Geduld“) → a little."},{"parts":["Science doesn't interest me. It's the subject I know very ",{"opts":["few","little","a little"],"decode":["wenige","wenig","ein-wenig"],"correct":1}," about."],"solutionEn":"It's the subject I know very little about.","solutionDe":"Es ist das Fach, über das ich sehr wenig weiß.","explain":"know little about = wenig wissen (unzählbar, negativ gemeint)."},{"parts":["The party was ok but there wasn't ",{"opts":["much","many","a lot"],"decode":["viel","viele","viel"],"correct":0}," dancing."],"solutionEn":"The party was ok but there wasn't much dancing.","solutionDe":"Die Party war okay, aber es wurde nicht viel getanzt.","explain":"dancing = unzählbar, Verneinung → much. „a lot“ bräuchte „of“ vor einem Nomen und passt stilistisch in Verneinungen nicht."}]},{"id":"quant_ex03","title":"Quantifiers – Key Practice 11–20","source":"Key_Practice – Quantifiers 11–20","type":"gap","instruction":"Wähle den richtigen Quantifier.","questions":[{"parts":["We'd better go to the petrol station. We've got very ",{"opts":["a little","few","little"],"decode":["ein-wenig","wenige","wenig"],"correct":2}," petrol left."],"solutionEn":"We've got very little petrol left.","solutionDe":"Wir haben nur noch sehr wenig Benzin.","explain":"petrol = unzählbar → little (negativ: fast nichts mehr). Nach „very“ steht nie „a little“."},{"parts":["Tomorrow's party will be legendary! There'll be ",{"opts":["much","a lot of","any"],"decode":["viel","viele","irgendwelche"],"correct":1}," people!"],"solutionEn":"There'll be a lot of people!","solutionDe":"Da werden viele Leute sein!","explain":"Bejahter Satz + zählbares Nomen → a lot of. much nur bei unzählbaren Nomen in Frage/Verneinung."},{"parts":["My wallet is empty. I have ",{"opts":["any","no","much"],"decode":["irgendein","kein","viel"],"correct":1}," money whatsoever."],"solutionEn":"I have no money whatsoever.","solutionDe":"Ich habe überhaupt kein Geld.","explain":"no + Nomen = überhaupt kein. any bräuchte ein verneintes Verb (don't have any)."},{"parts":["In his new flat there is ",{"opts":["little","few","a few"],"decode":["wenig","wenige","ein-paar"],"correct":0}," furniture. Maybe one chair and a small table."],"solutionEn":"In his new flat there is little furniture.","solutionDe":"In seiner neuen Wohnung gibt es wenig Möbel.","explain":"furniture = unzählbar (im Englischen!) → little. Achtung: „Möbel“ ist im Deutschen Plural, im Englischen aber uncountable."},{"parts":["Her grades have improved greatly. She's made ",{"opts":["many","much","a lot of"],"decode":["viele","viel","viel"],"correct":2}," progress."],"solutionEn":"She's made a lot of progress.","solutionDe":"Sie hat große Fortschritte gemacht.","explain":"progress = unzählbar; bejahter Satz → a lot of. much wäre nur in Frage/Verneinung üblich."},{"parts":["Norway is a very rich country. There isn't ",{"opts":["many","much","few"],"decode":["viele","viel","wenige"],"correct":1}," poverty."],"solutionEn":"There isn't much poverty.","solutionDe":"Es gibt nicht viel Armut.","explain":"poverty = unzählbar, Verneinung → much."},{"parts":["",{"opts":["Any","No","Some"],"decode":["irgendwelche","keine","einige"],"correct":2}," school subjects are easier than others."],"solutionEn":"Some school subjects are easier than others.","solutionDe":"Manche Schulfächer sind leichter als andere.","explain":"Bejahter Satz → some (hier: „manche“)."},{"parts":["I could rely on him in the past but this time he offered me ",{"opts":["no","any","little"],"decode":["keine","irgendwelche","wenig"],"correct":0}," help."],"solutionEn":"This time he offered me no help.","solutionDe":"Dieses Mal hat er mir keine Hilfe angeboten.","explain":"no + Nomen = kein/keine. Der Satz ist bejaht (offered), daher kein any."},{"parts":["The suspect was released because too ",{"opts":["few","little","a little"],"decode":["wenige","wenig","ein-wenig"],"correct":1}," evidence was presented."],"solutionEn":"Too little evidence was presented.","solutionDe":"Es wurden zu wenige Beweise vorgelegt.","explain":"evidence = unzählbar (im Englischen!) → little. „too little evidence“ = zu wenig Beweismaterial."},{"parts":["There aren't ",{"opts":["much","many","no"],"decode":["viel","viele","keine"],"correct":1}," things to do in Egypt that are free of charge."],"solutionEn":"There aren't many things to do in Egypt that are free of charge.","solutionDe":"In Ägypten gibt es nicht viele Dinge, die gratis sind.","explain":"things = zählbar, Verneinung → many. no ginge nur ohne „aren't“ (There are no things …)."}]},{"id":"quant_ex04","title":"much/many – some/any: Grundregeln","source":"Quantifiers (PPTX) – Folien 18/19","type":"gap","instruction":"Wähle die richtige Form.","questions":[{"parts":["How ",{"opts":["much","many"],"decode":["viel","viele"],"correct":0}," money do you need?"],"solutionEn":"How much money do you need?","solutionDe":"Wie viel Geld brauchst du?","explain":"money = unzählbar → how much."},{"parts":["How ",{"opts":["much","many"],"decode":["viel","viele"],"correct":1}," apples do you want?"],"solutionEn":"How many apples do you want?","solutionDe":"Wie viele Äpfel willst du?","explain":"apples = zählbar (Plural) → how many."},{"parts":["Do you have ",{"opts":["some","any"],"decode":["etwas","irgendetwas"],"correct":1}," milk left?"],"solutionEn":"Do you have any milk left?","solutionDe":"Hast du noch Milch übrig?","explain":"Frage → any. (some nur in bejahten Sätzen oder bei Angeboten wie „Would you like some tea?“)"},{"parts":["I bought ",{"opts":["some","any"],"decode":["ein-paar","irgendwelche"],"correct":0}," apples at the market."],"solutionEn":"I bought some apples at the market.","solutionDe":"Ich habe am Markt ein paar Äpfel gekauft.","explain":"Bejahter Satz → some."}]}]},{"id":"shopping","title":"Shopping","icon":"🛒","phase":2,"birkenbihl":[{"id":"shop_t1","title":"Shopping Vocabulary in Context","sentences":[{"id":"shop_t1_s01","en":"I always shop around before I buy something expensive.","decode":[["I","ich"],["always","immer"],["shop around","vergleiche die Preise"],["before","bevor"],["I","ich"],["buy","kaufe"],["something","etwas"],["expensive.","Teures."]],"de":"Ich vergleiche immer die Preise in mehreren Geschäften, bevor ich etwas Teures kaufe."},{"id":"shop_t1_s02","en":"Last week I had to return a jumper to the store because it was too small.","decode":[["Last week","letzte Woche"],["I","ich"],["had to","musste"],["return","zurückbringen"],["a","einen"],["jumper","Pullover"],["to the store","ins Geschäft"],["because","weil"],["it","er"],["was","war"],["too","zu"],["small.","klein."]],"de":"Letzte Woche musste ich einen Pullover ins Geschäft zurückbringen, weil er zu klein war."},{"id":"shop_t1_s03","en":"I have a points card for my favourite supermarket and use my points regularly.","decode":[["I","ich"],["have","habe"],["a","eine"],["points card","Punktekarte"],["for","für"],["my","meinen"],["favourite","Lieblings-"],["supermarket","Supermarkt"],["and","und"],["use","nutze"],["my","meine"],["points","Punkte"],["regularly.","regelmäßig."]],"de":"Ich habe eine Punktekarte für meinen Lieblingssupermarkt und nutze meine Punkte regelmäßig."},{"id":"shop_t1_s04","en":"Many people take advantage of major shopping days like Black Friday.","decode":[["Many","viele"],["people","Leute"],["take advantage of","nutzen die Vorteile von"],["major","großen"],["shopping days","Einkaufstagen"],["like","wie"],["Black Friday.","dem Black Friday."]],"de":"Viele Leute nutzen große Einkaufstage wie den Black Friday aus."},{"id":"shop_t1_s05","en":"My dad does most of the grocery shopping in our home because he loves cooking.","decode":[["My","mein"],["dad","Papa"],["does","erledigt"],["most of","den Großteil"],["the","des"],["grocery shopping","Lebensmitteleinkaufs"],["in our home","bei uns zu Hause"],["because","weil"],["he","er"],["loves","liebt"],["cooking.","das-Kochen."]],"de":"Mein Papa erledigt den Großteil des Lebensmitteleinkaufs bei uns zu Hause, weil er das Kochen liebt."},{"id":"shop_t1_s06","en":"On Saturdays we like to go window shopping in the main shopping street.","decode":[["On Saturdays","samstags"],["we","wir"],["like to go","gehen gerne"],["window shopping","Schaufenster-bummeln"],["in the main","in der Haupt-"],["shopping street.","Einkaufsstraße."]],"de":"Samstags machen wir gerne einen Schaufensterbummel in der Haupteinkaufsstraße."},{"id":"shop_t1_s07","en":"The bargain shopper hunts for special offers, while the impulse buyer buys things spontaneously.","decode":[["The","der"],["bargain shopper","Schnäppchenjäger"],["hunts for","jagt nach"],["special offers,","Sonderangeboten,"],["while","während"],["the","der"],["impulse buyer","Impulskäufer"],["buys","kauft"],["things","Dinge"],["spontaneously.","spontan."]],"de":"Der Schnäppchenjäger jagt nach Sonderangeboten, während der Impulskäufer Dinge spontan kauft."},{"id":"shop_t1_s08","en":"You can buy fresh fish at the fishmonger's and fruit and vegetables at the greengrocer's.","decode":[["You","du"],["can","kannst"],["buy","kaufen"],["fresh","frischen"],["fish","Fisch"],["at the fishmonger's","beim Fischhändler"],["and","und"],["fruit","Obst"],["and","und"],["vegetables","Gemüse"],["at the greengrocer's.","beim Obst- und Gemüsehändler."]],"de":"Frischen Fisch kannst du beim Fischhändler kaufen und Obst und Gemüse beim Gemüsehändler."},{"id":"shop_t1_s09","en":"The florist sells flowers, the optician sells glasses, and the off licence sells alcoholic drinks.","decode":[["The","der"],["florist","Blumenhändler"],["sells","verkauft"],["flowers,","Blumen,"],["the","der"],["optician","Optiker"],["sells","verkauft"],["glasses,","Brillen,"],["and","und"],["the","die"],["off licence","Spirituosenhandlung"],["sells","verkauft"],["alcoholic drinks.","alkoholische Getränke."]],"de":"Der Blumenhändler verkauft Blumen, der Optiker verkauft Brillen und die Spirituosenhandlung verkauft alkoholische Getränke."},{"id":"shop_t1_s10","en":"On my shopping list there are a loaf of bread, some cheese and half a pound of grapes.","decode":[["On","auf"],["my","meiner"],["shopping list","Einkaufsliste"],["there are","stehen"],["a","ein"],["loaf","Laib"],["of bread,","Brot,"],["some","etwas"],["cheese","Käse"],["and","und"],["half a pound","ein halbes Pfund"],["of grapes.","Weintrauben."]],"de":"Auf meiner Einkaufsliste stehen ein Laib Brot, etwas Käse und ein halbes Pfund Weintrauben."}]}],"exercises":[{"id":"shop_ex01","title":"Shopping Vocabulary Quiz","source":"Quiz_ShoppingVocab (allthingstopics) – Fragen 1–14","type":"mc","instruction":"Wähle die richtige Antwort.","questions":[{"parts":["Which of the following things can an 'advertisement' do? ",{"opts":["put things in a bag for you","tell you how much something costs","spend a lot of money","all of the above"],"decode":["Dinge für dich einpacken","dir sagen, wie viel etwas kostet","viel Geld ausgeben","alles oben Genannte"],"correct":1}],"solutionEn":"tell you how much something costs","solutionDe":"dir sagen, wie viel etwas kostet","explain":"advertisement = Werbung. Werbung informiert (z. B. über den Preis) – sie packt nichts ein und gibt kein Geld aus."},{"parts":["If something you bought was a 'bargain', it wasn't … ",{"opts":["expensive","on sale","big","bought with cash"],"decode":["teuer","im Angebot","groß","bar bezahlt"],"correct":0}],"solutionEn":"expensive","solutionDe":"teuer","explain":"bargain = Schnäppchen. Ein Schnäppchen ist gerade NICHT teuer."},{"parts":["Which of the following things does a 'cashier' usually do? ",{"opts":["give away things for free","browse","go shopping","take your money"],"decode":["Dinge gratis hergeben","stöbern","einkaufen gehen","dein Geld entgegennehmen"],"correct":3}],"solutionEn":"take your money","solutionDe":"dein Geld entgegennehmen","explain":"cashier = Kassier/Kassiererin. An der Kassa nimmt er/sie dein Geld entgegen."},{"parts":["A book costs $5.99 and you pay $6. What should you get? ",{"opts":["special offers","change","a clerk","a cash register"],"decode":["Sonderangebote","Wechselgeld","einen Verkäufer","eine Registrierkasse"],"correct":1}],"solutionEn":"change","solutionDe":"Wechselgeld","explain":"change = Wechselgeld. Du bekommst 1 Cent zurück. Achtung: change heißt auch 'wechseln/ändern'."},{"parts":["Which of the following things can you do with a 'debit card'? ",{"opts":["find a clerk to help you","find out someone's name","buy a bag of apples","find out the price of a sweater"],"decode":["einen Verkäufer finden, der dir hilft","den Namen von jemandem herausfinden","ein Sackerl Äpfel kaufen","den Preis eines Pullovers herausfinden"],"correct":2}],"solutionEn":"buy a bag of apples","solutionDe":"ein Sackerl Äpfel kaufen","explain":"debit card = Bankomatkarte. Damit bezahlt man – also kann man damit etwas kaufen."},{"parts":["What do you do when you 'exchange' a product? ",{"opts":["you replace it with another product","you look at it very carefully","you sell it to a customer","you put it inside a box"],"decode":["du ersetzt es durch ein anderes Produkt","du schaust es dir sehr genau an","du verkaufst es an einen Kunden","du legst es in eine Schachtel"],"correct":0}],"solutionEn":"you replace it with another product","solutionDe":"du ersetzt es durch ein anderes Produkt","explain":"exchange = umtauschen, also ein Produkt durch ein anderes ersetzen."},{"parts":["Which of the following things do people usually do in a 'fitting room'? ",{"opts":["they look at bar codes","they talk to other customers","they try on clothes","they buy things"],"decode":["sie schauen sich Strichcodes an","sie reden mit anderen Kunden","sie probieren Kleidung an","sie kaufen Dinge"],"correct":2}],"solutionEn":"they try on clothes","solutionDe":"sie probieren Kleidung an","explain":"fitting room = Umkleidekabine; try on = anprobieren."},{"parts":["Which of the following things do you do when you 'purchase' something? ",{"opts":["you return it","you advertise it","you sell it","you buy it"],"decode":["du gibst es zurück","du bewirbst es","du verkaufst es","du kaufst es"],"correct":3}],"solutionEn":"you buy it","solutionDe":"du kaufst es","explain":"purchase = kaufen (formelleres Wort für buy). Als Nomen: a purchase = ein Kauf."},{"parts":["When do people usually get a 'receipt'? ",{"opts":["before they buy a used car","before they check out","when they get a shopping basket","after they buy something"],"decode":["bevor sie einen Gebrauchtwagen kaufen","bevor sie zur Kassa gehen","wenn sie einen Einkaufskorb nehmen","nachdem sie etwas gekauft haben"],"correct":3}],"solutionEn":"after they buy something","solutionDe":"nachdem sie etwas gekauft haben","explain":"receipt = Kassenbeleg/Rechnung. Den bekommt man NACH dem Bezahlen."},{"parts":["Which of the following words is closest in meaning to 'shoplift'? ",{"opts":["steal","break","buy","use"],"decode":["stehlen","zerbrechen","kaufen","benutzen"],"correct":0}],"solutionEn":"steal","solutionDe":"stehlen","explain":"shoplift = Ladendiebstahl begehen, also etwas aus einem Geschäft stehlen. shoplifter = Ladendieb."},{"parts":["Which of the following things can you do with a 'shopping cart'? ",{"opts":["you can give it your credit card","you can put things in it","you can ask it to help you","you can drive it"],"decode":["du kannst ihm deine Kreditkarte geben","du kannst Dinge hineinlegen","du kannst ihn um Hilfe bitten","du kannst ihn fahren (wie ein Auto)"],"correct":1}],"solutionEn":"you can put things in it","solutionDe":"du kannst Dinge hineinlegen","explain":"shopping cart = Einkaufswagen (BE: trolley). Man legt seine Waren hinein."},{"parts":["What does 'store hours' mean? ",{"opts":["the time when the store is open","the time when there is a sale","the time when the store is closed","the time when the store is very busy"],"decode":["die Zeit, in der das Geschäft offen ist","die Zeit, in der es einen Ausverkauf gibt","die Zeit, in der das Geschäft geschlossen ist","die Zeit, in der das Geschäft sehr voll ist"],"correct":0}],"solutionEn":"the time when the store is open","solutionDe":"die Zeit, in der das Geschäft geöffnet ist","explain":"store hours = Öffnungszeiten (BE auch: opening hours)."},{"parts":["Which of the following things is an example of 'weight'? ",{"opts":["55 grams","14 kilograms","12 ounces","all of the above"],"decode":["55 Gramm","14 Kilogramm","12 Unzen","alles oben Genannte"],"correct":3}],"solutionEn":"all of the above","solutionDe":"alles oben Genannte","explain":"weight = Gewicht. Gramm, Kilogramm und Unzen (ounces) sind alle Gewichtseinheiten."},{"parts":["When they go 'window shopping', people usually … ",{"opts":["buy windows","spend a lot of money","buy nothing","none of the above"],"decode":["kaufen Fenster","geben viel Geld aus","kaufen nichts","nichts davon"],"correct":2}],"solutionEn":"buy nothing","solutionDe":"kaufen nichts","explain":"window shopping = Schaufensterbummel: nur schauen, nichts kaufen."}]},{"id":"shop_ex02","title":"Shops and Services","source":"Shopping_Part1 – Geschäfte (eigene Übungssätze)","type":"gap","instruction":"Wähle das passende Geschäft.","questions":[{"parts":["If you want fresh salmon for dinner, go to the ",{"opts":["greengrocer's","fishmonger's","florist"],"decode":["Obst- und Gemüsehändler","Fischhändler","Blumenhändler"],"correct":1},"."],"solutionEn":"fishmonger's","solutionDe":"Fischhändler / Fischgeschäft","explain":"salmon = Lachs → frischen Fisch kauft man beim fishmonger's."},{"parts":["I never buy fruit at the supermarket – I prefer the ",{"opts":["greengrocer's","off licence","optician"],"decode":["Obst- und Gemüsehändler","Spirituosenhandlung","Optiker"],"correct":0}," around the corner."],"solutionEn":"greengrocer's","solutionDe":"Obst- und Gemüsehändler","explain":"greengrocer's = Obst- und Gemüsegeschäft. Merkhilfe: green = Gemüse/Obst."},{"parts":["She bought a beautiful bunch of roses for her mum at the ",{"opts":["fishmonger's","florist","optician"],"decode":["Fischhändler","Blumenhändler","Optiker"],"correct":1},"."],"solutionEn":"florist","solutionDe":"Blumenhändler / Blumengeschäft","explain":"a bunch of roses = ein Rosenstrauß → den kauft man beim florist (Blumengeschäft)."},{"parts":["In Britain you can only buy wine and beer to take home at an ",{"opts":["outdoor market","optician","off licence"],"decode":["Markt im Freien","Optiker","Spirituosenhandlung"],"correct":2},"."],"solutionEn":"off licence","solutionDe":"Wein- und Spirituosenhandlung","explain":"off licence = britisches Geschäft mit Lizenz, Alkohol zum Mitnehmen ('off' the premises) zu verkaufen."},{"parts":["My eyesight has got worse, so I'm going to the ",{"opts":["florist","optician","cashier"],"decode":["Blumenhändler","Optiker","Kassier"],"correct":1}," to get new glasses."],"solutionEn":"optician","solutionDe":"Optiker","explain":"eyesight = Sehkraft, glasses = Brille → optician = Optiker."}]},{"id":"shop_ex03","title":"Shopping Habits","source":"Shopping_Part1 – Vokabeln in Kontextsätzen (eigene Übungssätze)","type":"gap","instruction":"Wähle das Wort oder den Ausdruck, der in den Satz passt.","questions":[{"parts":["Before buying a new laptop, you should ",{"opts":["check out","shop around","shoplift"],"decode":["an der Kassa bezahlen","Preise vergleichen","Ladendiebstahl begehen"],"correct":1}," and compare prices in different stores."],"solutionEn":"shop around","solutionDe":"sich umsehen / Preise vergleichen","explain":"shop around = in mehreren Geschäften Preise und Angebote vergleichen, bevor man kauft."},{"parts":["We didn't want to buy anything – we just went ",{"opts":["window shopping","grocery shopping","online shopping"],"decode":["Schaufensterbummeln","Lebensmittel einkaufen","online einkaufen"],"correct":0}," and looked at the beautiful shop windows."],"solutionEn":"window shopping","solutionDe":"Schaufensterbummel","explain":"go window shopping = einen Schaufensterbummel machen – schauen ohne zu kaufen."},{"parts":["I didn't plan to buy this T-shirt at all – it was a typical ",{"opts":["special offer","shopping list","impulse purchase"],"decode":["Sonderangebot","Einkaufsliste","Impulskauf"],"correct":2},"."],"solutionEn":"impulse purchase","solutionDe":"Impulskauf / Spontankauf","explain":"impulse purchase = ungeplanter Spontankauf. Person dazu: impulse buyer."},{"parts":["The fridge is empty, so I have to do the ",{"opts":["window shopping","grocery shopping","Christmas shopping"],"decode":["Schaufensterbummel","Lebensmitteleinkauf","Weihnachtseinkäufe"],"correct":1}," this afternoon."],"solutionEn":"grocery shopping","solutionDe":"Lebensmitteleinkauf","explain":"grocery shopping = shopping for food, also der Einkauf von Lebensmitteln. fridge = Kühlschrank."},{"parts":["The trousers didn't fit, so I had to ",{"opts":["purchase","exchange","return"],"decode":["kaufen","umtauschen","zurückbringen"],"correct":2}," them to the store."],"solutionEn":"return","solutionDe":"zurückbringen","explain":"return something to the store = etwas ins Geschäft zurückbringen. 'exchange' passt grammatikalisch nicht zu 'to the store' (man sagt: exchange it FOR something else)."},{"parts":["Many people take advantage of major shopping days like ",{"opts":["Boxing Day","Black Friday","Easter Monday"],"decode":["Stefanitag (26.12.)","Black Friday","Ostermontag"],"correct":1}," in November."],"solutionEn":"Black Friday","solutionDe":"Black Friday (großer Rabatt-Tag Ende November)","explain":"take advantage of = ausnutzen/profitieren von. Der Black Friday ist Ende November – Boxing Day (26.12.) und Easter Monday passen nicht zu 'in November'."}]}]}]};
